window.trendingPapers = {
    "today": [{"paper": {"id": "2610.33106", "authors": [{"_id": "6ae1a17ea5eb0647c29075f9", "name": "Wenbo Hu", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075fa", "name": "Ken Li", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075fb", "name": "Jiazhe Wei", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075fc", "name": "Yukang Cao", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075fd", "name": "Weiyi Hong", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075fe", "name": "Jiayi Dai", "hidden": false}, {"_id": "6ae1a17ea5eb0647c29075ff", "name": "Chenjun Bai", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907600", "name": "Jiajun Liang", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907601", "name": "Yucheng Liao", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907602", "name": "Ruichuan An", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907603", "name": "Zeyu Lou", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907604", "name": "Haofan Wang", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907605", "name": "Yueming Lyu", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907606", "name": "Jingkang Yang", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907607", "name": "Ziwei Liu", "hidden": false}, {"_id": "6ae1a17ea5eb0647c2907608", "name": "Chenyang Si", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6754f9eea4b0a4a71aeed438/OzwrI14ADhCGtWx7Uw--5.mp4"], "publishedAt": "2026-10-22T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "VibeGame: Prompt-to-Game Development with AI-Native Engine and Self-Evolving Adversarial Agent Team", "submittedOnDailyBy": {"_id": "6754f9eea4b0a4a71aeed438", "avatarUrl": "/avatars/442646a6acae514cebf30bb51681394c.svg", "isPro": false, "fullname": "Jiazhe Wei", "user": "void-2024", "type": "user", "name": "void-2024"}, "summary": "Large language model agents have enabled software development through natural-language interaction, but extending this paradigm to end-to-end game development remains challenging. Building a playable game requires coordinating code, scenes, assets, animations, physics, and configurations, while allowing developers to validate their integrated behavior through interactive testing. We introduce VibeGame, a framework for creating complete 2D game projects from natural-language prompts and optional reference images. Its AI-native game engine represents project state as schema-validated structured text and provides frame-synchronous runtime control, enabling agents to inspect game states, execute actions, and verify behavior at their own pace. Built upon this interface, we design an Adversarial Agent Team of eight specialized agents to separate implementation from review, so that problems are found and fixed through multi-round loops. For each conducted and accepted project, we further introduce a training-free self-evolution mechanism to distill it into reusable skeletons, modules, and collaboration contracts for future development. We evaluate prompt-assets-to-game (PA2G), where agents are given an asset library, and prompt-to-game (P2G), where agents generate their own art. On a GameCraft-Bench subset, VibeGame in P2G consistently outperforms a range of agent harnesses in either P2G or PA2G with the same underlying model, including GPT-6.1-Sol.", "upvotes": 11, "discussionId": "6ae1a17ea5eb0647c2907609", "projectPage": "https://vibegame.tettet.org", "githubRepo": "https://github.com/tettethu/VibeGame", "githubRepoAddedBy": "user", "ai_summary": "VibeGame is a framework that uses specialized adversarial agents and an AI-native engine to build complete 2D games from natural-language prompts with interactive validation and self-evolving reusable components.", "ai_keywords": ["large language model agents", "adversarial agent team", "AI-native game engine", "schema-validated structured text", "frame-synchronous runtime control", "self-evolution mechanism", "skeletons", "modules", "collaboration contracts", "PA2G", "P2G"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 284, "organization": {"_id": "638f70e8f1256a80d4288555", "name": "nanjinguniv", "fullname": "Nanjing University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/638f706ef1256a80d42880f9/6M6-JzwJGiLxjIJzvCflf.png"}, "summary_zh": "<ul>\n    <li>VibeGame\u662f\u4e00\u4e2a\u6846\u67b6\uff0c\u53ef\u4ee5\u901a\u8fc7\u81ea\u7136\u8bed\u8a00\u63d0\u793a\u548c\u53c2\u8003\u56fe\u50cf\u521b\u5efa\u5b8c\u6574\u76842D\u6e38\u620f\u9879\u76ee\u3002</li>\n    <li>\u8be5\u6846\u67b6\u4f7f\u7528AI\u539f\u751f\u6e38\u620f\u5f15\u64ce\uff0c\u80fd\u591f\u4ee5\u7ed3\u6784\u5316\u6587\u672c\u5f62\u5f0f\u8868\u793a\u9879\u76ee\u72b6\u6001\uff0c\u5e76\u63d0\u4f9b\u540c\u6b65\u8fd0\u884c\u63a7\u5236\u3002</li>\n    <li>\u8bbe\u8ba1\u4e86\u4e00\u4e2a\u7531\u516b\u4e2a\u4e13\u95e8\u4ee3\u7406\u7ec4\u6210\u7684\u5bf9\u6297\u4ee3\u7406\u56e2\u961f\uff0c\u901a\u8fc7\u591a\u8f6e\u5faa\u73af\u53d1\u73b0\u548c\u4fee\u590d\u95ee\u9898\u3002</li>\n    <li>VibeGame\u8fd8\u5f15\u5165\u4e86\u4e00\u79cd\u81ea\u6211\u8fdb\u5316\u673a\u5236\uff0c\u5c06\u9879\u76ee\u63d0\u70bc\u4e3a\u53ef\u91cd\u7528\u7684\u9aa8\u67b6\u3001\u6a21\u5757\u548c\u5408\u4f5c\u534f\u8bae\u3002</li>\n    <li>\u5728GameCraft-Bench\u7684\u6d4b\u8bd5\u4e2d\uff0cVibeGame\u5728\u751f\u6210\u6e38\u620f\u65b9\u9762\u8868\u73b0\u4f18\u4e8e\u5176\u4ed6\u4ee3\u7406\u7cfb\u7edf\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>VibeGame is a new framework that helps create 2D games using natural language prompts and reference images.</li>\n    <li>The framework manages various aspects of game development like code, scenes, and assets, allowing for interactive testing.</li>\n    <li>It features an AI engine that lets agents check game states and perform actions at their own speed.</li>\n    <li>An Adversarial Agent Team of eight specialized agents helps identify and fix problems through repeated reviews.</li>\n    <li>VibeGame's performance is better than other systems in creating games from prompts and assets, using the same AI model.</li>\n</ul>"}, "publishedAt": "2026-10-21T20:00:00.000Z", "title": "VibeGame: Prompt-to-Game Development with AI-Native Engine and Self-Evolving Adversarial Agent Team", "summary": "Large language model agents have enabled software development through natural-language interaction, but extending this paradigm to end-to-end game development remains challenging. Building a playable game requires coordinating code, scenes, assets, animations, physics, and configurations, while allowing developers to validate their integrated behavior through interactive testing. We introduce VibeGame, a framework for creating complete 2D game projects from natural-language prompts and optional reference images. Its AI-native game engine represents project state as schema-validated structured text and provides frame-synchronous runtime control, enabling agents to inspect game states, execute actions, and verify behavior at their own pace. Built upon this interface, we design an Adversarial Agent Team of eight specialized agents to separate implementation from review, so that problems are found and fixed through multi-round loops. For each conducted and accepted project, we further introduce a training-free self-evolution mechanism to distill it into reusable skeletons, modules, and collaboration contracts for future development. We evaluate prompt-assets-to-game (PA2G), where agents are given an asset library, and prompt-to-game (P2G), where agents generate their own art. On a GameCraft-Bench subset, VibeGame in P2G consistently outperforms a range of agent harnesses in either P2G or PA2G with the same underlying model, including GPT-6.1-Sol.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6754f9eea4b0a4a71aeed438/OzwrI14ADhCGtWx7Uw--5.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.33106.png", "numComments": 1, "submittedBy": {"_id": "6754f9eea4b0a4a71aeed438", "avatarUrl": "/avatars/442646a6acae514cebf30bb51681394c.svg", "fullname": "Jiazhe Wei", "name": "void-2024", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "638f70e8f1256a80d4288555", "name": "nanjinguniv", "fullname": "Nanjing University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/638f706ef1256a80d42880f9/6M6-JzwJGiLxjIJzvCflf.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.38352", "authors": [{"_id": "6ae3f93cc3b566b041f6c763", "name": "Chenyu Mu", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c764", "name": "Wenming Weng", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c765", "name": "Qinrui Wang", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c766", "name": "Xingsong Ye", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c767", "name": "Hao Yu", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c768", "name": "Jun He", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c769", "name": "Chong Sun", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c76a", "name": "Chen Li", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c76b", "name": "Jing Lyu", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c76c", "name": "Erkun Yang", "hidden": false}, {"_id": "6ae3f93cc3b566b041f6c76d", "name": "Cheng Deng", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/674d092c6421c58761fc83eb/EPvuXyet_XWaE9a0yEUGt.png", "https://cdn-uploads.huggingface.co/production/uploads/674d092c6421c58761fc83eb/xfvmV1KbAmbGilu2ktmtg.mp4"], "publishedAt": "2026-10-28T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "WeVisCut: The Whole Editing Room in One Agent From Narration to Long-Form Video", "submittedOnDailyBy": {"_id": "674d092c6421c58761fc83eb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/674d092c6421c58761fc83eb/lQSRWX_YyTzpRq2aJtwYT.png", "isPro": false, "fullname": "Xingsong Ye", "user": "Yesianrohn", "type": "user", "name": "Yesianrohn"}, "summary": "Producing long-form videos from narration requires interdependent decisions that remain coherent across shots. Existing agentic editors often use multi-stage workflows driven by general models, leaving the quality-cost trade-off of compact, task-adapted policies unclear. We address this gap with WeVisCut, a long-form script-to-video system that connects tool execution with policy learning. Its agent harness maintains shared production state so that tool feedback informs subsequent decisions and repairs. Because finished videos do not expose these decisions, our four-stage data pipeline combines editing inversion with verified replay to turn recovered editing intent into executable supervision. Applied to 3,750 finished videos, this pipeline yields over 130K training examples. We use this supervision to train a single 9B policy that coordinates production and recovers from failures within the same harness. Moreover, we introduce a 100-task benchmark and five metrics assessing editing quality and delivery reliability. Under a shared tool environment, WeVisCut substantially outperforms its base model and achieves comparable performance to Claude Opus 5 while using nearly 33x fewer generated tokens per successful output minute. It also outperforms task-matched native editors on our proposed metrics.", "upvotes": 9, "discussionId": "6ae3f93dc3b566b041f6c76e", "projectPage": "https://tencent.github.io/WeVisCut", "githubRepo": "https://github.com/Tencent/WeVisCut", "githubRepoAddedBy": "user", "ai_summary": "WeVisCut is a script-to-video system that trains a compact policy to coordinate video editing tools, recover from failures, and reduce token usage while maintaining quality.", "ai_keywords": ["agentic editors", "policy learning", "shared production state", "editing inversion", "verified replay", "executable supervision", "9B policy", "100-task benchmark", "token efficiency"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 2, "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "summary_zh": "<ul>\n    <li>WeVisCut \u662f\u4e00\u4e2a\u5c06\u811a\u672c\u8f6c\u5316\u4e3a\u957f\u89c6\u9891\u7684\u7cfb\u7edf\uff0c\u80fd\u591f\u5904\u7406\u591a\u4e2a\u955c\u5934\u95f4\u7684\u51b3\u7b56\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u7ed3\u5408\u4e86\u5de5\u5177\u6267\u884c\u548c\u7b56\u7565\u5b66\u4e60\uff0c\u786e\u4fdd\u7f16\u8f91\u8fc7\u7a0b\u4e2d\u7684\u4e00\u81f4\u6027\u3002</li>\n    <li>\u901a\u8fc7\u5bf93750\u4e2a\u5b8c\u6210\u89c6\u9891\u7684\u6570\u636e\u5904\u7406\uff0c\u751f\u6210\u4e86\u8d85\u8fc713\u4e07\u4e2a\u8bad\u7ec3\u5b9e\u4f8b\u3002</li>\n    <li>WeVisCut \u4f7f\u7528\u4e00\u4e2a9B\u7684\u7b56\u7565\u6a21\u578b\u6765\u534f\u8c03\u5236\u4f5c\u8fc7\u7a0b\uff0c\u5e76\u80fd\u4ece\u9519\u8bef\u4e2d\u6062\u590d\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u5728\u7f16\u8f91\u8d28\u91cf\u548c\u4ea4\u4ed8\u53ef\u9760\u6027\u65b9\u9762\u8868\u73b0\u4f18\u4e8e\u57fa\u7ebf\u6a21\u578b\uff0c\u5e76\u4e14\u6709\u6548\u51cf\u5c11\u4e86\u751f\u6210\u7684\u6807\u8bb0\u6570\u91cf\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>WeVisCut is a new system for creating long videos from scripts, focusing on making smoother editing decisions across different video shots.</li>\n    <li>The system improves video production by learning from previous editing choices and fixing mistakes as it goes along.</li>\n    <li>It uses a special data process to create over 130,000 examples from finished videos, which helps train a powerful editing policy.</li>\n    <li>WeVisCut performs significantly better than its basic model and is as effective as a leading competitor while using much less computing power.</li>\n    <li>It also surpasses traditional video editing tools in terms of quality and reliability based on new evaluation metrics.</li>\n</ul>"}, "publishedAt": "2026-10-27T20:00:00.000Z", "title": "WeVisCut: The Whole Editing Room in One Agent From Narration to Long-Form Video", "summary": "Producing long-form videos from narration requires interdependent decisions that remain coherent across shots. Existing agentic editors often use multi-stage workflows driven by general models, leaving the quality-cost trade-off of compact, task-adapted policies unclear. We address this gap with WeVisCut, a long-form script-to-video system that connects tool execution with policy learning. Its agent harness maintains shared production state so that tool feedback informs subsequent decisions and repairs. Because finished videos do not expose these decisions, our four-stage data pipeline combines editing inversion with verified replay to turn recovered editing intent into executable supervision. Applied to 3,750 finished videos, this pipeline yields over 130K training examples. We use this supervision to train a single 9B policy that coordinates production and recovers from failures within the same harness. Moreover, we introduce a 100-task benchmark and five metrics assessing editing quality and delivery reliability. Under a shared tool environment, WeVisCut substantially outperforms its base model and achieves comparable performance to Claude Opus 5 while using nearly 33x fewer generated tokens per successful output minute. It also outperforms task-matched native editors on our proposed metrics.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/674d092c6421c58761fc83eb/EPvuXyet_XWaE9a0yEUGt.png", "https://cdn-uploads.huggingface.co/production/uploads/674d092c6421c58761fc83eb/xfvmV1KbAmbGilu2ktmtg.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.38352.png", "numComments": 1, "submittedBy": {"_id": "674d092c6421c58761fc83eb", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/674d092c6421c58761fc83eb/lQSRWX_YyTzpRq2aJtwYT.png", "fullname": "Xingsong Ye", "name": "Yesianrohn", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.38425", "authors": [{"_id": "6ae407efc3b566b041f6c7e8", "name": "Shaohan Yu", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7e9", "name": "Jie Qin", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7ea", "name": "Wende Tan", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7eb", "name": "Haiwen Diao", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7ec", "name": "Limeng Qiao", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7ed", "name": "Yueming Lyu", "hidden": false}, {"_id": "6ae407efc3b566b041f6c7ee", "name": "Chenyang Si", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/68f59ae49315a06ad9a01464/PYZEmEPPaR8PFmfG5Ct5U.mp4"], "publishedAt": "2026-10-28T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "IntReal: A Real-World Dataset and Benchmark for Multimodal Interleaved Generation", "submittedOnDailyBy": {"_id": "68f59ae49315a06ad9a01464", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/68f59ae49315a06ad9a01464/welpgtUr6TY9Qa7nPBigg.jpeg", "isPro": true, "fullname": "Sean Yu", "user": "yushaohan", "type": "user", "name": "yushaohan"}, "summary": "Humans routinely consume multimodal content, where textual and visual information is naturally interleaved. Although Unified Multimodal Models (UMMs) can jointly generate text and images, multimodal interleaved generation remains largely underexplored. Progress in this area is hindered by two key limitations: (1) the lack of well-defined interleaved generation tasks and corresponding training data, and (2) the absence of fine-grained evaluation protocols that can reliably diagnose model performance across different capability dimensions. To this end, we present IntReal, comprising two complementary components: IntReal-100K, a real-world dataset of multimodal interleaved samples spanning four major categories, and the IntReal Evaluation Suite, which evaluates model performance across seven complementary dimensions using specialized expert models, enabling coarse-to-fine diagnosis. Extensive experiments validate our evaluation suite through low inter-metric redundancy (max pairwise absolute Spearman's \u03c1leq 0.42 ), high agreement with human judgments (83.3% accuracy), and strong consistency across different expert evaluators (Spearman's \u03c1> 0.9 ), supporting the complementarity and reliability of our metrics. By benchmarking four families of UMMs, we show that IntReal Evaluation Suite reveals distinct strengths and weaknesses across models. Post-training experiments demonstrate the utility of IntReal-100K for improving interleaved generation and further show that training unimodal generation can also benefit interleaved generation. These findings suggest that interleaved generation can benefit from modality-specific optimization, rather than requiring joint text-image training at every stage.", "upvotes": 8, "discussionId": "6ae407efc3b566b041f6c7ef", "projectPage": "https://yushaohan.github.io/IntReal/", "githubRepo": "https://github.com/yushaohan/IntReal", "githubRepoAddedBy": "user", "ai_summary": "IntReal introduces a real-world interleaved multimodal dataset and evaluation framework to diagnose unified model strengths and improve generation through targeted training.", "ai_keywords": ["Unified Multimodal Models", "interleaved generation", "IntReal-100K", "IntReal Evaluation Suite", "expert models", "Spearman's correlation"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 2, "organization": {"_id": "68b28d79a176a9beb30d2049", "name": "meituan-longcat", "fullname": "LongCat", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68a2a29ab9d4c5698e02c747/CDCAx7X7rXDt7xjI-DoxG.png"}, "summary_zh": "<ul>\n    <li>\u4eba\u7c7b\u7ecf\u5e38\u6d88\u8d39\u6587\u672c\u548c\u89c6\u89c9\u4fe1\u606f\u4ea4\u7ec7\u7684\u591a\u6a21\u6001\u5185\u5bb9\u3002</li>\n    <li>\u73b0\u6709\u7684\u7edf\u4e00\u591a\u6a21\u6001\u6a21\u578b\uff08UMMs\uff09\u80fd\u591f\u751f\u6210\u6587\u672c\u548c\u56fe\u50cf\uff0c\u4f46\u4ea4\u7ec7\u751f\u6210\u7684\u7814\u7a76\u4ecd\u8f83\u5c11\u3002</li>\n    <li>\u7814\u7a76\u8fdb\u5c55\u53d7\u9650\u4e8e\u7f3a\u4e4f\u660e\u786e\u7684\u4ea4\u7ec7\u751f\u6210\u4efb\u52a1\u548c\u8bad\u7ec3\u6570\u636e\uff0c\u4ee5\u53ca\u7f3a\u5c11\u53ef\u9760\u7684\u8bc4\u4f30\u6807\u51c6\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86IntReal\uff0c\u5305\u62ec\u4e00\u4e2a\u5305\u542b10\u4e07\u4e2a\u771f\u5b9e\u6837\u672c\u7684\u591a\u6a21\u6001\u6570\u636e\u96c6\u548c\u8bc4\u4f30\u5de5\u5177\uff0c\u80fd\u591f\u4ece\u591a\u4e2a\u7ef4\u5ea6\u8bc4\u4f30\u6a21\u578b\u6027\u80fd\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cIntReal\u80fd\u591f\u6709\u6548\u63ed\u793a\u4e0d\u540c\u6a21\u578b\u7684\u4f18\u7f3a\u70b9\uff0c\u5e76\u4e14\u901a\u8fc7\u7279\u5b9a\u7684\u8bad\u7ec3\u4f18\u5316\u4ea4\u7ec7\u751f\u6210\u6548\u679c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Humans often consume content that mixes text and images, but creating models that can generate this type of content together is still not well-developed.</li>\n    <li>Two main challenges are the lack of clear tasks and training data for interleaved generation, and the need for better evaluation methods to assess model performance.</li>\n    <li>The authors introduce IntReal, which includes a dataset (IntReal-100K) with real-world examples of mixed content and a robust evaluation system that measures model performance across several areas.</li>\n    <li>Tests show that the evaluation suite is reliable, aligning closely with human judgments and providing consistent results across different evaluators.</li>\n    <li>Results from testing various models reveal their strengths and weaknesses, and the dataset can help improve the generation of interleaved content, suggesting that focusing on specific types of content can be more beneficial than training models together all the time.</li>\n</ul>"}, "publishedAt": "2026-10-27T20:00:00.000Z", "title": "IntReal: A Real-World Dataset and Benchmark for Multimodal Interleaved Generation", "summary": "Humans routinely consume multimodal content, where textual and visual information is naturally interleaved. Although Unified Multimodal Models (UMMs) can jointly generate text and images, multimodal interleaved generation remains largely underexplored. Progress in this area is hindered by two key limitations: (1) the lack of well-defined interleaved generation tasks and corresponding training data, and (2) the absence of fine-grained evaluation protocols that can reliably diagnose model performance across different capability dimensions. To this end, we present IntReal, comprising two complementary components: IntReal-100K, a real-world dataset of multimodal interleaved samples spanning four major categories, and the IntReal Evaluation Suite, which evaluates model performance across seven complementary dimensions using specialized expert models, enabling coarse-to-fine diagnosis. Extensive experiments validate our evaluation suite through low inter-metric redundancy (max pairwise absolute Spearman's \u03c1leq 0.42 ), high agreement with human judgments (83.3% accuracy), and strong consistency across different expert evaluators (Spearman's \u03c1> 0.9 ), supporting the complementarity and reliability of our metrics. By benchmarking four families of UMMs, we show that IntReal Evaluation Suite reveals distinct strengths and weaknesses across models. Post-training experiments demonstrate the utility of IntReal-100K for improving interleaved generation and further show that training unimodal generation can also benefit interleaved generation. These findings suggest that interleaved generation can benefit from modality-specific optimization, rather than requiring joint text-image training at every stage.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/68f59ae49315a06ad9a01464/PYZEmEPPaR8PFmfG5Ct5U.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.38425.png", "numComments": 1, "submittedBy": {"_id": "68f59ae49315a06ad9a01464", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/68f59ae49315a06ad9a01464/welpgtUr6TY9Qa7nPBigg.jpeg", "fullname": "Sean Yu", "name": "yushaohan", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "68b28d79a176a9beb30d2049", "name": "meituan-longcat", "fullname": "LongCat", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68a2a29ab9d4c5698e02c747/CDCAx7X7rXDt7xjI-DoxG.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.37786", "authors": [{"_id": "6ae3fbe1c3b566b041f6c78c", "name": "Tianci Xie", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c78d", "name": "Zikun Cai", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c78e", "name": "Chaoyun Zhang", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c78f", "name": "Pinxue Guo", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c790", "name": "Bingxuan Li", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c791", "name": "Rui Zheng", "hidden": false}, {"_id": "6ae3fbe1c3b566b041f6c792", "name": "Hang Yan", "hidden": false}], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "WebAnything: From the Wild Web to Scalable Agent Environments", "submittedOnDailyBy": {"_id": "654dbac9938fbf1e696be8aa", "avatarUrl": "/avatars/185c57abc99caa4aedaaf342f4a65f75.svg", "isPro": false, "fullname": "Chaoyun Zhang", "user": "vyokky", "type": "user", "name": "vyokky"}, "summary": "Web agents require diverse, executable, and resettable website environments for reproducible training and evaluation. Human-assisted mirrors demand per-site engineering, while generative construction can diverge from specified real websites. Capture-and-replay preserves observations, with interaction coverage constrained by captured content and replay capabilities.\n  We present WebAnything, a fully automated framework that reconstructs source-grounded, reusable Web environments from real URLs without per-site manual implementation or repair after initial setup and authorization. An Explorer-Builder collects browser-observable structures, resources, and interaction outcomes; an independent verifier checks frozen candidates and guides local repair or targeted source recapture.\n  We construct 244 website artifacts across 14 application domains and 53 categories, supporting 12,984 executed and accepted tasks. Compared with human-assisted WebHarbor, WebAnything achieves higher aggregate scores on three fidelity metrics, with 12 wins, two ties, and no losses in a blind audit. Fine-tuning Qwen3.5-9B on 5,856 interaction trajectories improves REAL success by 9.9 percentage points, Odysseys-Easy Rubric Avg and Task Avg by 6.25 and 6.32 percentage points, and WebArena-Verified Overall success by 13.33 percentage points under the fixed harness. Code: https://github.com/china-qijizhifeng/Web-Anything", "upvotes": 8, "discussionId": "6ae3fbe2c3b566b041f6c793", "projectPage": "https://china-qijizhifeng.github.io/Web-Anything/", "githubRepo": "https://github.com/china-qijizhifeng/Web-Anything", "githubRepoAddedBy": "user", "ai_summary": "WebAnything automates the reconstruction of reusable, source-grounded web environments from real URLs, enabling scalable agent training and evaluation with verified fidelity.", "ai_keywords": ["WebAnything", "Explorer-Builder", "frozen candidates", "source recapture", "interaction trajectories", "Qwen3.5-9B", "REAL success", "WebArena-Verified"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 1, "summary_zh": "<ul>\n    <li>WebAnything\u662f\u4e00\u4e2a\u81ea\u52a8\u5316\u6846\u67b6\uff0c\u53ef\u4ee5\u4ece\u771f\u5b9e\u7f51\u5740\u91cd\u5efa\u53ef\u91cd\u590d\u4f7f\u7528\u7684\u7f51\u7ad9\u73af\u5883\u3002</li>\n    <li>\u8be5\u6846\u67b6\u4e0d\u9700\u8981\u4eba\u5de5\u5bf9\u6bcf\u4e2a\u7f51\u7ad9\u8fdb\u884c\u8bbe\u7f6e\u6216\u4fee\u590d\uff0c\u521d\u59cb\u8bbe\u7f6e\u548c\u6388\u6743\u540e\u5373\u53ef\u4f7f\u7528\u3002</li>\n    <li>\u901a\u8fc7Explorer-Builder\u6536\u96c6\u6d4f\u89c8\u5668\u53ef\u89c2\u5bdf\u5230\u7684\u7ed3\u6784\u3001\u8d44\u6e90\u548c\u4ea4\u4e92\u7ed3\u679c\uff0c\u72ec\u7acb\u9a8c\u8bc1\u8005\u68c0\u67e5\u5019\u9009\u7f51\u7ad9\u7684\u6709\u6548\u6027\u3002</li>\n    <li>\u6211\u4eec\u6784\u5efa\u4e86244\u4e2a\u7f51\u7ad9\u5de5\u4ef6\uff0c\u652f\u6301\u8d85\u8fc712,000\u4e2a\u6267\u884c\u548c\u63a5\u53d7\u7684\u4efb\u52a1\uff0c\u8868\u73b0\u4f18\u4e8e\u4eba\u7c7b\u52a9\u624bWebHarbor\u3002</li>\n    <li>\u5728\u6027\u80fd\u8bc4\u4f30\u4e2d\uff0cWebAnything\u5728\u591a\u4e2a\u6307\u6807\u4e0a\u53d6\u5f97\u4e86\u663e\u8457\u63d0\u5347\uff0c\u663e\u793a\u4e86\u5176\u5f3a\u5927\u7684\u80fd\u529b\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>WebAnything is an automated system that creates reusable website environments from real URLs without needing manual setup.</li>\n    <li>The framework includes an Explorer-Builder that gathers website data and a verifier that checks and repairs the collected information.</li>\n    <li>WebAnything successfully constructed 244 website artifacts across various categories, handling nearly 13,000 tasks.</li>\n    <li>It outperformed a human-assisted system (WebHarbor) in blind tests, achieving better scores on several metrics.</li>\n    <li>Fine-tuning a model on interaction data improved success rates significantly across multiple evaluation criteria.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "WebAnything: From the Wild Web to Scalable Agent Environments", "summary": "Web agents require diverse, executable, and resettable website environments for reproducible training and evaluation. Human-assisted mirrors demand per-site engineering, while generative construction can diverge from specified real websites. Capture-and-replay preserves observations, with interaction coverage constrained by captured content and replay capabilities.\n  We present WebAnything, a fully automated framework that reconstructs source-grounded, reusable Web environments from real URLs without per-site manual implementation or repair after initial setup and authorization. An Explorer-Builder collects browser-observable structures, resources, and interaction outcomes; an independent verifier checks frozen candidates and guides local repair or targeted source recapture.\n  We construct 244 website artifacts across 14 application domains and 53 categories, supporting 12,984 executed and accepted tasks. Compared with human-assisted WebHarbor, WebAnything achieves higher aggregate scores on three fidelity metrics, with 12 wins, two ties, and no losses in a blind audit. Fine-tuning Qwen3.5-9B on 5,856 interaction trajectories improves REAL success by 9.9 percentage points, Odysseys-Easy Rubric Avg and Task Avg by 6.25 and 6.32 percentage points, and WebArena-Verified Overall success by 13.33 percentage points under the fixed harness. Code: https://github.com/china-qijizhifeng/Web-Anything", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.37786.png", "numComments": 1, "submittedBy": {"_id": "654dbac9938fbf1e696be8aa", "avatarUrl": "/avatars/185c57abc99caa4aedaaf342f4a65f75.svg", "fullname": "Chaoyun Zhang", "name": "vyokky", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 4, "isUserFollowing": false}, "isAuthorParticipating": false}, {"paper": {"id": "2610.32411", "authors": [{"_id": "6ae41675c3b566b041f6c859", "name": "Jia Wang", "hidden": false}, {"_id": "6ae41675c3b566b041f6c85a", "name": "Yuqing Li", "hidden": false}, {"_id": "6ae41675c3b566b041f6c85b", "name": "Jiangnan Li", "hidden": false}, {"_id": "6ae41675c3b566b041f6c85c", "name": "Zheng Lin", "hidden": false}, {"_id": "6ae41675c3b566b041f6c85d", "name": "Mo Yu", "hidden": false}], "publishedAt": "2026-10-23T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "A Broader Look into MLLM's Retrieval Heads", "submittedOnDailyBy": {"_id": "6891bbff78946201296b4592", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6891bbff78946201296b4592/ECmWBrlfeonPg0HzmQ_sW.png", "isPro": false, "fullname": "Yuqing Li", "user": "MindscapeRAG", "type": "user", "name": "MindscapeRAG"}, "summary": "Locating relevant evidence in long inputs is a core capability of Multimodal Large Language Models. Prior studies attribute this capability to retrieval heads, a sparse set of attention heads that transfer information from the context to the output. However, these analyses are confined to a limited set of modalities and the corresponding models. Moreover, how retrieval heads can be leveraged to enhance the model calls for further exploration. In this paper, we ask whether this mechanism expands together with the input modalities of the model. Taking audio-visual input as a newly added modality, we construct paired inputs in which the same answer is either spoken or shown on screen. With the evidence content fixed, retrieval heads remain sparse in the new modality and are shared to a large extent across modalities. Across 18 language, vision-language, and omni-modal checkpoints, omni-modal models largely preserve the retrieval heads of their backbones. Ablating these heads eliminates nearly all audio-visual retrieval. The heads shared across modalities make up fewer than 2\\% of all heads, yet ablating them also degrades document understanding, spatial perception, and visual mathematics. Building on these findings, we turn retrieval heads into a target of optimization by training their attention with a ranking objective. This raises the page Recall@1 of Qwen3-VL-8B on MMDocIR by 6.03 points and improves document retrieval across three model families. Functional attention heads can thus serve both as a lens on multimodal models and as a target for improving them.", "upvotes": 7, "discussionId": "6ae41676c3b566b041f6c85e", "projectPage": "https://qdcassie-li.github.io/MLLM-Retrieval-heads/", "ai_summary": "Retrieval heads remain sparse and shared across audio-visual modalities, and optimizing them improves document retrieval performance in multimodal models.", "ai_keywords": ["retrieval heads", "attention heads", "multimodal large language models", "audio-visual input", "omni-modal models", "cross-modal sharing", "attention ablation", "ranking objective", "document retrieval"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "summary_zh": "<ul>\n    <li>\u591a\u6a21\u6001\u5927\u578b\u8bed\u8a00\u6a21\u578b\u80fd\u591f\u4ece\u957f\u8f93\u5165\u4e2d\u627e\u5230\u76f8\u5173\u8bc1\u636e\u3002</li>\n    <li>\u4ee5\u524d\u7684\u7814\u7a76\u8ba4\u4e3a\u8fd9\u79cd\u80fd\u529b\u4e0e\u7a00\u758f\u7684\u68c0\u7d22\u5934\u6709\u5173\uff0c\u8fd9\u4e9b\u68c0\u7d22\u5934\u5c06\u4e0a\u4e0b\u6587\u4fe1\u606f\u4f20\u9012\u5230\u8f93\u51fa\u3002</li>\n    <li>\u672c\u7814\u7a76\u63a2\u8ba8\u4e86\u68c0\u7d22\u5934\u5728\u4e0d\u540c\u8f93\u5165\u6a21\u6001\u4e0b\u7684\u8868\u73b0\uff0c\u5c24\u5176\u662f\u97f3\u9891-\u89c6\u89c9\u8f93\u5165\u3002</li>\n    <li>\u5c3d\u7ba1\u68c0\u7d22\u5934\u5728\u65b0\u6a21\u6001\u4e2d\u4ecd\u7136\u7a00\u758f\uff0c\u4f46\u5b83\u4eec\u5728\u4e0d\u540c\u6a21\u6001\u4e4b\u95f4\u5171\u4eab\u3002</li>\n    <li>\u901a\u8fc7\u4f18\u5316\u68c0\u7d22\u5934\u7684\u6ce8\u610f\u529b\uff0c\u53ef\u4ee5\u663e\u8457\u63d0\u9ad8\u6a21\u578b\u7684\u6587\u6863\u68c0\u7d22\u80fd\u529b\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Multimodal Large Language Models can find relevant evidence in long inputs effectively.</li>\n    <li>Previous research focused on specific types of models and didn't explore how retrieval heads work with different types of inputs.</li>\n    <li>This study investigates how retrieval heads function with audio-visual inputs, using examples that show or speak the same information.</li>\n    <li>Even with new input types, retrieval heads are still rare and shared across different modalities, but they are crucial for understanding and processing information.</li>\n    <li>Optimizing these retrieval heads improved document retrieval performance significantly across multiple model types.</li>\n</ul>"}, "publishedAt": "2026-10-22T20:00:00.000Z", "title": "A Broader Look into MLLM's Retrieval Heads", "summary": "Locating relevant evidence in long inputs is a core capability of Multimodal Large Language Models. Prior studies attribute this capability to retrieval heads, a sparse set of attention heads that transfer information from the context to the output. However, these analyses are confined to a limited set of modalities and the corresponding models. Moreover, how retrieval heads can be leveraged to enhance the model calls for further exploration. In this paper, we ask whether this mechanism expands together with the input modalities of the model. Taking audio-visual input as a newly added modality, we construct paired inputs in which the same answer is either spoken or shown on screen. With the evidence content fixed, retrieval heads remain sparse in the new modality and are shared to a large extent across modalities. Across 18 language, vision-language, and omni-modal checkpoints, omni-modal models largely preserve the retrieval heads of their backbones. Ablating these heads eliminates nearly all audio-visual retrieval. The heads shared across modalities make up fewer than 2\\% of all heads, yet ablating them also degrades document understanding, spatial perception, and visual mathematics. Building on these findings, we turn retrieval heads into a target of optimization by training their attention with a ranking objective. This raises the page Recall@1 of Qwen3-VL-8B on MMDocIR by 6.03 points and improves document retrieval across three model families. Functional attention heads can thus serve both as a lens on multimodal models and as a target for improving them.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.32411.png", "numComments": 1, "submittedBy": {"_id": "6891bbff78946201296b4592", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/6891bbff78946201296b4592/ECmWBrlfeonPg0HzmQ_sW.png", "fullname": "Yuqing Li", "name": "MindscapeRAG", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 12, "isUserFollowing": false}, "organization": {"_id": "66543b6e420092799d2f625c", "name": "tencent", "fullname": "Tencent", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Lp3m-XLpjQGwBItlvn69q.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.37161", "authors": [{"_id": "6ae2afe2d670fc6ea896c7e6", "name": "Ziyang Zeng", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7e7", "name": "Tingyang Chen", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7e8", "name": "Jia Deng", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7e9", "name": "Qiyao Wang", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7ea", "name": "Shuo Tang", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7eb", "name": "Yike Yang", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7ec", "name": "Tao Ren", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7ed", "name": "Wayne Xin Zhao", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7ee", "name": "Feng Chang", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7ef", "name": "Jujie He", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7f0", "name": "Chuan Hao", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7f1", "name": "Ran Tao", "hidden": false}, {"_id": "6ae2afe2d670fc6ea896c7f2", "name": "Bryan Dai", "hidden": false}], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "WorkFactory: Turning Professional Intents into Executable Work for Scalable Agent Training", "submittedOnDailyBy": {"_id": "68cb7d70de299da181a5ec4c", "avatarUrl": "/avatars/793f4263e9d900299cfd59c99922e7dc.svg", "isPro": false, "fullname": "CHEN TINGYANG", "user": "Tingyang-Chen", "type": "user", "name": "Tingyang-Chen"}, "summary": "Scaling supervised training for working agents requires diverse professional tasks that yield reliable expert demonstrations. However, missing or inconsistent task information can obstruct teacher execution and weaken the resulting supervision. We propose WorkFactory, a scalable framework for constructing coherent and executable professional tasks. Starting from professional intents, information-level planning builds an information support graph to guide task instantiation, explicitly representing the dependencies and locations of information required for the intended outputs. Probe executions then identify support failures and guide repairs while preserving the intended work. We construct 112,686 tasks spanning 612 occupations and use the collected teacher trajectories to fine-tune Qwen models at 4B, 27B, and 35B-A3B scales, yielding the WorkPilot family. All three models improve over their respective base models across four professional-work benchmarks, with WorkPilot-35B-A3B improving from 879 to 1565 Elo on GDPval-AA v2.1. Scaling analyses reveal model-dependent diminishing returns, with execution length first increasing and then decreasing. Controlled component analyses show that planning and repair reduce probe-diagnosed task environment defects and improve downstream performance. The data and models are available at https://github.com/IQuestLab/WorkFactory.", "upvotes": 6, "discussionId": "6ae2afe2d670fc6ea896c7f3", "githubRepo": "https://github.com/IQuestLab/WorkFactory", "githubRepoAddedBy": "user", "ai_summary": "WorkFactory builds coherent professional tasks via information planning and repair, yielding WorkPilot models that improve expert-level agent performance across benchmarks.", "ai_keywords": ["information support graph", "probe executions", "WorkFactory", "WorkPilot", "supervised training", "fine-tune", "Qwen", "Elo", "scaling analyses"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 5, "organization": {"_id": "6937e1578cd2568ba4c9d3f9", "name": "IQuestLab", "fullname": "IQuest", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68c80cc3a1ca9a73c17d29f7/pjOEigZuk_UQ4dqyS482V.png"}, "summary_zh": "<ul>\n    <li>\u63d0\u51fa\u4e86WorkFactory\uff0c\u4e00\u4e2a\u53ef\u6269\u5c55\u7684\u6846\u67b6\uff0c\u7528\u4e8e\u6784\u5efa\u4e00\u81f4\u4e14\u53ef\u6267\u884c\u7684\u4e13\u4e1a\u4efb\u52a1\u3002</li>\n    <li>\u901a\u8fc7\u4fe1\u606f\u652f\u6301\u56fe\uff0c\u660e\u786e\u8868\u793a\u4efb\u52a1\u6240\u9700\u7684\u4fe1\u606f\u4f9d\u8d56\u5173\u7cfb\u548c\u4f4d\u7f6e\uff0c\u4ee5\u6307\u5bfc\u4efb\u52a1\u7684\u5b9e\u4f8b\u5316\u3002</li>\n    <li>\u6784\u5efa\u4e86112,686\u4e2a\u6db5\u76d6612\u79cd\u804c\u4e1a\u7684\u4efb\u52a1\uff0c\u5e76\u4f7f\u7528\u6536\u96c6\u7684\u6559\u5e08\u8f68\u8ff9\u6765\u5fae\u8c03\u4e0d\u540c\u89c4\u6a21\u7684Qwen\u6a21\u578b\u3002</li>\n    <li>WorkPilot\u6a21\u578b\u5728\u56db\u4e2a\u804c\u4e1a\u5de5\u4f5c\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u4f18\u4e8e\u57fa\u7840\u6a21\u578b\uff0c\u5c24\u5176\u662fWorkPilot-35B-A3B\u7684Elo\u8bc4\u5206\u5927\u5e45\u63d0\u5347\u3002</li>\n    <li>\u5206\u6790\u663e\u793a\u89c4\u5212\u548c\u4fee\u590d\u8fc7\u7a0b\u51cf\u5c11\u4e86\u4efb\u52a1\u73af\u5883\u7f3a\u9677\uff0c\u63d0\u9ad8\u4e86\u540e\u7eed\u6027\u80fd\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>WorkFactory is a framework designed to create clear and executable professional tasks for training agents.</li>\n    <li>It starts with professional goals and builds a support graph to help organize the necessary information for tasks.</li>\n    <li>Probe executions are used to find problems and fix them while keeping the original work goals intact.</li>\n    <li>The framework has produced over 112,000 tasks across 612 job types, which have been used to improve AI models called WorkPilot.</li>\n    <li>The improved models show better performance on professional tasks, and the data is available for public use.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "WorkFactory: Turning Professional Intents into Executable Work for Scalable Agent Training", "summary": "Scaling supervised training for working agents requires diverse professional tasks that yield reliable expert demonstrations. However, missing or inconsistent task information can obstruct teacher execution and weaken the resulting supervision. We propose WorkFactory, a scalable framework for constructing coherent and executable professional tasks. Starting from professional intents, information-level planning builds an information support graph to guide task instantiation, explicitly representing the dependencies and locations of information required for the intended outputs. Probe executions then identify support failures and guide repairs while preserving the intended work. We construct 112,686 tasks spanning 612 occupations and use the collected teacher trajectories to fine-tune Qwen models at 4B, 27B, and 35B-A3B scales, yielding the WorkPilot family. All three models improve over their respective base models across four professional-work benchmarks, with WorkPilot-35B-A3B improving from 879 to 1565 Elo on GDPval-AA v2.1. Scaling analyses reveal model-dependent diminishing returns, with execution length first increasing and then decreasing. Controlled component analyses show that planning and repair reduce probe-diagnosed task environment defects and improve downstream performance. The data and models are available at https://github.com/IQuestLab/WorkFactory.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.37161.png", "numComments": 1, "submittedBy": {"_id": "68cb7d70de299da181a5ec4c", "avatarUrl": "/avatars/793f4263e9d900299cfd59c99922e7dc.svg", "fullname": "CHEN TINGYANG", "name": "Tingyang-Chen", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "6937e1578cd2568ba4c9d3f9", "name": "IQuestLab", "fullname": "IQuest", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68c80cc3a1ca9a73c17d29f7/pjOEigZuk_UQ4dqyS482V.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.38678", "authors": [{"_id": "6ae41054c3b566b041f6c823", "name": "Lu Wang", "hidden": false}, {"_id": "6ae41054c3b566b041f6c824", "name": "Zhuoran Jin", "hidden": false}, {"_id": "6ae41054c3b566b041f6c825", "name": "Longxiang Wang", "hidden": false}, {"_id": "6ae41054c3b566b041f6c826", "name": "Junhong Chen", "hidden": false}, {"_id": "6ae41054c3b566b041f6c827", "name": "Yupu Hao", "hidden": false}, {"_id": "6ae41054c3b566b041f6c828", "name": "Yao Xu", "hidden": false}, {"_id": "6ae41054c3b566b041f6c829", "name": "Daojian Zeng", "hidden": false}, {"_id": "6ae41054c3b566b041f6c82a", "name": "Yubo Chen", "hidden": false}, {"_id": "6ae41054c3b566b041f6c82b", "name": "Kang Liu", "hidden": false}, {"_id": "6ae41054c3b566b041f6c82c", "name": "Guang Liu", "hidden": false}, {"_id": "6ae41054c3b566b041f6c82d", "name": "Jun Zhao", "hidden": false}], "publishedAt": "2026-10-28T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "AskStream: When and What to Ask Proactively under Uncertainty in Streaming Video Understanding", "submittedOnDailyBy": {"_id": "67d15f29bacfd19231a6e178", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/67d15f29bacfd19231a6e178/nbm1rAJgnH-QdEZS2tF8Z.png", "isPro": false, "fullname": "Lu  Wang", "user": "wanglucs", "type": "user", "name": "wanglucs"}, "summary": "Recent advances in multimodal large language models have increased interest in interaction paradigms for video understanding. The evolution from offline to streaming and proactive interaction has gradually shifted models from passive responders toward more proactive agents that can decide when to answer. However, existing proactive paradigms typically assume that the information required to answer a query is complete, leaving models to only wait or answer. In the real world, however, information is often incomplete due to uncertainty from either the video or the user. In proactive paradigms, such uncertainty can cause the model to wait forever or generate highly hallucinatory responses. We therefore argue that proactive interaction should be redefined with a third action: ask, allowing models to actively ask for missing information. To study when and what models should ask before answering, we introduce AskStream, the first multi-turn benchmark spanning video and user uncertainty for streaming video understanding, with four task categories and eight subtasks. It contains 438 videos with 2,714 manually annotated frame-level time windows across three types: wait, ask, and answer. Across both multiple-choice and open-ended settings, even the strongest model attains only 52.18% on our proposed Ask-F1 metric, highlighting substantial limitations in proactive information seeking under uncertainty.", "upvotes": 4, "discussionId": "6ae41054c3b566b041f6c82e", "projectPage": "https://askstream.top/", "githubRepo": "https://github.com/wanglu-cs/AskStream", "githubRepoAddedBy": "user", "ai_summary": "Proactive video understanding should include asking for missing information under uncertainty, and the AskStream benchmark reveals current models struggle with this decision.", "ai_keywords": ["multimodal large language models", "streaming video understanding", "proactive interaction", "AskStream", "Ask-F1 metric", "video uncertainty", "user uncertainty"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 9, "organization": {"_id": "640a887796aae649741a586f", "name": "CASIA", "fullname": "Chinese Academic of Science Institute of Automation", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1678411888885-6388984e8a5dbe2f3dc5afee.jpeg"}, "summary_zh": "<ul>\n  <li>\u591a\u6a21\u6001\u5927\u578b\u8bed\u8a00\u6a21\u578b\u5728\u89c6\u9891\u7406\u89e3\u4e2d\u7684\u4e92\u52a8\u65b9\u5f0f\u5f97\u5230\u4e86\u5173\u6ce8\u3002</li>\n  <li>\u73b0\u6709\u7684\u4e3b\u52a8\u4e92\u52a8\u6a21\u578b\u5047\u8bbe\u4fe1\u606f\u662f\u5b8c\u6574\u7684\uff0c\u4f46\u73b0\u5b9e\u4e2d\u4fe1\u606f\u5f80\u5f80\u4e0d\u5b8c\u6574\u3002</li>\n  <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e00\u95ee\u9898\uff0c\u63d0\u51fa\u4e86\u201cAskStream\u201d\u57fa\u51c6\uff0c\u5141\u8bb8\u6a21\u578b\u4e3b\u52a8\u8be2\u95ee\u7f3a\u5931\u7684\u4fe1\u606f\u3002</li>\n  <li>\u201cAskStream\u201d\u5305\u542b438\u4e2a\u89c6\u9891\u548c2714\u4e2a\u624b\u52a8\u6807\u6ce8\u7684\u5e27\u7ea7\u65f6\u95f4\u7a97\u53e3\uff0c\u5206\u4e3a\u7b49\u5f85\u3001\u8be2\u95ee\u548c\u56de\u7b54\u4e09\u79cd\u7c7b\u578b\u3002</li>\n  <li>\u5728\u4e0d\u786e\u5b9a\u6027\u4e0b\uff0c\u6700\u5f3a\u6a21\u578b\u5728\u201cAsk-F1\u201d\u6307\u6807\u4e0a\u4ec5\u8fbe\u523052.18%\uff0c\u663e\u793a\u51fa\u4e3b\u52a8\u4fe1\u606f\u83b7\u53d6\u7684\u5c40\u9650\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>New large language models are improving how we understand videos and interact with them.</li>\n    <li>Current models can only wait or answer, but they often face incomplete information from videos or users.</li>\n    <li>This study suggests adding a third action, \"ask,\" so models can request missing information.</li>\n    <li>AskStream is the first benchmark to test how models handle uncertainty in streaming video, featuring 438 videos and various tasks.</li>\n    <li>Even the best models only scored 52.18% on the new Ask-F1 metric, showing there\u2019s much room for improvement in proactive information seeking.</li>\n</ul>"}, "publishedAt": "2026-10-27T20:00:00.000Z", "title": "AskStream: When and What to Ask Proactively under Uncertainty in Streaming Video Understanding", "summary": "Recent advances in multimodal large language models have increased interest in interaction paradigms for video understanding. The evolution from offline to streaming and proactive interaction has gradually shifted models from passive responders toward more proactive agents that can decide when to answer. However, existing proactive paradigms typically assume that the information required to answer a query is complete, leaving models to only wait or answer. In the real world, however, information is often incomplete due to uncertainty from either the video or the user. In proactive paradigms, such uncertainty can cause the model to wait forever or generate highly hallucinatory responses. We therefore argue that proactive interaction should be redefined with a third action: ask, allowing models to actively ask for missing information. To study when and what models should ask before answering, we introduce AskStream, the first multi-turn benchmark spanning video and user uncertainty for streaming video understanding, with four task categories and eight subtasks. It contains 438 videos with 2,714 manually annotated frame-level time windows across three types: wait, ask, and answer. Across both multiple-choice and open-ended settings, even the strongest model attains only 52.18% on our proposed Ask-F1 metric, highlighting substantial limitations in proactive information seeking under uncertainty.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.38678.png", "numComments": 1, "submittedBy": {"_id": "67d15f29bacfd19231a6e178", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/67d15f29bacfd19231a6e178/nbm1rAJgnH-QdEZS2tF8Z.png", "fullname": "Lu  Wang", "name": "wanglucs", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "640a887796aae649741a586f", "name": "CASIA", "fullname": "Chinese Academic of Science Institute of Automation", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1678411888885-6388984e8a5dbe2f3dc5afee.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.39664", "authors": [{"_id": "6ae40e7ec3b566b041f6c818", "name": "Haiyang Xu", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c819", "name": "Tianyu Wang", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81a", "name": "Jialu Li", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81b", "name": "Jiteng Mu", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81c", "name": "Yuanjun Xiong", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81d", "name": "Jianming Zhang", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81e", "name": "Zhuowen Tu", "hidden": false}, {"_id": "6ae40e7ec3b566b041f6c81f", "name": "Mingze Xu", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/632a994b4ee2960462ecbf7e/TxvbXSdulQPILjAQkPAnY.png"], "publishedAt": "2026-10-29T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "EditAgent: Rethinking Agentic Image Editing", "submittedOnDailyBy": {"_id": "632a994b4ee2960462ecbf7e", "avatarUrl": "/avatars/5b462ddc343e035c4d147b521180691b.svg", "isPro": true, "fullname": "Haiyang Xu", "user": "xuhaiyang3110", "type": "user", "name": "xuhaiyang3110"}, "summary": "Agentic image editors decompose complex requests into steps, but when a step fails, they mostly retry with the same narrow set of tools and a judge that scores each output by eye directly. We argue that such agents are bounded by two spaces: the action space of what the agent can do, and the observation space of what its judge can see. On our expert-annotated benchmark, a general-purpose editor yields no usable result in over 40% of the cases, and no judge is reliable across edit types. We present EditAgent, which expands both spaces. It routes each step to general editors and specialized methods, and attaches to each candidate a verification record. With these records, off-the-shelf VLM judges outperform finetuned reward models. Candidates are generated in parallel and judged in one listwise call: experts prefer this to sequential refinement in 78.5% of decided comparisons, at no more than half the judge calls. EditAgent improves two open-weight editors on three benchmarks and serves as a data engine for training stronger editors.", "upvotes": 4, "discussionId": "6ae40e7ec3b566b041f6c820", "ai_summary": "EditAgent broadens agentic image editing by routing steps to diverse editors and using verification records for listwise judging, improving reliability and efficiency.", "ai_keywords": ["agentic image editors", "action space", "observation space", "VLM judges", "verification records", "listwise judging", "reward models", "open-weight editors"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "61e5d14f77496de0a6d95c6b", "name": "adobe", "fullname": "Adobe", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1645217431826-61e35e517ac6b6d06cfa8081.png"}, "summary_zh": "<ul>\n    <li>\u4f20\u7edf\u7684\u56fe\u50cf\u7f16\u8f91\u4ee3\u7406\u5728\u5904\u7406\u590d\u6742\u8bf7\u6c42\u65f6\uff0c\u5e38\u5e38\u4f1a\u56e0\u4e3a\u6b65\u9aa4\u5931\u8d25\u800c\u91cd\u590d\u4f7f\u7528\u76f8\u540c\u7684\u5de5\u5177\uff0c\u5bfc\u81f4\u4f4e\u6548\u3002</li>\n    <li>\u8fd9\u4e9b\u4ee3\u7406\u53d7\u5230\u64cd\u4f5c\u7a7a\u95f4\u548c\u89c2\u5bdf\u7a7a\u95f4\u7684\u9650\u5236\uff0c\u5bfc\u81f4\u5728\u8d85\u8fc740%\u7684\u60c5\u51b5\u4e0b\u65e0\u6cd5\u4ea7\u751f\u53ef\u7528\u7ed3\u679c\u3002</li>\n    <li>EditAgent\u901a\u8fc7\u6269\u5c55\u64cd\u4f5c\u7a7a\u95f4\u548c\u89c2\u5bdf\u7a7a\u95f4\uff0c\u6539\u8fdb\u4e86\u56fe\u50cf\u7f16\u8f91\u8fc7\u7a0b\u3002</li>\n    <li>EditAgent\u5c06\u6bcf\u4e2a\u6b65\u9aa4\u5206\u914d\u7ed9\u901a\u7528\u7f16\u8f91\u5668\u548c\u4e13\u4e1a\u65b9\u6cd5\uff0c\u5e76\u4e3a\u6bcf\u4e2a\u5019\u9009\u7ed3\u679c\u9644\u52a0\u9a8c\u8bc1\u8bb0\u5f55\u3002</li>\n    <li>\u76f8\u6bd4\u4e8e\u4f20\u7edf\u7684\u9010\u6b65\u6539\u8fdb\u65b9\u6cd5\uff0cEditAgent\u5728\u4e13\u5bb6\u8bc4\u5224\u4e2d\u83b7\u5f97\u4e86\u66f4\u9ad8\u7684\u504f\u597d\uff0c\u4e14\u6548\u7387\u66f4\u9ad8\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Current image editors often struggle with complex requests, leading to failures in over 40% of cases.</li>\n    <li>These editors are limited by what they can do and what their judges can see when assessing results.</li>\n    <li>EditAgent improves the process by using both general editors and specialized methods for different steps.</li>\n    <li>It better verifies results, allowing for more reliable judging compared to traditional methods.</li>\n    <li>EditAgent has been shown to improve existing editors and can help train better future editors.</li>\n</ul>"}, "publishedAt": "2026-10-28T20:00:00.000Z", "title": "EditAgent: Rethinking Agentic Image Editing", "summary": "Agentic image editors decompose complex requests into steps, but when a step fails, they mostly retry with the same narrow set of tools and a judge that scores each output by eye directly. We argue that such agents are bounded by two spaces: the action space of what the agent can do, and the observation space of what its judge can see. On our expert-annotated benchmark, a general-purpose editor yields no usable result in over 40% of the cases, and no judge is reliable across edit types. We present EditAgent, which expands both spaces. It routes each step to general editors and specialized methods, and attaches to each candidate a verification record. With these records, off-the-shelf VLM judges outperform finetuned reward models. Candidates are generated in parallel and judged in one listwise call: experts prefer this to sequential refinement in 78.5% of decided comparisons, at no more than half the judge calls. EditAgent improves two open-weight editors on three benchmarks and serves as a data engine for training stronger editors.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/632a994b4ee2960462ecbf7e/TxvbXSdulQPILjAQkPAnY.png"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.39664.png", "numComments": 1, "submittedBy": {"_id": "632a994b4ee2960462ecbf7e", "avatarUrl": "/avatars/5b462ddc343e035c4d147b521180691b.svg", "fullname": "Haiyang Xu", "name": "xuhaiyang3110", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "61e5d14f77496de0a6d95c6b", "name": "adobe", "fullname": "Adobe", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1645217431826-61e35e517ac6b6d06cfa8081.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.35138", "authors": [{"_id": "6ae1b2c5a5eb0647c2907674", "name": "Xilin Wei", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907675", "name": "Shengyuan Ding", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907676", "name": "Xinyu Fang", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907677", "name": "Tiancheng Gu", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907678", "name": "Yuchi Wang", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907679", "name": "Zhixun Li", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767a", "name": "Ziyu Liu", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767b", "name": "Yuhang Zang", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767c", "name": "Weixiang Yu", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767d", "name": "Cheng Lu", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767e", "name": "Chonggao Sun", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c290767f", "name": "Tong Zhou", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907680", "name": "Dahua Lin", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907681", "name": "Hang Zhang", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907682", "name": "Shuai Bai", "hidden": false}, {"_id": "6ae1b2c5a5eb0647c2907683", "name": "Dayiheng Liu", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/62eb70462f0f5e54df42f778/pDDM0C5U3tpdBkGIVbFss.mp4"], "publishedAt": "2026-10-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "Co-Design Bench: Multimodal Collaborative Coding Evaluation for Agentic Models", "submittedOnDailyBy": {"_id": "62eb70462f0f5e54df42f778", "avatarUrl": "/avatars/2b83a61c422a0209cba804e6a81dea5a.svg", "isPro": false, "fullname": "Xilin Wei", "user": "Wiselnn", "type": "user", "name": "Wiselnn"}, "summary": "Evaluating human-AI co-design requires testing whether coding agents can translate real users' multimodal requests into working application revisions. We introduce Co-Design Bench, a reference-free benchmark of 273 tasks curated from 37,463 deduplicated queries across 26,314 real user coding sessions. Its two tracks, Multimodal Editing (ME) and Repository Editing (RE), cover localized edits with optional image, audio, video, or document inputs and coordinated repository revisions. Tasks span three capability dimensions: Grounded Understanding, UI Transformation, and Functional Implementation. The tasks pair normalized requests and runnable pre-edit applications with 2,331 hidden expert-authored acceptance criteria. Our judge-then-refute protocol grades criteria using source and browser evidence, challenges positive verdicts with a separate LLM verifier, and audits visual and interaction claims without gold code or target screenshots. Under a shared agentic harness, the strongest of ten model endpoints passes an average of 69.9% of criteria per task but fully satisfies only 26.4% of tasks. All ten endpoints achieve lower criterion completion on repository edits spanning three or four change types than on those spanning one or two. Co-Design Bench provides a testbed for studying the gap between partial requirement satisfaction and complete task success under agentic execution for real-user application revisions.", "upvotes": 3, "discussionId": "6ae1b2c5a5eb0647c2907684", "projectPage": "https://codesignbench.github.io/", "githubRepo": "https://github.com/Wiselnn570/Co-Design-Bench", "githubRepoAddedBy": "user", "githubStars": 24, "organization": {"_id": "64c8b5837fe12ecd0a7e92eb", "name": "Qwen", "fullname": "Qwen", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6215ca5692c0ecfba9186921/hrRM50-6XcdWgg2AKpENG.jpeg"}, "summary_zh": "<ul>\n    <li>Co-Design Bench \u662f\u4e00\u4e2a\u8bc4\u4f30\u4eba\u7c7b\u4e0e AI \u5171\u540c\u8bbe\u8ba1\u7684\u57fa\u51c6\uff0c\u5305\u542b 273 \u4e2a\u4efb\u52a1\uff0c\u6765\u6e90\u4e8e 37,463 \u4e2a\u7528\u6237\u8bf7\u6c42\u3002</li>\n    <li>\u5b83\u6709\u4e24\u4e2a\u90e8\u5206\uff0c\u5206\u522b\u662f\u591a\u6a21\u6001\u7f16\u8f91\uff08ME\uff09\u548c\u4ed3\u5e93\u7f16\u8f91\uff08RE\uff09\uff0c\u6d89\u53ca\u4e0d\u540c\u7c7b\u578b\u7684\u8f93\u5165\uff0c\u5982\u56fe\u50cf\u3001\u97f3\u9891\u3001\u89c6\u9891\u548c\u6587\u6863\u3002</li>\n    <li>\u4efb\u52a1\u6db5\u76d6\u4e86\u4e09\u4e2a\u80fd\u529b\u7ef4\u5ea6\uff1a\u57fa\u7840\u7406\u89e3\u3001\u7528\u6237\u754c\u9762\u8f6c\u6362\u548c\u529f\u80fd\u5b9e\u73b0\u3002</li>\n    <li>\u901a\u8fc7\u8bc4\u4f30\u6807\u51c6\u548c\u9a8c\u8bc1\u673a\u5236\uff0c\u8be5\u57fa\u51c6\u53ef\u4ee5\u6d4b\u8bd5 AI \u5728\u5b8c\u6210\u7528\u6237\u8bf7\u6c42\u65f6\u7684\u8868\u73b0\u3002</li>\n    <li>\u867d\u7136\u6700\u5f3a\u7684\u6a21\u578b\u5728\u6bcf\u4e2a\u4efb\u52a1\u4e2d\u5e73\u5747\u80fd\u6ee1\u8db3 69.9% \u7684\u6807\u51c6\uff0c\u4f46\u5b8c\u5168\u6ee1\u8db3\u7684\u4efb\u52a1\u6bd4\u4f8b\u4ec5\u4e3a 26.4%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Co-Design Bench is a new tool to test how well coding agents can understand and modify applications based on user requests.</li>\n    <li>It includes 273 tasks collected from real user coding sessions, which involve making changes to applications using different types of media inputs.</li>\n    <li>The tasks focus on three main areas: understanding user requests, changing user interfaces, and implementing functional features.</li>\n    <li>A special grading system evaluates how well the coding agents meet expert-defined criteria, using evidence from various sources.</li>\n    <li>While the best coding agents meet about 70% of the criteria on average, they only fully complete about 26% of the tasks, especially struggling with more complex changes.</li>\n</ul>"}, "publishedAt": "2026-10-25T20:00:00.000Z", "title": "Co-Design Bench: Multimodal Collaborative Coding Evaluation for Agentic Models", "summary": "Evaluating human-AI co-design requires testing whether coding agents can translate real users' multimodal requests into working application revisions. We introduce Co-Design Bench, a reference-free benchmark of 273 tasks curated from 37,463 deduplicated queries across 26,314 real user coding sessions. Its two tracks, Multimodal Editing (ME) and Repository Editing (RE), cover localized edits with optional image, audio, video, or document inputs and coordinated repository revisions. Tasks span three capability dimensions: Grounded Understanding, UI Transformation, and Functional Implementation. The tasks pair normalized requests and runnable pre-edit applications with 2,331 hidden expert-authored acceptance criteria. Our judge-then-refute protocol grades criteria using source and browser evidence, challenges positive verdicts with a separate LLM verifier, and audits visual and interaction claims without gold code or target screenshots. Under a shared agentic harness, the strongest of ten model endpoints passes an average of 69.9% of criteria per task but fully satisfies only 26.4% of tasks. All ten endpoints achieve lower criterion completion on repository edits spanning three or four change types than on those spanning one or two. Co-Design Bench provides a testbed for studying the gap between partial requirement satisfaction and complete task success under agentic execution for real-user application revisions.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/62eb70462f0f5e54df42f778/pDDM0C5U3tpdBkGIVbFss.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.35138.png", "numComments": 1, "submittedBy": {"_id": "62eb70462f0f5e54df42f778", "avatarUrl": "/avatars/2b83a61c422a0209cba804e6a81dea5a.svg", "fullname": "Xilin Wei", "name": "Wiselnn", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "64c8b5837fe12ecd0a7e92eb", "name": "Qwen", "fullname": "Qwen", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6215ca5692c0ecfba9186921/hrRM50-6XcdWgg2AKpENG.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.29927", "authors": [{"_id": "6ad970df3f2bb52eb8d6e985", "name": "Yifan Sun", "hidden": false}, {"_id": "6ad970df3f2bb52eb8d6e986", "name": "Naicheng Yu", "hidden": false}, {"_id": "6ad970df3f2bb52eb8d6e987", "name": "Jiawen Gong", "hidden": false}, {"_id": "6ad970df3f2bb52eb8d6e988", "name": "Jingyan Shen", "hidden": false}, {"_id": "6ad970df3f2bb52eb8d6e989", "name": "Huan Zhang", "hidden": false}], "publishedAt": "2026-10-21T00:00:00.000Z", "submittedOnDailyAt": "2026-10-30T00:00:00.000Z", "title": "Your Benchmark Is an Empirical Measure Over Difficulty", "submittedOnDailyBy": {"_id": "687ebb87416fcff56959d817", "avatarUrl": "/avatars/1b41aff8f565b63d8c1dec8197db087a.svg", "isPro": false, "fullname": "Keyang Xuan", "user": "keyangx3", "type": "user", "name": "keyangx3"}, "summary": "A benchmark is not merely a collection of test questions; it naturally induces an empirical measure over difficulty. In this work, we develop this measure-based view of benchmark evaluation. This perspective allows us to identify and formalize two central failure modes: measure mismatch, where the benchmark difficulty distribution differs from the intended difficulty distribution, and coverage gaps, where uncovered regions along the difficulty axis prevent benchmarks from detecting meaningful localized training progress. We propose two diagnostic metrics that capture these two failure modes and provide rigorous theoretical guarantees. Empirically, we analyze 25 popular benchmarks spanning 7 domains using carefully estimated item difficulties. Our results show that many benchmarks implicitly overweight certain difficulty regions, so their leaderboard conclusions should be interpreted with caution; others leave substantial portions of the difficulty axis uncovered, limiting their ability to monitor the model improvement process. Finally, we turn diagnosis into action by introducing BenchFill, a simple difficulty-targeted item rewriting algorithm that effectively reduces local coverage gaps.", "upvotes": 1, "discussionId": "6ad970e03f2bb52eb8d6e98a", "projectPage": "https://benchmark-difficulty-measure.github.io/", "githubRepo": "https://github.com/ASTRAL-Group/benchmark-difficulty-measure", "githubRepoAddedBy": "user", "ai_summary": "This work formalizes benchmark evaluation through difficulty measures, identifies failure modes of measure mismatch and coverage gaps, and proposes diagnostic metrics and a rewriting algorithm to improve benchmark coverage.", "ai_keywords": ["measure mismatch", "coverage gaps", "diagnostic metrics", "item difficulty", "BenchFill", "difficulty-targeted item rewriting"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "65448bef5b5d9185ba3202b9", "name": "UIUC-CS", "fullname": "University of Illinois at Urbana-Champaign", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65448b21fcb96b8b48733729/ycqcXFayMTTD_KpE37067.jpeg"}, "summary_zh": "<ul>\n    <li>\u57fa\u51c6\u6d4b\u8bd5\u4e0d\u4ec5\u4ec5\u662f\u4e00\u4e9b\u6d4b\u8bd5\u95ee\u9898\uff0c\u800c\u662f\u80fd\u6709\u6548\u8861\u91cf\u96be\u5ea6\u7684\u5de5\u5177\u3002</li>\n    <li>\u672c\u7814\u7a76\u63d0\u51fa\u4e86\u4e00\u79cd\u57fa\u4e8e\u6d4b\u91cf\u7684\u57fa\u51c6\u8bc4\u4f30\u65b9\u6cd5\uff0c\u8bc6\u522b\u4e86\u4e24\u79cd\u4e3b\u8981\u7684\u5931\u8d25\u6a21\u5f0f\uff1a\u6d4b\u91cf\u4e0d\u5339\u914d\u548c\u8986\u76d6\u7f3a\u53e3\u3002</li>\n    <li>\u6d4b\u91cf\u4e0d\u5339\u914d\u662f\u6307\u57fa\u51c6\u7684\u96be\u5ea6\u5206\u5e03\u4e0e\u9884\u671f\u7684\u96be\u5ea6\u5206\u5e03\u4e0d\u540c\uff1b\u8986\u76d6\u7f3a\u53e3\u662f\u6307\u5728\u96be\u5ea6\u8f74\u4e0a\u672a\u8986\u76d6\u7684\u533a\u57df\uff0c\u5bfc\u81f4\u57fa\u51c6\u65e0\u6cd5\u68c0\u6d4b\u5230\u6709\u610f\u4e49\u7684\u8bad\u7ec3\u8fdb\u5c55\u3002</li>\n    <li>\u6211\u4eec\u5206\u6790\u4e8625\u4e2a\u6d41\u884c\u7684\u57fa\u51c6\uff0c\u53d1\u73b0\u8bb8\u591a\u57fa\u51c6\u5bf9\u67d0\u4e9b\u96be\u5ea6\u533a\u57df\u7684\u6743\u91cd\u8fc7\u91cd\uff0c\u7ed3\u679c\u9700\u8981\u8c28\u614e\u89e3\u8bfb\uff1b\u8fd8\u6709\u4e00\u4e9b\u57fa\u51c6\u5728\u96be\u5ea6\u8f74\u4e0a\u7559\u6709\u8f83\u5927\u7a7a\u767d\uff0c\u9650\u5236\u4e86\u76d1\u6d4b\u6a21\u578b\u6539\u8fdb\u7684\u80fd\u529b\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u6211\u4eec\u63d0\u51fa\u4e86BenchFill\uff0c\u8fd9\u662f\u4e00\u79cd\u7b80\u5355\u7684\u9488\u5bf9\u96be\u5ea6\u7684\u9879\u76ee\u91cd\u5199\u7b97\u6cd5\uff0c\u6709\u6548\u51cf\u5c11\u4e86\u5c40\u90e8\u8986\u76d6\u7f3a\u53e3\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>A benchmark is more than just test questions; it measures difficulty in a systematic way.</li>\n    <li>This study identifies two main issues with benchmarks: measure mismatch and coverage gaps.</li>\n    <li>Measure mismatch occurs when the benchmark's difficulty does not match what was intended.</li>\n    <li>Coverage gaps happen when some difficulty levels are not tested, making it hard to see real progress in training.</li>\n    <li>The authors propose a solution called BenchFill, which helps improve coverage by rewriting test items to target specific difficulty levels.</li>\n</ul>"}, "publishedAt": "2026-10-20T20:00:00.000Z", "title": "Your Benchmark Is an Empirical Measure Over Difficulty", "summary": "A benchmark is not merely a collection of test questions; it naturally induces an empirical measure over difficulty. In this work, we develop this measure-based view of benchmark evaluation. This perspective allows us to identify and formalize two central failure modes: measure mismatch, where the benchmark difficulty distribution differs from the intended difficulty distribution, and coverage gaps, where uncovered regions along the difficulty axis prevent benchmarks from detecting meaningful localized training progress. We propose two diagnostic metrics that capture these two failure modes and provide rigorous theoretical guarantees. Empirically, we analyze 25 popular benchmarks spanning 7 domains using carefully estimated item difficulties. Our results show that many benchmarks implicitly overweight certain difficulty regions, so their leaderboard conclusions should be interpreted with caution; others leave substantial portions of the difficulty axis uncovered, limiting their ability to monitor the model improvement process. Finally, we turn diagnosis into action by introducing BenchFill, a simple difficulty-targeted item rewriting algorithm that effectively reduces local coverage gaps.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.29927.png", "numComments": 1, "submittedBy": {"_id": "687ebb87416fcff56959d817", "avatarUrl": "/avatars/1b41aff8f565b63d8c1dec8197db087a.svg", "fullname": "Keyang Xuan", "name": "keyangx3", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 4, "isUserFollowing": false}, "organization": {"_id": "65448bef5b5d9185ba3202b9", "name": "UIUC-CS", "fullname": "University of Illinois at Urbana-Champaign", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65448b21fcb96b8b48733729/ycqcXFayMTTD_KpE37067.jpeg"}, "isAuthorParticipating": false}],
    "week": [{"paper": {"id": "2610.34283", "authors": [{"_id": "6ae15489a5eb0647c290713b", "name": "Yihao Hu", "hidden": false}, {"_id": "6ae15489a5eb0647c290713c", "name": "Yitong Lin", "hidden": false}, {"_id": "6ae15489a5eb0647c290713d", "name": "Pan Wang", "hidden": false}, {"_id": "6ae15489a5eb0647c290713e", "name": "Zhihao Wen", "hidden": false}, {"_id": "6ae15489a5eb0647c290713f", "name": "Hang Wang", "hidden": false}, {"_id": "6ae15489a5eb0647c2907140", "name": "Yiwen Zhao", "hidden": false}, {"_id": "6ae15489a5eb0647c2907141", "name": "Deyuan Liu", "hidden": false}, {"_id": "6ae15489a5eb0647c2907142", "name": "Yutong Li", "hidden": false}, {"_id": "6ae15489a5eb0647c2907143", "name": "Mingda Wan", "hidden": false}, {"_id": "6ae15489a5eb0647c2907144", "name": "Yuchen Mao", "hidden": false}, {"_id": "6ae15489a5eb0647c2907145", "name": "Tao Lin", "hidden": false}], "publishedAt": "2026-10-25T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence", "submittedOnDailyBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "isPro": false, "fullname": "Yihao Hu", "user": "HU22333", "type": "user", "name": "HU22333"}, "summary": "Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, and balancing supervision across families. Under the same observation access, a single ChronoReplay checkpoint improves OVO-S-Bench, OST-Bench, and UCS-Bench together, including a 13.41-point gain on OST-Bench, and achieves the highest three-benchmark mean among the supervision settings compared here. Same-data controls further separate the ingredients of this transfer: answer serialization redistributes gains across OST and UCS, family-balanced learning improves over ordinary joint SFT and natural turn weighting, and chronological replay exceeds a shifted-order control by about 2.41 OST points across two paired seeds. Adaptive frame selection then changes evidence access while keeping the trained model fixed, providing an additional inference-time gain at lower visual cost. Streaming spatial performance depends on what distinctions supervision preserves, how heterogeneous histories are organized during learning, and what causal evidence inference makes available at test time.", "upvotes": 77, "discussionId": "6ae15489a5eb0647c2907146", "projectPage": "https://yihaohu0118.github.io/ChronoReplay/", "ai_summary": "ChronoReplay mitigates interface lock-in in spatial vision-language models by replaying heterogeneous spatial supervision chronologically, improving cross-task transfer and enabling efficient inference-time evidence selection.", "ai_keywords": ["spatial VLM", "interface lock-in", "ChronoReplay", "joint SFT", "adaptive frame selection", "OVO-S-Bench", "OST-Bench", "UCS-Bench"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "6650967d53061f0d1b5a7962", "name": "LINs-lab", "fullname": "LINs lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65296b8a6cdea40585bd81e2/M80w6f0H8dfx3Sa1nVmfq.png"}, "summary_zh": "<ul>\n    <li>\u8bad\u7ec3\u7a7a\u95f4\u89c6\u89c9\u8bed\u8a00\u6a21\u578b\uff08VLM\uff09\u65f6\uff0c\u4e0d\u9700\u8981\u4fdd\u7559\u51b3\u5b9a\u7269\u4f53\u4f4d\u7f6e\u7684\u5ea6\u91cf\u8ddd\u79bb\u3002</li>\n    <li>\u5728\u8bad\u7ec3\u540e\u5f3a\u8c03\u67d0\u4e2a\u8f93\u51fa\u63a5\u53e3\u53ef\u80fd\u5bfc\u81f4\u5176\u4ed6\u63a5\u53e3\u7684\u8f6c\u79fb\u6548\u679c\u8f83\u5f31\uff0c\u751a\u81f3\u6076\u5316\uff0c\u8fd9\u79cd\u73b0\u8c61\u79f0\u4e3a\u201c\u4e13\u95e8\u5316\u63a5\u53e3\u9501\u5b9a\u201d\u3002</li>\n    <li>ChronoReplay\u901a\u8fc7\u56de\u653e\u4e0d\u540c\u7684\u7a7a\u95f4\u76d1\u7763\uff0c\u4fdd\u6301\u539f\u59cb\u76ee\u6807\uff0c\u5e76\u5728\u4e0d\u540c\u7c7b\u522b\u95f4\u5e73\u8861\u76d1\u7763\uff0c\u6765\u89e3\u51b3\u63a5\u53e3\u9501\u5b9a\u95ee\u9898\u3002</li>\n    <li>\u4f7f\u7528ChronoReplay\u540e\uff0c\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\uff08\u5982OST-Bench\uff09\u8868\u73b0\u663e\u8457\u63d0\u5347\uff0c\u5176\u4e2dOST-Bench\u63d0\u9ad8\u4e8613.41\u5206\u3002</li>\n    <li>\u9002\u5e94\u6027\u5e27\u9009\u62e9\u5728\u4fdd\u6301\u6a21\u578b\u4e0d\u53d8\u7684\u60c5\u51b5\u4e0b\u6539\u53d8\u8bc1\u636e\u83b7\u53d6\uff0c\u4ece\u800c\u5728\u63a8\u7406\u65f6\u63d0\u4f9b\u989d\u5916\u6536\u76ca\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Training a spatial visual language model (VLM) to determine object positions can lead to specialization in certain areas, limiting its overall performance.</li>\n    <li>ChronoReplay is a method that improves this by using diverse spatial guidance in a structured way, which helps the model learn better across different tasks.</li>\n    <li>This method has shown significant improvements in performance on multiple benchmarks, including a notable 13.41-point increase on one specific benchmark.</li>\n    <li>Different techniques within ChronoReplay, like answer serialization and family-balanced learning, help distribute improvements effectively across tasks.</li>\n    <li>Adaptive frame selection further enhances model performance by optimizing evidence access during inference, leading to better results with less visual effort.</li>\n</ul>"}, "publishedAt": "2026-10-24T20:00:00.000Z", "title": "ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence", "summary": "Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, and balancing supervision across families. Under the same observation access, a single ChronoReplay checkpoint improves OVO-S-Bench, OST-Bench, and UCS-Bench together, including a 13.41-point gain on OST-Bench, and achieves the highest three-benchmark mean among the supervision settings compared here. Same-data controls further separate the ingredients of this transfer: answer serialization redistributes gains across OST and UCS, family-balanced learning improves over ordinary joint SFT and natural turn weighting, and chronological replay exceeds a shifted-order control by about 2.41 OST points across two paired seeds. Adaptive frame selection then changes evidence access while keeping the trained model fixed, providing an additional inference-time gain at lower visual cost. Streaming spatial performance depends on what distinctions supervision preserves, how heterogeneous histories are organized during learning, and what causal evidence inference makes available at test time.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.34283.png", "numComments": 1, "submittedBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "fullname": "Yihao Hu", "name": "HU22333", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6650967d53061f0d1b5a7962", "name": "LINs-lab", "fullname": "LINs lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65296b8a6cdea40585bd81e2/M80w6f0H8dfx3Sa1nVmfq.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.34662", "authors": [{"_id": "6ae00e8ba5efa215400a7919", "name": "Chengzhi Liu", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791a", "name": "Yuxiang Lai", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791b", "name": "Yuzhe Yang", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791c", "name": "Yanqing Liu", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791d", "name": "Jiheng Hou", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791e", "name": "Yue Cao", "hidden": false}, {"_id": "6ae00e8ba5efa215400a791f", "name": "Haonan Wang", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7920", "name": "Ruixi Fan", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7921", "name": "Lan Wang", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7922", "name": "Sheng Liu", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7923", "name": "Songyou Peng", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7924", "name": "Yale Song", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7925", "name": "Kevin Qinghong Lin", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7926", "name": "Xin Eric Wang", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7927", "name": "Jui-Hsin Lai", "hidden": false}, {"_id": "6ae00e8ba5efa215400a7928", "name": "Youbao Tang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65e71f6bcd3df9b0f6b2678b/rDRpHvKCWXNBtytJY3XjT.mp4"], "publishedAt": "2026-10-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-27T00:00:00.000Z", "title": "StreamVibe: Proactive Video Agents for Evolving User Intent", "submittedOnDailyBy": {"_id": "65e71f6bcd3df9b0f6b2678b", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/65e71f6bcd3df9b0f6b2678b/8mdex6eI80TGezot_GGI3.jpeg", "isPro": true, "fullname": "Chengzhi Liu", "user": "LCZZZZ", "type": "user", "name": "LCZZZZ"}, "summary": "Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., \"where should I click next?\" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation samples and 85K training samples spanning explicit, implicit, and dynamic intents. Building on this benchmark, we develop StreamVibe-VL, a streaming proactive model that infers implicit user intents from continuous observations and dynamically tailors its interactions as these intents evolve. We further introduce StreamVibe-Harness, which maintains user intents as persistent states with a fleixble lifecycles via a hierarchical memory to track the latest user intent and environmental state. Our experiments reveal three key findings: (i) StreamVibe-VL preserves strong general video understanding while improving response timing and answer quality by 10.7% over other baselines; (ii) existing proactive models remain limited in understanding user intent and deciding when to respond, especially under implicit and dynamic intents; and (iii) StreamVibe-Harness further improves response consistency and adaptation over sustained interaction, resulting in a 12.3% gain in proactive interaction.", "upvotes": 50, "discussionId": "6ae00e8ba5efa215400a7929", "ai_summary": "StreamVibe introduces a benchmark, streaming vision-language model, and hierarchical memory harness to enable proactive, intent-aware interaction with implicit and evolving user goals.", "ai_keywords": ["vision-language models", "implicit user intent", "dynamic intent", "StreamVibe-Bench", "StreamVibe-VL", "streaming proactive model", "StreamVibe-Harness", "hierarchical memory", "proactive interaction"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "5e6aca39878b8b2bf9806447", "name": "google", "fullname": "Google", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/WtA3YYitedOr9n02eHfJe.png"}, "summary_zh": "<ul>\n    <li>\u89c6\u89c9\u8bed\u8a00\u6a21\u578b\u6b63\u5728\u4ece\u88ab\u52a8\u7406\u89e3\u8f6c\u5411\u4e3b\u52a8\u4ea4\u4e92\uff0c\u4f46\u73b0\u6709\u65b9\u6cd5\u4e3b\u8981\u4f9d\u8d56\u660e\u786e\u8bf7\u6c42\uff0c\u5ffd\u89c6\u9690\u542b\u7528\u6237\u610f\u56fe\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\uff0c\u7814\u7a76\u56e2\u961f\u63a8\u51fa\u4e86StreamVibe-Bench\uff0c\u8fd9\u662f\u4e00\u4e2a\u7528\u4e8e\u7528\u6237\u610f\u56fe\u4ea4\u4e92\u7684\u65b0\u57fa\u51c6\uff0c\u5305\u542b4100\u4e2a\u8bc4\u4f30\u6837\u672c\u548c85000\u4e2a\u8bad\u7ec3\u6837\u672c\u3002</li>\n    <li>\u57fa\u4e8e\u8be5\u57fa\u51c6\uff0c\u5f00\u53d1\u4e86StreamVibe-VL\u6a21\u578b\uff0c\u53ef\u4ee5\u4ece\u8fde\u7eed\u89c2\u5bdf\u4e2d\u63a8\u65ad\u9690\u542b\u7528\u6237\u610f\u56fe\uff0c\u5e76\u6839\u636e\u8fd9\u4e9b\u610f\u56fe\u7684\u53d8\u5316\u8c03\u6574\u4ea4\u4e92\u3002</li>\n    <li>\u5f15\u5165\u4e86StreamVibe-Harness\uff0c\u901a\u8fc7\u5206\u5c42\u8bb0\u5fc6\u4fdd\u6301\u7528\u6237\u610f\u56fe\uff0c\u8ddf\u8e2a\u6700\u65b0\u7684\u7528\u6237\u610f\u56fe\u548c\u73af\u5883\u72b6\u6001\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0cStreamVibe-VL\u5728\u54cd\u5e94\u65f6\u673a\u548c\u56de\u7b54\u8d28\u91cf\u4e0a\u6bd4\u5176\u4ed6\u6a21\u578b\u63d0\u9ad8\u4e8610.7%\uff0c\u800cStreamVibe-Harness\u5728\u6301\u7eed\u4ea4\u4e92\u4e2d\u7684\u54cd\u5e94\u4e00\u81f4\u6027\u548c\u9002\u5e94\u6027\u63d0\u5347\u4e8612.3%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Vision-language models are evolving to interact with users in real-time instead of just understanding requests.</li>\n    <li>Current methods often miss subtle user intentions and struggle to keep up with changing user needs.</li>\n    <li>StreamVibe-Bench is a new benchmark with thousands of samples to evaluate how well models understand user intents.</li>\n    <li>StreamVibe-VL is a new model that learns to predict user intentions from ongoing observations and adapts its responses accordingly.</li>\n    <li>StreamVibe-Harness improves how the model tracks user intentions over time, leading to better interaction quality and consistency.</li>\n</ul>"}, "publishedAt": "2026-10-25T20:00:00.000Z", "title": "StreamVibe: Proactive Video Agents for Evolving User Intent", "summary": "Vision-language models are shifting from offline passive understanding toward online proactive interaction. However, prevailing methods largely rely on explicit requests while miss the implicit user intent (e.g., \"where should I click next?\" while a user navigate a website), meanwhile fail to update the state simultaneously as user requests might update continuously. These limitations make them less suited to intent-aware interaction in practical. To address these challenges, we introduce StreamVibe-Bench, a new benchmark serving as testbed for user intent interaction, with 4.1K evaluation samples and 85K training samples spanning explicit, implicit, and dynamic intents. Building on this benchmark, we develop StreamVibe-VL, a streaming proactive model that infers implicit user intents from continuous observations and dynamically tailors its interactions as these intents evolve. We further introduce StreamVibe-Harness, which maintains user intents as persistent states with a fleixble lifecycles via a hierarchical memory to track the latest user intent and environmental state. Our experiments reveal three key findings: (i) StreamVibe-VL preserves strong general video understanding while improving response timing and answer quality by 10.7% over other baselines; (ii) existing proactive models remain limited in understanding user intent and deciding when to respond, especially under implicit and dynamic intents; and (iii) StreamVibe-Harness further improves response consistency and adaptation over sustained interaction, resulting in a 12.3% gain in proactive interaction.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65e71f6bcd3df9b0f6b2678b/rDRpHvKCWXNBtytJY3XjT.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.34662.png", "numComments": 1, "submittedBy": {"_id": "65e71f6bcd3df9b0f6b2678b", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/65e71f6bcd3df9b0f6b2678b/8mdex6eI80TGezot_GGI3.jpeg", "fullname": "Chengzhi Liu", "name": "LCZZZZ", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "5e6aca39878b8b2bf9806447", "name": "google", "fullname": "Google", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/WtA3YYitedOr9n02eHfJe.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.36729", "authors": [{"_id": "6ae15718a5eb0647c2907149", "name": "Qiaoling Chen", "hidden": false}, {"_id": "6ae15718a5eb0647c290714a", "name": "Jiaxiang Cheng", "hidden": false}, {"_id": "6ae15718a5eb0647c290714b", "name": "Xueqing Deng", "hidden": false}, {"_id": "6ae15718a5eb0647c290714c", "name": "Tiankai Hang", "hidden": false}, {"_id": "6ae15718a5eb0647c290714d", "name": "Ji Hou", "hidden": false}, {"_id": "6ae15718a5eb0647c290714e", "name": "Jiaqi Li", "hidden": false}, {"_id": "6ae15718a5eb0647c290714f", "name": "Yifan Liu", "hidden": false}, {"_id": "6ae15718a5eb0647c2907150", "name": "Tao Lu", "hidden": false}, {"_id": "6ae15718a5eb0647c2907151", "name": "Junshu Tang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907152", "name": "Yu Tang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907153", "name": "Yao Teng", "hidden": false}, {"_id": "6ae15718a5eb0647c2907154", "name": "Yu Tian", "hidden": false}, {"_id": "6ae15718a5eb0647c2907155", "name": "Heng Wang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907156", "name": "Weizhi Wang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907157", "name": "Xiyao Wang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907158", "name": "Xilun Wu", "hidden": false}, {"_id": "6ae15718a5eb0647c2907159", "name": "Mingyu Yang", "hidden": false}, {"_id": "6ae15718a5eb0647c290715a", "name": "Yangbin Yu", "hidden": false}, {"_id": "6ae15718a5eb0647c290715b", "name": "Rui Zhao", "hidden": false}, {"_id": "6ae15718a5eb0647c290715c", "name": "Longjun Cao", "hidden": false}, {"_id": "6ae15718a5eb0647c290715d", "name": "Linghao Chen", "hidden": false}, {"_id": "6ae15718a5eb0647c290715e", "name": "Haoyi Duan", "hidden": false}, {"_id": "6ae15718a5eb0647c290715f", "name": "Jiaming Han", "hidden": false}, {"_id": "6ae15718a5eb0647c2907160", "name": "Mingji Han", "hidden": false}, {"_id": "6ae15718a5eb0647c2907161", "name": "Enhua Jiang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907162", "name": "Shunkai Li", "hidden": false}, {"_id": "6ae15718a5eb0647c2907163", "name": "Yanzhe Liang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907164", "name": "Qinwei Ma", "hidden": false}, {"_id": "6ae15718a5eb0647c2907165", "name": "Cong Wang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907166", "name": "Lei Wang", "hidden": false}, {"_id": "6ae15718a5eb0647c2907167", "name": "Bing Wu", "hidden": false}, {"_id": "6ae15718a5eb0647c2907168", "name": "Ke Xing", "hidden": false}, {"_id": "6ae15718a5eb0647c2907169", "name": "Ray Ying", "hidden": false}, {"_id": "6ae15718a5eb0647c290716a", "name": "Zhentao Yu", "hidden": false}, {"_id": "6ae15718a5eb0647c290716b", "name": "Key Zhang", "hidden": false}, {"_id": "6ae15718a5eb0647c290716c", "name": "Yuan Zhou", "hidden": false}, {"_id": "6ae15718a5eb0647c290716d", "name": "Zhengguang Zhou", "hidden": false}, {"_id": "6ae15718a5eb0647c290716e", "name": "Kai Zou", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63d34004b734eaa4d4faeccf/lOBvI5ytl4xxTPiMTwOCy.mp4"], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "Hy-Nomas: Towards Free-form Interactive World Generation", "submittedOnDailyBy": {"_id": "63d34004b734eaa4d4faeccf", "avatarUrl": "/avatars/7431a0177ac618bfcdffbf436e689acc.svg", "isPro": false, "fullname": "Weizhi Wang", "user": "weizhiwang", "type": "user", "name": "weizhiwang"}, "summary": "Interactive world generation requires models to follow successive commands while preserving relevant history and action consequences. We present Hy-Nomas, a video world model with an 8B diffusion backbone that supports free-form text instructions and continuous camera control across multiple interaction turns. It generates variable-length segments conditioned on current inputs and cached history. Our central design aligns structured video captions with action-aware causal attention: descriptive context remains accessible across segments, while action instructions are restricted to their intended temporal windows. A vision-language Prompt Enhancer (PE) translates user requests and multimodal interaction histories into structured conditions for the next segment. A multi-stage curriculum progressively introduces causal generation, text interaction, camera control, and training on model-generated histories, followed by diffusion distillation. In human evaluation, Hy-Nomas shows superior performance over existing world models. We release model weights, code and benchmarks, together with a lightweight adaptation workflow, to support reproducible research on interactive world generation.", "upvotes": 49, "discussionId": "6ae15718a5eb0647c290716f", "projectPage": "https://hy-nomas.hy.tencent.com/", "githubRepo": "https://github.com/Tencent-Hunyuan/Hy-Nomas", "githubRepoAddedBy": "user", "ai_summary": "Hy-Nomas is a video world model that uses causal attention and structured captions to follow multi-turn text and camera instructions while preserving interaction history.", "ai_keywords": ["video world model", "diffusion backbone", "action-aware causal attention", "vision-language Prompt Enhancer", "multi-stage curriculum", "diffusion distillation", "interactive world generation"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 274, "organization": {"_id": "6645f953c39288df638dbdd5", "name": "Tencent-Hunyuan", "fullname": "Tencent Hunyuan", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/62d22496c58f969c152bcefd/woKSjt2wXvBNKussyYPsa.png"}, "summary_zh": "<ul>\n    <li>Hy-Nomas \u662f\u4e00\u79cd\u89c6\u9891\u4e16\u754c\u6a21\u578b\uff0c\u80fd\u591f\u6839\u636e\u7528\u6237\u7684\u6587\u672c\u6307\u4ee4\u548c\u76f8\u673a\u63a7\u5236\u751f\u6210\u4e92\u52a8\u5185\u5bb9\u3002</li>\n    <li>\u8be5\u6a21\u578b\u4f7f\u7528 8B \u7684\u6269\u6563\u57fa\u7840\u67b6\u6784\uff0c\u652f\u6301\u591a\u8f6e\u4ea4\u4e92\uff0c\u5e76\u80fd\u8bb0\u4f4f\u5386\u53f2\u548c\u884c\u52a8\u540e\u679c\u3002</li>\n    <li>Hy-Nomas \u901a\u8fc7\u7ed3\u6784\u5316\u89c6\u9891\u6807\u9898\u548c\u56e0\u679c\u6ce8\u610f\u529b\u5bf9\u9f50\uff0c\u786e\u4fdd\u63cf\u8ff0\u6027\u4e0a\u4e0b\u6587\u5728\u4e0d\u540c\u6bb5\u843d\u4e4b\u95f4\u53ef\u7528\u3002</li>\n    <li>\u6a21\u578b\u4e2d\u4f7f\u7528\u7684\u89c6\u89c9-\u8bed\u8a00\u63d0\u793a\u589e\u5f3a\u5668\u5c06\u7528\u6237\u8bf7\u6c42\u8f6c\u6362\u4e3a\u4e0b\u4e00\u4e2a\u6bb5\u843d\u7684\u7ed3\u6784\u5316\u6761\u4ef6\u3002</li>\n    <li>\u5728\u4eba\u7c7b\u8bc4\u4f30\u4e2d\uff0cHy-Nomas \u7684\u8868\u73b0\u4f18\u4e8e\u73b0\u6709\u7684\u4e16\u754c\u6a21\u578b\uff0c\u5e76\u63d0\u4f9b\u4e86\u4ee3\u7801\u548c\u57fa\u51c6\uff0c\u652f\u6301\u53ef\u91cd\u590d\u7684\u7814\u7a76\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Hy-Nomas is a video world model that can follow commands and remember past actions.</li>\n    <li>It creates video segments based on user instructions and previous interactions, allowing for flexible storytelling.</li>\n    <li>The model uses a special design that keeps relevant context and action instructions in sync.</li>\n    <li>A Prompt Enhancer helps translate user requests into structured inputs for better video generation.</li>\n    <li>Hy-Nomas outperforms other models in tests, and its resources are available for research purposes.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "Hy-Nomas: Towards Free-form Interactive World Generation", "summary": "Interactive world generation requires models to follow successive commands while preserving relevant history and action consequences. We present Hy-Nomas, a video world model with an 8B diffusion backbone that supports free-form text instructions and continuous camera control across multiple interaction turns. It generates variable-length segments conditioned on current inputs and cached history. Our central design aligns structured video captions with action-aware causal attention: descriptive context remains accessible across segments, while action instructions are restricted to their intended temporal windows. A vision-language Prompt Enhancer (PE) translates user requests and multimodal interaction histories into structured conditions for the next segment. A multi-stage curriculum progressively introduces causal generation, text interaction, camera control, and training on model-generated histories, followed by diffusion distillation. In human evaluation, Hy-Nomas shows superior performance over existing world models. We release model weights, code and benchmarks, together with a lightweight adaptation workflow, to support reproducible research on interactive world generation.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63d34004b734eaa4d4faeccf/lOBvI5ytl4xxTPiMTwOCy.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.36729.png", "numComments": 1, "submittedBy": {"_id": "63d34004b734eaa4d4faeccf", "avatarUrl": "/avatars/7431a0177ac618bfcdffbf436e689acc.svg", "fullname": "Weizhi Wang", "name": "weizhiwang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 23, "isUserFollowing": false}, "organization": {"_id": "6645f953c39288df638dbdd5", "name": "Tencent-Hunyuan", "fullname": "Tencent Hunyuan", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/62d22496c58f969c152bcefd/woKSjt2wXvBNKussyYPsa.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.35684", "authors": [{"_id": "6ae2bb70d670fc6ea896c825", "name": "Junyeong Ahn", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c826", "name": "Geonwoo Kim", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c827", "name": "Kinam Kim", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c828", "name": "Gihwi Kim", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c829", "name": "Hoonjin Jung", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c82a", "name": "Hyojin Jang", "hidden": false}, {"_id": "6ae2bb70d670fc6ea896c82b", "name": "Jaegul Choo", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/632872d5ed473b0259e482fa/eEUbC0NeLSc1fr70XJZGw.mp4"], "publishedAt": "2026-10-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-29T00:00:00.000Z", "title": "OmniShowcase: Omnidirectional Subject-Consistent Video Generation from Multi-View Images", "submittedOnDailyBy": {"_id": "632872d5ed473b0259e482fa", "avatarUrl": "/avatars/f05033fdcc255b4d5eb15109f3043c22.svg", "isPro": false, "fullname": "Junyeong Ahn", "user": "Justin4AI", "type": "user", "name": "Justin4AI"}, "summary": "Generating videos of a specific subject from a few reference images remains challenging when the camera reveals surfaces that are not visible in the input. Early subject-to-video (S2V) methods condition on a single reference image and must therefore infer the subject's unseen appearance and geometry as the viewpoint changes. To address this limitation, recent methods extend S2V to multiple reference views, providing more information about the subject from different viewpoints. However, they do not explicitly specify the 3D structure that connects these observations. In addition, existing training data do not guarantee that viewpoint changes preserve the same underlying 3D subject. We present OmniShowcase, built on two components: (i) a fully automated data synthesis pipeline that produces training videos along diverse camera trajectories, with viewpoint variation driven by underlying subject geometry, even spanning full 360-degree orbits; and (ii) a geometry-conditioning method that provides the video model with a turntable of surface-normal maps reconstructed from the reference views without requiring temporal alignment with the generated frames. We construct Showcase-4K, a corpus of 3D-asset-based videos covering twelve camera motions across 88 trajectory configurations with reconstruction-derived surface-normal conditioning, and ShowcaseBench, a held-out evaluation set with the source meshes and camera parameters used to render each video. Experiments show state-of-the-art subject identity and 3D consistency while maintaining competitive video quality and motion. Project page: justin4ai.github.io/OmniShowcase", "upvotes": 47, "discussionId": "6ae2bb71d670fc6ea896c82c", "projectPage": "https://justin4ai.github.io/OmniShowcase/", "githubRepo": "https://github.com/justin4ai/OmniShowcase", "githubRepoAddedBy": "user", "ai_summary": "OmniShowcase improves subject-to-video generation by using geometry-driven training data and surface-normal conditioning to maintain 3D consistency across novel viewpoints.", "ai_keywords": ["subject-to-video", "surface-normal maps", "geometry-conditioning", "3D consistency", "data synthesis pipeline", "camera trajectories"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 10, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u521b\u5efa\u89c6\u9891\u65f6\uff0c\u4f7f\u7528\u5c11\u91cf\u53c2\u8003\u56fe\u50cf\u6765\u751f\u6210\u7279\u5b9a\u4e3b\u9898\u7684\u89c6\u9891\u4ecd\u7136\u5b58\u5728\u6311\u6218\u3002</li>\n    <li>\u4f20\u7edf\u65b9\u6cd5\u4f9d\u8d56\u5355\u4e2a\u53c2\u8003\u56fe\u50cf\uff0c\u65e0\u6cd5\u51c6\u786e\u63a8\u65ad\u4e3b\u9898\u5728\u4e0d\u540c\u89c6\u89d2\u4e0b\u7684\u5916\u89c2\u548c\u51e0\u4f55\u5f62\u72b6\u3002</li>\n    <li>\u65b0\u65b9\u6cd5\u4f7f\u7528\u591a\u4e2a\u53c2\u8003\u89c6\u89d2\uff0c\u4f46\u672a\u660e\u786e\u6307\u5b9a3D\u7ed3\u6784\u8fde\u63a5\u8fd9\u4e9b\u89c2\u5bdf\u7ed3\u679c\u3002</li>\n    <li>\u63d0\u51fa\u7684OmniShowcase\u5305\u62ec\u81ea\u52a8\u6570\u636e\u5408\u6210\u7ba1\u9053\u548c\u51e0\u4f55\u6761\u4ef6\u65b9\u6cd5\uff0c\u4ee5\u6539\u5584\u89c6\u9891\u751f\u6210\u3002</li>\n    <li>\u6784\u5efa\u4e86Showcase-4K\u548cShowcaseBench\u6570\u636e\u96c6\uff0c\u5c55\u793a\u4e86\u4f18\u8d8a\u7684\u4e3b\u9898\u4e00\u81f4\u6027\u548c3D\u7a33\u5b9a\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Creating videos from a few images of a subject is tough, especially when parts of the subject are hidden from view.</li>\n    <li>Newer methods use multiple images to understand the subject better from different angles, but they don't clearly define the 3D shape of the subject.</li>\n    <li>OmniShowcase is a new system that uses automated tools to generate training videos with various camera angles based on the subject's 3D shape.</li>\n    <li>It includes a method to help video models understand the subject's surface details without needing to match them with specific video frames.</li>\n    <li>The system features Showcase-4K, a collection of videos showing 3D models from different camera movements, and ShowcaseBench, a test set for evaluating performance.</li>\n</ul>"}, "publishedAt": "2026-10-25T20:00:00.000Z", "title": "OmniShowcase: Omnidirectional Subject-Consistent Video Generation from Multi-View Images", "summary": "Generating videos of a specific subject from a few reference images remains challenging when the camera reveals surfaces that are not visible in the input. Early subject-to-video (S2V) methods condition on a single reference image and must therefore infer the subject's unseen appearance and geometry as the viewpoint changes. To address this limitation, recent methods extend S2V to multiple reference views, providing more information about the subject from different viewpoints. However, they do not explicitly specify the 3D structure that connects these observations. In addition, existing training data do not guarantee that viewpoint changes preserve the same underlying 3D subject. We present OmniShowcase, built on two components: (i) a fully automated data synthesis pipeline that produces training videos along diverse camera trajectories, with viewpoint variation driven by underlying subject geometry, even spanning full 360-degree orbits; and (ii) a geometry-conditioning method that provides the video model with a turntable of surface-normal maps reconstructed from the reference views without requiring temporal alignment with the generated frames. We construct Showcase-4K, a corpus of 3D-asset-based videos covering twelve camera motions across 88 trajectory configurations with reconstruction-derived surface-normal conditioning, and ShowcaseBench, a held-out evaluation set with the source meshes and camera parameters used to render each video. Experiments show state-of-the-art subject identity and 3D consistency while maintaining competitive video quality and motion. Project page: justin4ai.github.io/OmniShowcase", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/632872d5ed473b0259e482fa/eEUbC0NeLSc1fr70XJZGw.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.35684.png", "numComments": 2, "submittedBy": {"_id": "632872d5ed473b0259e482fa", "avatarUrl": "/avatars/f05033fdcc255b4d5eb15109f3043c22.svg", "fullname": "Junyeong Ahn", "name": "Justin4AI", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.36068", "authors": [{"_id": "6ae1517da5eb0647c29070f8", "name": "Jiayi Luo", "hidden": false}, {"_id": "6ae1517da5eb0647c29070f9", "name": "Yang Zhang", "hidden": false}, {"_id": "6ae1517da5eb0647c29070fa", "name": "Liliang Chen", "hidden": false}, {"_id": "6ae1517da5eb0647c29070fb", "name": "Nan Wang", "hidden": false}, {"_id": "6ae1517da5eb0647c29070fc", "name": "Chen Gao", "hidden": false}, {"_id": "6ae1517da5eb0647c29070fd", "name": "Boxiang Qiu", "hidden": false}, {"_id": "6ae1517da5eb0647c29070fe", "name": "Zhuoxuan Li", "hidden": false}, {"_id": "6ae1517da5eb0647c29070ff", "name": "Baorui Peng", "hidden": false}, {"_id": "6ae1517da5eb0647c2907100", "name": "Chuankang Li", "hidden": false}, {"_id": "6ae1517da5eb0647c2907101", "name": "Yuxiang Yan", "hidden": false}, {"_id": "6ae1517da5eb0647c2907102", "name": "Si Liu", "hidden": false}, {"_id": "6ae1517da5eb0647c2907103", "name": "Qingyun Sun", "hidden": false}, {"_id": "6ae1517da5eb0647c2907104", "name": "Shuicheng Yan", "hidden": false}, {"_id": "6ae1517da5eb0647c2907105", "name": "Maoqing Yao", "hidden": false}, {"_id": "6ae1517da5eb0647c2907106", "name": "Jianxin Li", "hidden": false}, {"_id": "6ae1517da5eb0647c2907107", "name": "Guanghui Ren", "hidden": false}], "publishedAt": "2026-10-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "Rollback: Experience Backtracking in World Models for Policy Improvement", "submittedOnDailyBy": {"_id": "66c4816e96583c59b09fec30", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/66c4816e96583c59b09fec30/RLurCsmcgOfyuWVkpsv1L.jpeg", "isPro": false, "fullname": "Ryan Chen", "user": "ryancll118", "type": "user", "name": "ryancll118"}, "summary": "Action-conditioned world models offer a scalable alternative to costly real-world interaction for improving robot policies. However, existing world-model-based methods largely treat world models as forward-only surrogates of the physical environment, leaving untapped a capability no physical environment affords: rewinding to past decision points to explore counterfactual futures. We introduce Rollback, a policy improvement paradigm that turns world models from passive simulators into counterfactual engines: it rolls back to critical decision points, branches into alternative actions, and contrasts their outcomes to attribute success to individual decisions. This concentrates imagination where it matters most and distills counterfactual outcomes into fine-grained, action-level supervision without a separately learned value model. We build a scalable training system that unifies distributed world-model search with asynchronous real-robot execution, forming a self-reinforcing cycle: real-world experience continually sharpens the world model, and a sharper world model in turn drives further policy improvement. We term the world-model side of this cycle test-time physics grounding, a capability that hand-built physics simulators lack: while the world model serves as the training environment, real transitions from the policy it trains correct its dynamics through a lightweight LoRA pipeline. Experiments on three challenging real-world tasks show that Rollback improves success rates over the strongest baseline by an absolute 10.67%, 11.11%, and 11.85% on block extraction, ball tossing, and tabletop curling, respectively, while achieving more stable improvement throughout training. Although initialized from teleoperated demonstrations far below human level, Rollback surpasses the average success rate of human players on both ball tossing and tabletop curling within 8 hours of training.", "upvotes": 41, "discussionId": "6ae1517ea5eb0647c2907108", "projectPage": "https://rollback-wm.github.io/", "ai_summary": "Rollback improves robot policies by using world models to rewind to past decisions, explore counterfactual actions, and generate fine-grained supervision, while continuously refining dynamics via real-world feedback.", "ai_keywords": ["action-conditioned world models", "counterfactual futures", "Rollback", "world-model search", "test-time physics grounding", "LoRA", "distributed search", "asynchronous execution"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "676fc7c31c48eff17fac3135", "name": "agibot-world", "fullname": "AgiBot World", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64e57309b78bc92221ce3b70/ewI1QvFVMDgSsShQeSvlX.png"}, "summary_zh": "<ul>\n  <li>\u884c\u52a8\u6761\u4ef6\u7684\u4e16\u754c\u6a21\u578b\u4e3a\u673a\u5668\u4eba\u653f\u7b56\u63d0\u4f9b\u4e86\u4e00\u79cd\u53ef\u6269\u5c55\u7684\u66ff\u4ee3\u65b9\u6848\uff0c\u51cf\u5c11\u4e86\u4e0e\u73b0\u5b9e\u4e16\u754c\u4ea4\u4e92\u7684\u6210\u672c\u3002</li>\n  <li>\u73b0\u6709\u7684\u4e16\u754c\u6a21\u578b\u65b9\u6cd5\u4e3b\u8981\u5c06\u5176\u89c6\u4e3a\u7269\u7406\u73af\u5883\u7684\u524d\u5411\u4ee3\u7406\uff0c\u672a\u80fd\u5229\u7528\u56de\u6eaf\u5230\u8fc7\u53bb\u51b3\u7b56\u70b9\u7684\u80fd\u529b\u3002</li>\n  <li>\u6211\u4eec\u63d0\u51fa\u4e86\u201c\u56de\u6eda\u201d\u7b56\u7565\u6539\u5584\u8303\u5f0f\uff0c\u5c06\u4e16\u754c\u6a21\u578b\u8f6c\u53d8\u4e3a\u53cd\u4e8b\u5b9e\u5f15\u64ce\uff0c\u901a\u8fc7\u56de\u6eaf\u548c\u5206\u652f\u63a2\u7d22\u4e0d\u540c\u7684\u884c\u52a8\u53ca\u5176\u7ed3\u679c\u3002</li>\n  <li>\u8fd9\u4e2a\u7cfb\u7edf\u7ed3\u5408\u4e86\u5206\u5e03\u5f0f\u4e16\u754c\u6a21\u578b\u641c\u7d22\u4e0e\u5f02\u6b65\u771f\u5b9e\u673a\u5668\u4eba\u6267\u884c\uff0c\u5f62\u6210\u81ea\u6211\u5f3a\u5316\u7684\u5faa\u73af\uff0c\u63d0\u5347\u4e86\u653f\u7b56\u6539\u5584\u6548\u679c\u3002</li>\n  <li>\u5728\u4e09\u4e2a\u5b9e\u4e16\u754c\u4efb\u52a1\u4e2d\u7684\u5b9e\u9a8c\u8868\u660e\uff0c\u56de\u6eda\u65b9\u6cd5\u7684\u6210\u529f\u7387\u6bd4\u6700\u5f3a\u57fa\u7ebf\u63d0\u9ad8\u4e8610.67%\u300111.11%\u548c11.85%\uff0c\u5e76\u5728\u8bad\u7ec3\u8fc7\u7a0b\u4e2d\u8868\u73b0\u51fa\u66f4\u7a33\u5b9a\u7684\u8fdb\u6b65\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Action-conditioned world models help robots learn better without needing expensive real-world trials.</li>\n    <li>The new method, Rollback, allows robots to revisit past decisions and explore different actions to see their effects.</li>\n    <li>Rollback improves robot training by focusing on important decisions and providing detailed feedback on actions.</li>\n    <li>This method combines real-world robot experiences with simulations to continually enhance the training process.</li>\n    <li>Experiments show Rollback significantly increases success rates in tasks like block extraction and ball tossing, outperforming human players after just 8 hours of training.</li>\n</ul>"}, "publishedAt": "2026-10-25T20:00:00.000Z", "title": "Rollback: Experience Backtracking in World Models for Policy Improvement", "summary": "Action-conditioned world models offer a scalable alternative to costly real-world interaction for improving robot policies. However, existing world-model-based methods largely treat world models as forward-only surrogates of the physical environment, leaving untapped a capability no physical environment affords: rewinding to past decision points to explore counterfactual futures. We introduce Rollback, a policy improvement paradigm that turns world models from passive simulators into counterfactual engines: it rolls back to critical decision points, branches into alternative actions, and contrasts their outcomes to attribute success to individual decisions. This concentrates imagination where it matters most and distills counterfactual outcomes into fine-grained, action-level supervision without a separately learned value model. We build a scalable training system that unifies distributed world-model search with asynchronous real-robot execution, forming a self-reinforcing cycle: real-world experience continually sharpens the world model, and a sharper world model in turn drives further policy improvement. We term the world-model side of this cycle test-time physics grounding, a capability that hand-built physics simulators lack: while the world model serves as the training environment, real transitions from the policy it trains correct its dynamics through a lightweight LoRA pipeline. Experiments on three challenging real-world tasks show that Rollback improves success rates over the strongest baseline by an absolute 10.67%, 11.11%, and 11.85% on block extraction, ball tossing, and tabletop curling, respectively, while achieving more stable improvement throughout training. Although initialized from teleoperated demonstrations far below human level, Rollback surpasses the average success rate of human players on both ball tossing and tabletop curling within 8 hours of training.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.36068.png", "numComments": 1, "submittedBy": {"_id": "66c4816e96583c59b09fec30", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/66c4816e96583c59b09fec30/RLurCsmcgOfyuWVkpsv1L.jpeg", "fullname": "Ryan Chen", "name": "ryancll118", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 4, "isUserFollowing": false}, "organization": {"_id": "676fc7c31c48eff17fac3135", "name": "agibot-world", "fullname": "AgiBot World", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64e57309b78bc92221ce3b70/ewI1QvFVMDgSsShQeSvlX.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.37666", "authors": [{"_id": "6ae15d93a5eb0647c2907233", "name": "Chaehyun Kim", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907234", "name": "Chi-Pin Huang", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907235", "name": "Jisoo Kim", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907236", "name": "Min-Hung Chen", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907237", "name": "Yu-Chiang Frank Wang", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907238", "name": "Seungryong Kim", "hidden": false}, {"_id": "6ae15d93a5eb0647c2907239", "name": "Fu-En Yang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63f727b1bd28622c9b951114/upl0lRpybvBMpqUSl4LGv.mp4"], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "ThinkWorld: World Imagination Reinforces Chain-of-Dynamics Reasoning", "submittedOnDailyBy": {"_id": "63f727b1bd28622c9b951114", "avatarUrl": "/avatars/0b52ae1ff473615fdd665cdbc91f6db9.svg", "isPro": true, "fullname": "Chaehyun Kim", "user": "chyun", "type": "user", "name": "chyun"}, "summary": "Vision-Language-Action (VLA) models have made substantial progress in robotic manipulation, but their generalization remains constrained by the diversity and coverage of action-labeled robot demonstrations. Human videos provide much broader behavioral and environmental experience, while learning from them faces a fundamental trade-off between scalable data and explicit action grounding. We introduce ThinkWorld, a VLA learning framework that grounds action reasoning in world dynamics and strengthens it through reinforcement learning with world imagination. ThinkWorld represents each action thought as a Chain-of-Dynamics (CoD), a sequence of discrete motion tokens that captures the intermediate dynamics connecting the current world to a future state and serves as a common action representation across embodiments. We first initialize CoD with action-labeled demonstrations, then predict the future induced by each CoD and reinforce those whose predictions better match the observed outcome. This enables videos without action annotations to provide direct supervision from observed state transitions, allowing human and robot experience to refine the same reasoning space. Experiments in simulation and on real robots demonstrate effective human-to-robot transfer and strong generalization to unseen tasks and environments.", "upvotes": 36, "discussionId": "6ae15d94a5eb0647c290723a", "projectPage": "https://thinkworld-project.github.io/", "ai_summary": "ThinkWorld improves robotic generalization by representing actions as dynamics chains and using world imagination to learn from unlabeled human videos.", "ai_keywords": ["Vision-Language-Action models", "Chain-of-Dynamics", "motion tokens", "world dynamics", "reinforcement learning", "world imagination"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>Vision-Language-Action (VLA) \u6a21\u578b\u5728\u673a\u5668\u4eba\u64cd\u4f5c\u65b9\u9762\u53d6\u5f97\u4e86\u663e\u8457\u8fdb\u5c55\uff0c\u4f46\u5176\u6cdb\u5316\u80fd\u529b\u53d7\u5230\u52a8\u4f5c\u6807\u8bb0\u793a\u8303\u591a\u6837\u6027\u7684\u9650\u5236\u3002</li>\n    <li>\u4eba\u7c7b\u89c6\u9891\u63d0\u4f9b\u4e86\u66f4\u5e7f\u6cdb\u7684\u884c\u4e3a\u548c\u73af\u5883\u7ecf\u9a8c\uff0c\u4f46\u4ece\u4e2d\u5b66\u4e60\u9762\u4e34\u6570\u636e\u53ef\u6269\u5c55\u6027\u4e0e\u660e\u786e\u52a8\u4f5c\u57fa\u7840\u4e4b\u95f4\u7684\u6743\u8861\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86 ThinkWorld \u6846\u67b6\uff0c\u901a\u8fc7\u4e16\u754c\u52a8\u6001\u6765\u52a0\u5f3a\u884c\u52a8\u63a8\u7406\uff0c\u5e76\u5229\u7528\u5f3a\u5316\u5b66\u4e60\u8fdb\u884c\u4e16\u754c\u60f3\u8c61\u3002</li>\n    <li>ThinkWorld \u5c06\u6bcf\u4e2a\u52a8\u4f5c\u601d\u7ef4\u8868\u793a\u4e3a\u52a8\u6001\u94fe\uff08Chain-of-Dynamics\uff0cCoD\uff09\uff0c\u6355\u6349\u5f53\u524d\u4e16\u754c\u5230\u672a\u6765\u72b6\u6001\u7684\u52a8\u6001\u8fde\u63a5\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cThinkWorld \u5728\u4eff\u771f\u548c\u771f\u5b9e\u673a\u5668\u4eba\u4e0a\u6709\u6548\u5b9e\u73b0\u4e86\u4eba\u7c7b\u5230\u673a\u5668\u4eba\u7684\u77e5\u8bc6\u8f6c\u79fb\uff0c\u5e76\u5bf9\u672a\u89c1\u8fc7\u7684\u4efb\u52a1\u548c\u73af\u5883\u5177\u6709\u826f\u597d\u7684\u6cdb\u5316\u80fd\u529b\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Vision-Language-Action (VLA) models help robots with manipulation, but they need better action data for generalization.</li>\n    <li>ThinkWorld is a new framework that uses human videos to improve robot learning by combining action reasoning with world dynamics.</li>\n    <li>Actions are represented as a Chain-of-Dynamics (CoD), which connects current actions to future outcomes.</li>\n    <li>CoD is initially based on labeled demonstrations, and it improves by predicting and reinforcing actions based on real outcomes.</li>\n    <li>Experiments show that this approach helps robots learn effectively from human experiences and adapt to new tasks and environments.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "ThinkWorld: World Imagination Reinforces Chain-of-Dynamics Reasoning", "summary": "Vision-Language-Action (VLA) models have made substantial progress in robotic manipulation, but their generalization remains constrained by the diversity and coverage of action-labeled robot demonstrations. Human videos provide much broader behavioral and environmental experience, while learning from them faces a fundamental trade-off between scalable data and explicit action grounding. We introduce ThinkWorld, a VLA learning framework that grounds action reasoning in world dynamics and strengthens it through reinforcement learning with world imagination. ThinkWorld represents each action thought as a Chain-of-Dynamics (CoD), a sequence of discrete motion tokens that captures the intermediate dynamics connecting the current world to a future state and serves as a common action representation across embodiments. We first initialize CoD with action-labeled demonstrations, then predict the future induced by each CoD and reinforce those whose predictions better match the observed outcome. This enables videos without action annotations to provide direct supervision from observed state transitions, allowing human and robot experience to refine the same reasoning space. Experiments in simulation and on real robots demonstrate effective human-to-robot transfer and strong generalization to unseen tasks and environments.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/63f727b1bd28622c9b951114/upl0lRpybvBMpqUSl4LGv.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.37666.png", "numComments": 1, "submittedBy": {"_id": "63f727b1bd28622c9b951114", "avatarUrl": "/avatars/0b52ae1ff473615fdd665cdbc91f6db9.svg", "fullname": "Chaehyun Kim", "name": "chyun", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.36456", "authors": [{"_id": "6ae14bb6a5eb0647c29070c7", "name": "Yuxuan Chen", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070c8", "name": "Feng Xie", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070c9", "name": "Jiagao Hu", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070ca", "name": "Fuhao Li", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070cb", "name": "Zepeng Wang", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070cc", "name": "Fei Wang", "hidden": false}, {"_id": "6ae14bb6a5eb0647c29070cd", "name": "Daiguo Zhou", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/649176436cadae13f22d014b/5rZZkERA6tUqDATPYhbhm.mp4"], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "LociArt: A Unified Paradigm for Free-Style Local Video Stylization", "submittedOnDailyBy": {"_id": "649176436cadae13f22d014b", "avatarUrl": "/avatars/2cab0804761d986e2769d68063a59081.svg", "isPro": false, "fullname": "Higher", "user": "HigherHu", "type": "user", "name": "HigherHu"}, "summary": "Video stylization typically transforms entire scenes, while local artistic editing requires precise region--style association, spatial control, and temporal consistency. We introduce LociArt, a unified paradigm for free-style local video stylization that explicitly specifies where to stylize and what style to apply while preserving non-target content. At its core, GRNStyle builds on Generative Refinement Networks (GRN) and introduces a polar style-aware mask that embeds style identities as equal-norm directions within selected regions. Complementary representation--geometry conditioning combines encoded mask features with raw-mask spatial support, integrating spatiotemporal context with geometric control. To provide paired supervision, we develop an automated pipeline combining global stylization, video object removal, matting, and compositing, and construct the LociArt-100K Dataset with 100K local stylization pairs. We further establish the LociArt Benchmark, comprising 80 source videos and 84 target masks covering 168 foreground/background stylization cases, with a Style Prototype Similarity (SPS) evaluation scheme for regional style quality and complementary measures of non-target preservation and temporal consistency. Experiments show that GRNStyle outperforms existing methods in regional style quality and spatial control while maintaining strong temporal consistency. Qualitative examples further illustrate joint stylization of multiple regions with the same or different learned styles, despite training only on single-region, single-style pairs. Together, these components provide a unified foundation for learning and evaluating controllable local video stylization. Project page: https://higherhu.github.io/lociart/.", "upvotes": 25, "discussionId": "6ae14bb6a5eb0647c29070ce", "projectPage": "https://higherhu.github.io/lociart/", "ai_summary": "LociArt enables precise local video stylization with region-style control and temporal consistency via a generative refinement network, automated dataset construction, and a dedicated benchmark.", "ai_keywords": ["Generative Refinement Networks", "polar style-aware mask", "representation-geometry conditioning", "LociArt-100K Dataset", "Style Prototype Similarity", "local video stylization", "temporal consistency"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "6821ba7e5a7efab94a235406", "name": "xiaomi-research", "fullname": "Xiaomi Research", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/673735e4373ad40af7f81ea1/DR4m0bz2Du1l0Z8Txg351.png"}, "summary_zh": "<ul>\n  <li>\u63d0\u51fa\u4e86LociArt\uff0c\u4e00\u4e2a\u7528\u4e8e\u81ea\u7531\u98ce\u683c\u5c40\u90e8\u89c6\u9891\u98ce\u683c\u5316\u7684\u7edf\u4e00\u6846\u67b6\u3002</li>\n  <li>\u8be5\u65b9\u6cd5\u53ef\u4ee5\u7cbe\u786e\u6307\u5b9a\u98ce\u683c\u5316\u533a\u57df\u548c\u5e94\u7528\u7684\u98ce\u683c\uff0c\u540c\u65f6\u4fdd\u7559\u975e\u76ee\u6807\u5185\u5bb9\u3002</li>\n  <li>\u4f7f\u7528\u751f\u6210\u7ec6\u5316\u7f51\u7edc\uff08GRN\uff09\u548c\u6781\u6027\u98ce\u683c\u611f\u77e5\u63a9\u819c\u6765\u5b9e\u73b0\u98ce\u683c\u5316\u3002</li>\n  <li>\u5f00\u53d1\u4e86LociArt-100K\u6570\u636e\u96c6\u548cLociArt\u57fa\u51c6\uff0c\u4ee5\u8bc4\u4f30\u533a\u57df\u98ce\u683c\u8d28\u91cf\u548c\u65f6\u95f4\u4e00\u81f4\u6027\u3002</li>\n  <li>\u5b9e\u9a8c\u8868\u660e\uff0cGRNStyle\u5728\u533a\u57df\u98ce\u683c\u8d28\u91cf\u548c\u7a7a\u95f4\u63a7\u5236\u65b9\u9762\u4f18\u4e8e\u73b0\u6709\u65b9\u6cd5\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>LociArt is a new method for local video stylization that allows users to specify exactly where and what style to apply without changing other content.</li>\n    <li>It uses Generative Refinement Networks (GRN) with a special mask that helps apply styles in selected areas while keeping the overall look consistent.</li>\n    <li>The method includes a pipeline that automates processes like global stylization and video editing, and it has created a dataset with 100,000 examples of local stylization.</li>\n    <li>LociArt also features a benchmark with 80 source videos and 84 target masks to test and evaluate the quality of regional styles and consistency over time.</li>\n    <li>Experiments show that LociArt achieves better regional style quality and control compared to previous methods while also maintaining good consistency throughout the video.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "LociArt: A Unified Paradigm for Free-Style Local Video Stylization", "summary": "Video stylization typically transforms entire scenes, while local artistic editing requires precise region--style association, spatial control, and temporal consistency. We introduce LociArt, a unified paradigm for free-style local video stylization that explicitly specifies where to stylize and what style to apply while preserving non-target content. At its core, GRNStyle builds on Generative Refinement Networks (GRN) and introduces a polar style-aware mask that embeds style identities as equal-norm directions within selected regions. Complementary representation--geometry conditioning combines encoded mask features with raw-mask spatial support, integrating spatiotemporal context with geometric control. To provide paired supervision, we develop an automated pipeline combining global stylization, video object removal, matting, and compositing, and construct the LociArt-100K Dataset with 100K local stylization pairs. We further establish the LociArt Benchmark, comprising 80 source videos and 84 target masks covering 168 foreground/background stylization cases, with a Style Prototype Similarity (SPS) evaluation scheme for regional style quality and complementary measures of non-target preservation and temporal consistency. Experiments show that GRNStyle outperforms existing methods in regional style quality and spatial control while maintaining strong temporal consistency. Qualitative examples further illustrate joint stylization of multiple regions with the same or different learned styles, despite training only on single-region, single-style pairs. Together, these components provide a unified foundation for learning and evaluating controllable local video stylization. Project page: https://higherhu.github.io/lociart/.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/649176436cadae13f22d014b/5rZZkERA6tUqDATPYhbhm.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.36456.png", "numComments": 1, "submittedBy": {"_id": "649176436cadae13f22d014b", "avatarUrl": "/avatars/2cab0804761d986e2769d68063a59081.svg", "fullname": "Higher", "name": "HigherHu", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6821ba7e5a7efab94a235406", "name": "xiaomi-research", "fullname": "Xiaomi Research", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/673735e4373ad40af7f81ea1/DR4m0bz2Du1l0Z8Txg351.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.37230", "authors": [{"_id": "6ae1d18da5eb0647c290774c", "user": {"_id": "661cb57f851baf948bca33a4", "avatarUrl": "/avatars/5077723bfe0b5600f0346cc995cc0dc1.svg", "isPro": false, "fullname": "Li shuhuai", "user": "lsh-algorithm", "type": "user", "name": "lsh-algorithm"}, "name": "Shuhuai Li", "status": "claimed_verified", "statusLastChangedAt": "2026-10-29T08:45:04.803Z", "hidden": false}, {"_id": "6ae1d18da5eb0647c290774d", "user": {"_id": "67a26a8b366becf5b30f2283", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/67a26a8b366becf5b30f2283/Ej1Mta_Lo_87ShE5ihmpH.png", "isPro": false, "fullname": "Shengdong Ye", "user": "ysd1123", "type": "user", "name": "ysd1123"}, "name": "Shengdong Ye", "status": "claimed_verified", "statusLastChangedAt": "2026-10-29T16:45:04.994Z", "hidden": false}, {"_id": "6ae1d18da5eb0647c290774e", "name": "Dongdong Ge", "hidden": false}, {"_id": "6ae1d18da5eb0647c290774f", "name": "Yinyu Ye", "hidden": false}, {"_id": "6ae1d18da5eb0647c2907750", "name": "Jianghao Lin", "hidden": false}], "publishedAt": "2026-10-27T00:00:00.000Z", "submittedOnDailyAt": "2026-10-29T00:00:00.000Z", "title": "TAO: Tool-Aware Joint Scheduling for LLM-Based Agentic Serving", "submittedOnDailyBy": {"_id": "661cb57f851baf948bca33a4", "avatarUrl": "/avatars/5077723bfe0b5600f0346cc995cc0dc1.svg", "isPro": false, "fullname": "Li shuhuai", "user": "lsh-algorithm", "type": "user", "name": "lsh-algorithm"}, "summary": "Agentic services alternate between model inference on clustered GPUs and external tools on distributed CPUs. In this scenario, existing systems (1) overlook tool-return readiness in service evaluation, wasting limited resources, and (2) use heuristic strategies to decide admission and placement on GPUs, resulting in suboptimal scheduling decisions. To bridge this gap, we present TAO, a tool-aware joint scheduling framework for LLM-based agentic serving. Its value interface combines near-term tool readiness, node-specific cache credit with time-aware decay, and token footprint; a dynamic program jointly selects and places waiting sessions under capacity constraints. Across the 12 reported model-workload-concurrency settings, TAO reduces latency by up to 26.8%, reduces mean time to first token (TTFT) by up to 36.3%, and increases decode throughput by up to 29.5% relative to the best evaluated state-of-the-art baseline for each metric.", "upvotes": 18, "discussionId": "6ae1d18ea5eb0647c2907751", "ai_summary": "TAO improves scheduling for LLM agent services by considering tool readiness and using dynamic programming to place sessions, reducing latency and increasing throughput.", "ai_keywords": ["LLM-based agentic serving", "tool-aware scheduling", "tool-return readiness", "node-specific cache credit", "time-aware decay", "token footprint", "dynamic programming", "admission and placement", "decode throughput", "time to first token (TTFT)"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "6a914351ceb09c999ea12f84", "name": "AIOR-Research", "fullname": "AIOR", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/63f33193520c146189241780/UyBZGY7cm0LlIbu8qm0H4.png"}, "summary_zh": "<ul>\n    <li>\u4ee3\u7406\u670d\u52a1\u5728\u96c6\u7fa4GPU\u548c\u5206\u5e03\u5f0fCPU\u4e4b\u95f4\u4ea4\u66ff\u4f7f\u7528\u6a21\u578b\u63a8\u7406\u548c\u5916\u90e8\u5de5\u5177\u3002</li>\n    <li>\u73b0\u6709\u7cfb\u7edf\u5ffd\u89c6\u5de5\u5177\u7684\u51c6\u5907\u60c5\u51b5\uff0c\u6d6a\u8d39\u8d44\u6e90\uff0c\u5e76\u4f7f\u7528\u542f\u53d1\u5f0f\u7b56\u7565\u8fdb\u884cGPU\u7684\u63a5\u7eb3\u548c\u653e\u7f6e\uff0c\u5bfc\u81f4\u8c03\u5ea6\u51b3\u7b56\u4e0d\u4f73\u3002</li>\n    <li>\u63d0\u51fa\u4e86TAO\uff0c\u4e00\u4e2a\u5de5\u5177\u611f\u77e5\u7684\u8054\u5408\u8c03\u5ea6\u6846\u67b6\uff0c\u65e8\u5728\u63d0\u9ad8\u57fa\u4e8e\u5927\u578b\u8bed\u8a00\u6a21\u578b\u7684\u4ee3\u7406\u670d\u52a1\u6548\u7387\u3002</li>\n    <li>TAO\u7ed3\u5408\u4e86\u5de5\u5177\u51c6\u5907\u60c5\u51b5\u3001\u8282\u70b9\u7279\u5b9a\u7f13\u5b58\u548c\u65f6\u95f4\u654f\u611f\u7684\u8870\u51cf\uff0c\u52a8\u6001\u9009\u62e9\u548c\u5b89\u6392\u4f1a\u8bdd\u3002</li>\n    <li>\u5728\u591a\u79cd\u8bbe\u7f6e\u4e2d\uff0cTAO\u7684\u5ef6\u8fdf\u51cf\u5c11\u6700\u9ad8\u53ef\u8fbe26.8%\uff0c\u9996\u6b21\u4ee4\u724c\u65f6\u95f4\u51cf\u5c11\u6700\u592736.3%\uff0c\u89e3\u7801\u541e\u5410\u91cf\u63d0\u5347\u6700\u592729.5%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Agentic services use both clustered GPUs and distributed CPUs for processing tasks.</li>\n    <li>Current systems waste resources by not considering tool readiness and make poor decisions on how to place tasks on GPUs.</li>\n    <li>TAO is a new scheduling framework that improves how tasks are managed in LLM-based services.</li>\n    <li>TAO takes into account tool readiness, cache availability, and time factors for better scheduling.</li>\n    <li>Using TAO, latency can be reduced by up to 26.8%, time to first token by up to 36.3%, and decode throughput by up to 29.5% compared to other leading methods.</li>\n</ul>"}, "publishedAt": "2026-10-26T20:00:00.000Z", "title": "TAO: Tool-Aware Joint Scheduling for LLM-Based Agentic Serving", "summary": "Agentic services alternate between model inference on clustered GPUs and external tools on distributed CPUs. In this scenario, existing systems (1) overlook tool-return readiness in service evaluation, wasting limited resources, and (2) use heuristic strategies to decide admission and placement on GPUs, resulting in suboptimal scheduling decisions. To bridge this gap, we present TAO, a tool-aware joint scheduling framework for LLM-based agentic serving. Its value interface combines near-term tool readiness, node-specific cache credit with time-aware decay, and token footprint; a dynamic program jointly selects and places waiting sessions under capacity constraints. Across the 12 reported model-workload-concurrency settings, TAO reduces latency by up to 26.8%, reduces mean time to first token (TTFT) by up to 36.3%, and increases decode throughput by up to 29.5% relative to the best evaluated state-of-the-art baseline for each metric.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.37230.png", "numComments": 4, "submittedBy": {"_id": "661cb57f851baf948bca33a4", "avatarUrl": "/avatars/5077723bfe0b5600f0346cc995cc0dc1.svg", "fullname": "Li shuhuai", "name": "lsh-algorithm", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "6a914351ceb09c999ea12f84", "name": "AIOR-Research", "fullname": "AIOR", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/63f33193520c146189241780/UyBZGY7cm0LlIbu8qm0H4.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.35724", "authors": [{"_id": "6ae1609aa5eb0647c290724c", "name": "Shuyun Wang", "hidden": false}, {"_id": "6ae1609aa5eb0647c290724d", "name": "Shangchen Zhou", "hidden": false}, {"_id": "6ae1609aa5eb0647c290724e", "name": "Peiqing Yang", "hidden": false}, {"_id": "6ae1609aa5eb0647c290724f", "name": "Yuekun Dai", "hidden": false}, {"_id": "6ae1609aa5eb0647c2907250", "name": "Xin Yu", "hidden": false}, {"_id": "6ae1609aa5eb0647c2907251", "name": "Chen Change Loy", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/69df73d051cf1a3591b7fdda/xv9bXigtaMkt94Y06ct25.mp4"], "publishedAt": "2026-10-26T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "MatAnyone-E: Sparse Memory Propagation for Efficient High-Resolution Video Matting", "submittedOnDailyBy": {"_id": "69df73d051cf1a3591b7fdda", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/69df73d051cf1a3591b7fdda/eHwHYMhPKJsm9Ug26RPS7.jpeg", "isPro": false, "fullname": "Shuyun Wang", "user": "Shuyun-Wang", "type": "user", "name": "Shuyun-Wang"}, "summary": "High-resolution video matting requires preserving fine details, such as hair strands and soft transparency, while maintaining consistency across frames. Memory-based methods achieve strong matting quality by matching current-frame features with information stored from earlier frames, but this process becomes increasingly costly as resolution grows. We present MatAnyone-E, an efficient extension of MatAnyone 2 that focuses computation where it is most needed. Our approach first performs low-resolution propagation to identify uncertain regions that require closer inspection and the memory candidates most relevant to them. It then performs high-resolution matching only for these regions using the selected memory, while reusing low-resolution matching results elsewhere. This strategy reduces both the number of locations requiring detailed matching and the amount of memory searched, while preserving the information needed to produce a complete matte. We further reduce the cost of generating high-resolution mattes with a lightweight decoder designed around measured runtime bottlenecks and trained to reproduce the original decoder's representations. Experiments show that MatAnyone-E maintains matting quality comparable to MatAnyone 2 while achieving an estimated 7.4x inference speedup and reducing peak GPU memory usage to 7.6% of the usage of MatAnyone 2 at 4K. With compilation-enabled inference on a single NVIDIA H200 GPU, it reaches 73.07 FPS at 1080p and 28.62 FPS at 4K.", "upvotes": 15, "discussionId": "6ae1609aa5eb0647c2907252", "projectPage": "https://shuyun-wang.github.io/projects/MatAnyone-E", "githubRepo": "https://github.com/Shuyun-Wang/MatAnyone-E", "githubRepoAddedBy": "user", "ai_summary": "MatAnyone-E accelerates high-resolution video matting by selectively applying high-resolution matching to uncertain regions and using a lightweight decoder, achieving large speedups with preserved quality.", "ai_keywords": ["video matting", "memory-based methods", "low-resolution propagation", "high-resolution matching", "memory candidates", "lightweight decoder", "inference speedup", "GPU memory"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 54, "organization": {"_id": "62d55f243bf5e059f7ca25ba", "name": "mmlab-ntu", "fullname": "MMLab@NTU", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1658151991971-62b5777f593a2c49da69dc02.png"}, "summary_zh": "<ul>\n    <li>\u9ad8\u5206\u8fa8\u7387\u89c6\u9891\u62a0\u56fe\u9700\u8981\u4fdd\u7559\u7ec6\u8282\uff0c\u5982\u5934\u53d1\u548c\u67d4\u8f6f\u900f\u660e\u5ea6\uff0c\u540c\u65f6\u4fdd\u6301\u5e27\u95f4\u4e00\u81f4\u6027\u3002</li>\n    <li>\u57fa\u4e8e\u5185\u5b58\u7684\u65b9\u6cd5\u901a\u8fc7\u5339\u914d\u5f53\u524d\u5e27\u7279\u5f81\u548c\u65e9\u671f\u5e27\u7684\u4fe1\u606f\u6765\u5b9e\u73b0\u9ad8\u8d28\u91cf\u62a0\u56fe\uff0c\u4f46\u968f\u7740\u5206\u8fa8\u7387\u589e\u52a0\uff0c\u8ba1\u7b97\u6210\u672c\u4e5f\u4f1a\u589e\u52a0\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86MatAnyone-E\uff0c\u8fd9\u662fMatAnyone 2\u7684\u9ad8\u6548\u6269\u5c55\uff0c\u91cd\u70b9\u5728\u9700\u8981\u7684\u5730\u65b9\u8fdb\u884c\u8ba1\u7b97\u3002</li>\n    <li>\u8be5\u65b9\u6cd5\u9996\u5148\u8fdb\u884c\u4f4e\u5206\u8fa8\u7387\u4f20\u64ad\uff0c\u4ee5\u8bc6\u522b\u9700\u8981\u4ed4\u7ec6\u68c0\u67e5\u7684\u4e0d\u786e\u5b9a\u533a\u57df\u548c\u76f8\u5173\u7684\u5185\u5b58\u5019\u9009\u9879\u3002</li>\n    <li>\u5b9e\u9a8c\u8868\u660e\uff0cMatAnyone-E\u5728\u62a0\u56fe\u8d28\u91cf\u4e0a\u4e0eMatAnyone 2\u76f8\u5f53\uff0c\u4f46\u63a8\u7406\u901f\u5ea6\u63d0\u9ad8\u4e86\u7ea67.4\u500d\uff0cGPU\u5185\u5b58\u4f7f\u7528\u964d\u4f4e\u52307.6%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>MatAnyone-E is a new video matting method that keeps fine details and consistency across frames.</li>\n    <li>It uses a two-step process: first, it checks low-resolution images to find areas needing more detail.</li>\n    <li>Only the uncertain areas get high-resolution matching, while other parts use low-resolution results, saving time and memory.</li>\n    <li>The method includes a lightweight decoder to speed up the process and reduce memory use.</li>\n    <li>MatAnyone-E is faster and uses less memory than its predecessor, MatAnyone 2, while maintaining similar quality.</li>\n</ul>"}, "publishedAt": "2026-10-25T20:00:00.000Z", "title": "MatAnyone-E: Sparse Memory Propagation for Efficient High-Resolution Video Matting", "summary": "High-resolution video matting requires preserving fine details, such as hair strands and soft transparency, while maintaining consistency across frames. Memory-based methods achieve strong matting quality by matching current-frame features with information stored from earlier frames, but this process becomes increasingly costly as resolution grows. We present MatAnyone-E, an efficient extension of MatAnyone 2 that focuses computation where it is most needed. Our approach first performs low-resolution propagation to identify uncertain regions that require closer inspection and the memory candidates most relevant to them. It then performs high-resolution matching only for these regions using the selected memory, while reusing low-resolution matching results elsewhere. This strategy reduces both the number of locations requiring detailed matching and the amount of memory searched, while preserving the information needed to produce a complete matte. We further reduce the cost of generating high-resolution mattes with a lightweight decoder designed around measured runtime bottlenecks and trained to reproduce the original decoder's representations. Experiments show that MatAnyone-E maintains matting quality comparable to MatAnyone 2 while achieving an estimated 7.4x inference speedup and reducing peak GPU memory usage to 7.6% of the usage of MatAnyone 2 at 4K. With compilation-enabled inference on a single NVIDIA H200 GPU, it reaches 73.07 FPS at 1080p and 28.62 FPS at 4K.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/69df73d051cf1a3591b7fdda/xv9bXigtaMkt94Y06ct25.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.35724.png", "numComments": 1, "submittedBy": {"_id": "69df73d051cf1a3591b7fdda", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/69df73d051cf1a3591b7fdda/eHwHYMhPKJsm9Ug26RPS7.jpeg", "fullname": "Shuyun Wang", "name": "Shuyun-Wang", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "62d55f243bf5e059f7ca25ba", "name": "mmlab-ntu", "fullname": "MMLab@NTU", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1658151991971-62b5777f593a2c49da69dc02.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.33966", "authors": [{"_id": "6ae00898a5efa215400a78f6", "name": "Qinsi Wang", "hidden": false}, {"_id": "6ae00898a5efa215400a78f7", "name": "Wei Wen", "hidden": false}, {"_id": "6ae00898a5efa215400a78f8", "name": "Chong Zhou", "hidden": false}, {"_id": "6ae00898a5efa215400a78f9", "name": "Saksham Suri", "hidden": false}, {"_id": "6ae00898a5efa215400a78fa", "name": "Zechun Liu", "hidden": false}, {"_id": "6ae00898a5efa215400a78fb", "name": "Lemeng Wu", "hidden": false}, {"_id": "6ae00898a5efa215400a78fc", "name": "Hai Helen Li", "hidden": false}, {"_id": "6ae00898a5efa215400a78fd", "name": "Yiran Chen", "hidden": false}, {"_id": "6ae00898a5efa215400a78fe", "name": "Raghuraman Krishnamoorthi", "hidden": false}, {"_id": "6ae00898a5efa215400a78ff", "name": "Qi Qian", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66128e8b7e0e7a64652dbbdf/dcvO-JtnH4jLxgL-jiptM.mp4"], "publishedAt": "2026-10-25T00:00:00.000Z", "submittedOnDailyAt": "2026-10-27T00:00:00.000Z", "title": "InteractiveWorld: A Verifiable Human-Centric Environment for Building Better Interactive MLLM Assistants", "submittedOnDailyBy": {"_id": "66128e8b7e0e7a64652dbbdf", "avatarUrl": "/avatars/b90f06e74c52286fd421c4d9bbbc2c9f.svg", "isPro": false, "fullname": "Wang", "user": "Qinsi1", "type": "user", "name": "Qinsi1"}, "summary": "People have long dreamed of an assistant that is always there to guide them and remind what they forget, from new dishes to lost keys. Powered by multimodal large language models (MLLMs), egocentric AI assistants on wearable devices are bringing this dream within reach: they see what the user sees and give instructions for user's physical work when necessary. However, testing such assistance is challenging and usually requires real people. The expensive and rare real interaction data leaves a key question unanswered: Can today's MLLMs truly help people in physical world? To answer this question, we propose InteractiveWorld, the first verifiable environment for closed-loop interaction between human and AI assistant. Unlike existing robot-centric simulators, InteractiveWorld lets the assistant guide a human agent who observes the scene, understands instructions, and acts independently. It thus realistically simulates how AI assistant collaborates with human: the assistant instructs, the human acts, and the environment executes actions and updates what they see next. Building on it, we introduce InteractiveBench, the first dynamic benchmark for egocentric AI assistants, with 120 multi-turn tasks across six categories. In each task, the assistant guides the human in real time, and every instruction shapes the outcome, which is scored by verifiable, state-based rewards. Experiments with 12 frontier MLLMs show they are still far from reliable assistants. Even the strongest model, Claude Fable 5.1, achieves at most 20% and 25% on long-horizon Guidance and Planning tasks, respectively. Overall, our work offers a verifiable platform and a rigorous evaluation set, laying a solid foundation for research on interactive MLLM assistants that truly help people in the physical world.", "upvotes": 15, "discussionId": "6ae00898a5efa215400a7900", "projectPage": "https://meta-interactiveworld.github.io/", "githubRepo": "https://github.com/facebookresearch/InteractiveWorld", "githubRepoAddedBy": "user", "ai_summary": "InteractiveWorld provides a verifiable simulation environment and benchmark to evaluate whether multimodal language models can reliably guide humans through physical tasks.", "ai_keywords": ["multimodal large language models", "egocentric AI assistants", "InteractiveWorld", "closed-loop interaction", "InteractiveBench", "state-based rewards", "frontier MLLMs"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 6, "organization": {"_id": "6a78cbce04f58391d2d7c93b", "name": "meta", "fullname": "Meta", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Yq_gbM7i78tR3nfEvcwSA.png"}, "summary_zh": "<ul>\n    <li>\u4eba\u4eec\u4e00\u76f4\u68a6\u60f3\u62e5\u6709\u4e00\u4e2a\u968f\u65f6\u80fd\u63d0\u4f9b\u6307\u5bfc\u548c\u63d0\u9192\u7684\u52a9\u624b\uff0c\u6bd4\u5982\u5e2e\u52a9\u8bb0\u4f4f\u65b0\u83dc\u8c31\u6216\u627e\u4e22\u5931\u7684\u94a5\u5319\u3002</li>\n    <li>\u57fa\u4e8e\u591a\u6a21\u6001\u5927\u8bed\u8a00\u6a21\u578b\u7684\u53ef\u7a7f\u6234\u8bbe\u5907\u52a9\u624b\u6b63\u5728\u4f7f\u8fd9\u4e00\u68a6\u60f3\u53d8\u4e3a\u73b0\u5b9e\uff0c\u5b83\u4eec\u80fd\u591f\u770b\u5230\u7528\u6237\u6240\u89c1\u5e76\u5728\u9700\u8981\u65f6\u63d0\u4f9b\u6307\u5bfc\u3002</li>\n    <li>\u6d4b\u8bd5\u8fd9\u79cd\u52a9\u624b\u7684\u6709\u6548\u6027\u5f88\u6709\u6311\u6218\u6027\uff0c\u901a\u5e38\u9700\u8981\u771f\u5b9e\u7684\u4eba\u8fdb\u884c\u4e92\u52a8\uff0c\u800c\u771f\u5b9e\u7684\u4e92\u52a8\u6570\u636e\u65e2\u6602\u8d35\u53c8\u7a00\u5c11\u3002</li>\n    <li>\u4e3a\u4e86\u89e3\u51b3\u8fd9\u4e2a\u95ee\u9898\uff0c\u6211\u4eec\u63d0\u51fa\u4e86InteractiveWorld\uff0c\u8fd9\u662f\u4e00\u4e2a\u53ef\u9a8c\u8bc1\u7684\u73af\u5883\uff0c\u80fd\u591f\u6a21\u62df\u4eba\u7c7b\u4e0eAI\u52a9\u624b\u4e4b\u95f4\u7684\u95ed\u73af\u4e92\u52a8\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0c\u76ee\u524d\u7684\u591a\u6a21\u6001\u5927\u8bed\u8a00\u6a21\u578b\u4ecd\u7136\u65e0\u6cd5\u6210\u4e3a\u53ef\u9760\u7684\u52a9\u624b\uff0c\u6700\u5f3a\u7684\u6a21\u578b\u5728\u67d0\u4e9b\u4efb\u52a1\u4e0a\u7684\u6210\u529f\u7387\u4ec5\u4e3a20%\u523025%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Egocentric AI assistants on wearable devices can help with everyday tasks by seeing what users see and providing instructions.</li>\n    <li>Testing these assistants is difficult due to the need for real interaction data, which is expensive and rare.</li>\n    <li>InteractiveWorld is a new environment that allows testing of AI assistants by simulating interactions with human users.</li>\n    <li>InteractiveBench introduces a benchmark with 120 tasks to evaluate how well AI assistants can guide humans in real time.</li>\n    <li>Current advanced AI models still struggle with providing reliable assistance, achieving only 20-25% success in complex tasks.</li>\n</ul>"}, "publishedAt": "2026-10-24T20:00:00.000Z", "title": "InteractiveWorld: A Verifiable Human-Centric Environment for Building Better Interactive MLLM Assistants", "summary": "People have long dreamed of an assistant that is always there to guide them and remind what they forget, from new dishes to lost keys. Powered by multimodal large language models (MLLMs), egocentric AI assistants on wearable devices are bringing this dream within reach: they see what the user sees and give instructions for user's physical work when necessary. However, testing such assistance is challenging and usually requires real people. The expensive and rare real interaction data leaves a key question unanswered: Can today's MLLMs truly help people in physical world? To answer this question, we propose InteractiveWorld, the first verifiable environment for closed-loop interaction between human and AI assistant. Unlike existing robot-centric simulators, InteractiveWorld lets the assistant guide a human agent who observes the scene, understands instructions, and acts independently. It thus realistically simulates how AI assistant collaborates with human: the assistant instructs, the human acts, and the environment executes actions and updates what they see next. Building on it, we introduce InteractiveBench, the first dynamic benchmark for egocentric AI assistants, with 120 multi-turn tasks across six categories. In each task, the assistant guides the human in real time, and every instruction shapes the outcome, which is scored by verifiable, state-based rewards. Experiments with 12 frontier MLLMs show they are still far from reliable assistants. Even the strongest model, Claude Fable 5.1, achieves at most 20% and 25% on long-horizon Guidance and Planning tasks, respectively. Overall, our work offers a verifiable platform and a rigorous evaluation set, laying a solid foundation for research on interactive MLLM assistants that truly help people in the physical world.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66128e8b7e0e7a64652dbbdf/dcvO-JtnH4jLxgL-jiptM.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.33966.png", "numComments": 1, "submittedBy": {"_id": "66128e8b7e0e7a64652dbbdf", "avatarUrl": "/avatars/b90f06e74c52286fd421c4d9bbbc2c9f.svg", "fullname": "Wang", "name": "Qinsi1", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 5, "isUserFollowing": false}, "organization": {"_id": "6a78cbce04f58391d2d7c93b", "name": "meta", "fullname": "Meta", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5dd96eb166059660ed1ee413/Yq_gbM7i78tR3nfEvcwSA.png"}, "isAuthorParticipating": false}],
    "month": [{"paper": {"id": "2610.32749", "authors": [{"_id": "6ae29be0d670fc6ea896c79e", "name": "Wendi Sang", "hidden": false}, {"_id": "6ae29be0d670fc6ea896c79f", "name": "Kai Li", "hidden": false}, {"_id": "6ae29be0d670fc6ea896c7a0", "name": "Yifan Li", "hidden": false}, {"_id": "6ae29be0d670fc6ea896c7a1", "name": "Jianqiang Huang", "hidden": false}, {"_id": "6ae29be0d670fc6ea896c7a2", "name": "Xiaolin Hu", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6387676c23da90491eb9fb16/fyfAlyMRka4HqWEFfbAoN.mp4"], "publishedAt": "2026-10-23T00:00:00.000Z", "submittedOnDailyAt": "2026-10-29T00:00:00.000Z", "title": "Efficient Streaming Audio-Visual Target Speaker Extraction for Real-World Acoustic Scenes", "submittedOnDailyBy": {"_id": "6387676c23da90491eb9fb16", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/1669818175965-noauth.jpeg", "isPro": true, "fullname": "Kai Li", "user": "JusperLee", "type": "user", "name": "JusperLee"}, "summary": "Streaming audio-visual target speaker extraction (AVTSE) is essential for latency-sensitive applications. However, current causal systems face two coupled gaps. First, standard benchmarks fix the number of speakers at two and ignore the near-/far-field interference, reverberation, and sudden noise of real scenes. Second, high-performance causal architectures are too heavy for edge deployment. Lightweight alternatives try to reclaim capacity by repeatedly invoking a small separator, which offsets the savings. To address the first gap, we release RealSSA, a realistic AVTSE benchmark consisting of RealSSA-Sim and RealSSA-Real. RealSSA-Sim provides controllable simulated scenes with 1--5 dynamic near-field interfering speakers; scenes with far-field interference additionally include 10--15 far-field interfering speakers. RealSSA-Real provides a held-out real-recorded evaluation set. To address the second gap, we propose Falcon, a causal AVTSE method. Its Separator performs multi-scale time-frequency separation in a single encoder--decoder pass. We train Falcon with an encoder-space speaker contrastive loss. This loss suppresses near-field leakage at zero inference cost and transfers across backbones. Falcon achieves state-of-the-art extraction quality on RealSSA-Sim, LRS2-2Mix, LRS3-2Mix, and VoxCeleb2-2Mix. Compared with the causal AV-TFGridNet baseline, it cuts parameters by 91.9%, computation by 20.2 times, and GPU inference latency by 11.1 times. Code and demo are available at https://cslikai.cn/Falcon/.", "upvotes": 152, "discussionId": "6ae29be1d670fc6ea896c7a3", "projectPage": "https://cslikai.cn/Falcon/", "githubRepo": "https://github.com/JusperLee/Falcon", "githubRepoAddedBy": "user", "ai_summary": "Falcon is a lightweight causal audio-visual target speaker extraction method that achieves high quality with drastically reduced parameters and latency, supported by the realistic RealSSA benchmark.", "ai_keywords": ["audio-visual target speaker extraction", "causal AVTSE", "RealSSA", "Falcon", "multi-scale time-frequency separation", "encoder-space speaker contrastive loss", "near-field leakage suppression"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 20, "organization": {"_id": "640d3084536d9fe0f005cac3", "name": "thu-ml", "fullname": "Tsinghua Machine Learning Group", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1678587085174-633131798ef21f47308ce49b.jpeg"}, "summary_zh": "<ul>\n    <li>\u97f3\u9891-\u89c6\u89c9\u76ee\u6807\u8bf4\u8bdd\u4eba\u63d0\u53d6\uff08AVTSE\uff09\u5bf9\u5b9e\u65f6\u5e94\u7528\u975e\u5e38\u91cd\u8981\uff0c\u4f46\u73b0\u6709\u7cfb\u7edf\u5b58\u5728\u4e24\u4e2a\u4e3b\u8981\u95ee\u9898\u3002</li>\n    <li>\u5f53\u524d\u57fa\u51c6\u6d4b\u8bd5\u53ea\u8003\u8651\u4e24\u4e2a\u8bf4\u8bdd\u4eba\uff0c\u5ffd\u89c6\u4e86\u771f\u5b9e\u573a\u666f\u4e2d\u7684\u5e72\u6270\u548c\u566a\u97f3\u3002</li>\n    <li>\u6211\u4eec\u53d1\u5e03\u4e86RealSSA\u57fa\u51c6\uff0c\u5305\u542b\u53ef\u63a7\u7684\u6a21\u62df\u573a\u666f\u548c\u771f\u5b9e\u5f55\u97f3\u6570\u636e\u96c6\uff0c\u4ee5\u89e3\u51b3\u8fd9\u4e9b\u95ee\u9898\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86Falcon\u65b9\u6cd5\uff0c\u80fd\u591f\u5728\u4e00\u6b21\u7f16\u7801-\u89e3\u7801\u4e2d\u8fdb\u884c\u591a\u5c3a\u5ea6\u65f6\u9891\u5206\u79bb\uff0c\u63d0\u9ad8\u63d0\u53d6\u8d28\u91cf\u5e76\u51cf\u5c11\u8ba1\u7b97\u8d44\u6e90\u3002</li>\n    <li>\u4e0e\u4f20\u7edf\u65b9\u6cd5\u76f8\u6bd4\uff0cFalcon\u5927\u5e45\u964d\u4f4e\u4e86\u53c2\u6570\u6570\u91cf\u548c\u8ba1\u7b97\u9700\u6c42\uff0c\u5ef6\u8fdf\u4e5f\u663e\u8457\u51cf\u5c11\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>The study focuses on improving audio-visual target speaker extraction (AVTSE) for real-time applications.</li>\n    <li>It introduces RealSSA, a new benchmark that simulates realistic audio scenes with varying numbers of speakers and interference.</li>\n    <li>To address performance issues in current systems, the authors present Falcon, a lightweight AVTSE method that efficiently separates speakers.</li>\n    <li>Falcon significantly reduces the size and computation needed compared to previous models, while maintaining high extraction quality.</li>\n    <li>Demo and code for Falcon are available online for further exploration.</li>\n</ul>"}, "publishedAt": "2026-10-22T20:00:00.000Z", "title": "Efficient Streaming Audio-Visual Target Speaker Extraction for Real-World Acoustic Scenes", "summary": "Streaming audio-visual target speaker extraction (AVTSE) is essential for latency-sensitive applications. However, current causal systems face two coupled gaps. First, standard benchmarks fix the number of speakers at two and ignore the near-/far-field interference, reverberation, and sudden noise of real scenes. Second, high-performance causal architectures are too heavy for edge deployment. Lightweight alternatives try to reclaim capacity by repeatedly invoking a small separator, which offsets the savings. To address the first gap, we release RealSSA, a realistic AVTSE benchmark consisting of RealSSA-Sim and RealSSA-Real. RealSSA-Sim provides controllable simulated scenes with 1--5 dynamic near-field interfering speakers; scenes with far-field interference additionally include 10--15 far-field interfering speakers. RealSSA-Real provides a held-out real-recorded evaluation set. To address the second gap, we propose Falcon, a causal AVTSE method. Its Separator performs multi-scale time-frequency separation in a single encoder--decoder pass. We train Falcon with an encoder-space speaker contrastive loss. This loss suppresses near-field leakage at zero inference cost and transfers across backbones. Falcon achieves state-of-the-art extraction quality on RealSSA-Sim, LRS2-2Mix, LRS3-2Mix, and VoxCeleb2-2Mix. Compared with the causal AV-TFGridNet baseline, it cuts parameters by 91.9%, computation by 20.2 times, and GPU inference latency by 11.1 times. Code and demo are available at https://cslikai.cn/Falcon/.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/6387676c23da90491eb9fb16/fyfAlyMRka4HqWEFfbAoN.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.32749.png", "numComments": 2, "submittedBy": {"_id": "6387676c23da90491eb9fb16", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/1669818175965-noauth.jpeg", "fullname": "Kai Li", "name": "JusperLee", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 63, "isUserFollowing": false}, "organization": {"_id": "640d3084536d9fe0f005cac3", "name": "thu-ml", "fullname": "Tsinghua Machine Learning Group", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/1678587085174-633131798ef21f47308ce49b.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.34283", "authors": [{"_id": "6ae15489a5eb0647c290713b", "name": "Yihao Hu", "hidden": false}, {"_id": "6ae15489a5eb0647c290713c", "name": "Yitong Lin", "hidden": false}, {"_id": "6ae15489a5eb0647c290713d", "name": "Pan Wang", "hidden": false}, {"_id": "6ae15489a5eb0647c290713e", "name": "Zhihao Wen", "hidden": false}, {"_id": "6ae15489a5eb0647c290713f", "name": "Hang Wang", "hidden": false}, {"_id": "6ae15489a5eb0647c2907140", "name": "Yiwen Zhao", "hidden": false}, {"_id": "6ae15489a5eb0647c2907141", "name": "Deyuan Liu", "hidden": false}, {"_id": "6ae15489a5eb0647c2907142", "name": "Yutong Li", "hidden": false}, {"_id": "6ae15489a5eb0647c2907143", "name": "Mingda Wan", "hidden": false}, {"_id": "6ae15489a5eb0647c2907144", "name": "Yuchen Mao", "hidden": false}, {"_id": "6ae15489a5eb0647c2907145", "name": "Tao Lin", "hidden": false}], "publishedAt": "2026-10-25T00:00:00.000Z", "submittedOnDailyAt": "2026-10-28T00:00:00.000Z", "title": "ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence", "submittedOnDailyBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "isPro": false, "fullname": "Yihao Hu", "user": "HU22333", "type": "user", "name": "HU22333"}, "summary": "Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, and balancing supervision across families. Under the same observation access, a single ChronoReplay checkpoint improves OVO-S-Bench, OST-Bench, and UCS-Bench together, including a 13.41-point gain on OST-Bench, and achieves the highest three-benchmark mean among the supervision settings compared here. Same-data controls further separate the ingredients of this transfer: answer serialization redistributes gains across OST and UCS, family-balanced learning improves over ordinary joint SFT and natural turn weighting, and chronological replay exceeds a shifted-order control by about 2.41 OST points across two paired seeds. Adaptive frame selection then changes evidence access while keeping the trained model fixed, providing an additional inference-time gain at lower visual cost. Streaming spatial performance depends on what distinctions supervision preserves, how heterogeneous histories are organized during learning, and what causal evidence inference makes available at test time.", "upvotes": 77, "discussionId": "6ae15489a5eb0647c2907146", "projectPage": "https://yihaohu0118.github.io/ChronoReplay/", "ai_summary": "ChronoReplay mitigates interface lock-in in spatial vision-language models by replaying heterogeneous spatial supervision chronologically, improving cross-task transfer and enabling efficient inference-time evidence selection.", "ai_keywords": ["spatial VLM", "interface lock-in", "ChronoReplay", "joint SFT", "adaptive frame selection", "OVO-S-Bench", "OST-Bench", "UCS-Bench"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "6650967d53061f0d1b5a7962", "name": "LINs-lab", "fullname": "LINs lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65296b8a6cdea40585bd81e2/M80w6f0H8dfx3Sa1nVmfq.png"}, "summary_zh": "<ul>\n    <li>\u8bad\u7ec3\u7a7a\u95f4\u89c6\u89c9\u8bed\u8a00\u6a21\u578b\uff08VLM\uff09\u65f6\uff0c\u4e0d\u9700\u8981\u4fdd\u7559\u51b3\u5b9a\u7269\u4f53\u4f4d\u7f6e\u7684\u5ea6\u91cf\u8ddd\u79bb\u3002</li>\n    <li>\u5728\u8bad\u7ec3\u540e\u5f3a\u8c03\u67d0\u4e2a\u8f93\u51fa\u63a5\u53e3\u53ef\u80fd\u5bfc\u81f4\u5176\u4ed6\u63a5\u53e3\u7684\u8f6c\u79fb\u6548\u679c\u8f83\u5f31\uff0c\u751a\u81f3\u6076\u5316\uff0c\u8fd9\u79cd\u73b0\u8c61\u79f0\u4e3a\u201c\u4e13\u95e8\u5316\u63a5\u53e3\u9501\u5b9a\u201d\u3002</li>\n    <li>ChronoReplay\u901a\u8fc7\u56de\u653e\u4e0d\u540c\u7684\u7a7a\u95f4\u76d1\u7763\uff0c\u4fdd\u6301\u539f\u59cb\u76ee\u6807\uff0c\u5e76\u5728\u4e0d\u540c\u7c7b\u522b\u95f4\u5e73\u8861\u76d1\u7763\uff0c\u6765\u89e3\u51b3\u63a5\u53e3\u9501\u5b9a\u95ee\u9898\u3002</li>\n    <li>\u4f7f\u7528ChronoReplay\u540e\uff0c\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\uff08\u5982OST-Bench\uff09\u8868\u73b0\u663e\u8457\u63d0\u5347\uff0c\u5176\u4e2dOST-Bench\u63d0\u9ad8\u4e8613.41\u5206\u3002</li>\n    <li>\u9002\u5e94\u6027\u5e27\u9009\u62e9\u5728\u4fdd\u6301\u6a21\u578b\u4e0d\u53d8\u7684\u60c5\u51b5\u4e0b\u6539\u53d8\u8bc1\u636e\u83b7\u53d6\uff0c\u4ece\u800c\u5728\u63a8\u7406\u65f6\u63d0\u4f9b\u989d\u5916\u6536\u76ca\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Training a spatial visual language model (VLM) to determine object positions can lead to specialization in certain areas, limiting its overall performance.</li>\n    <li>ChronoReplay is a method that improves this by using diverse spatial guidance in a structured way, which helps the model learn better across different tasks.</li>\n    <li>This method has shown significant improvements in performance on multiple benchmarks, including a notable 13.41-point increase on one specific benchmark.</li>\n    <li>Different techniques within ChronoReplay, like answer serialization and family-balanced learning, help distribute improvements effectively across tasks.</li>\n    <li>Adaptive frame selection further enhances model performance by optimizing evidence access during inference, leading to better results with less visual effort.</li>\n</ul>"}, "publishedAt": "2026-10-24T20:00:00.000Z", "title": "ChronoReplay: One Answer Interface Is Not Enough for Streaming Spatial Intelligence", "summary": "Training a spatial VLM to answer which side an object lies on does not require it to preserve the metric displacement that determines that answer, while supervision for a distance estimate may leave categorical relations largely unconstrained. When post-training emphasizes one readout, improvements can therefore concentrate on that interface while transfer to others remains weak or even degrades; we call this observed specialization interface lock-in. ChronoReplay addresses it by replaying heterogeneous spatial supervision as chronologically ordered episodes, retaining source-native targets, and balancing supervision across families. Under the same observation access, a single ChronoReplay checkpoint improves OVO-S-Bench, OST-Bench, and UCS-Bench together, including a 13.41-point gain on OST-Bench, and achieves the highest three-benchmark mean among the supervision settings compared here. Same-data controls further separate the ingredients of this transfer: answer serialization redistributes gains across OST and UCS, family-balanced learning improves over ordinary joint SFT and natural turn weighting, and chronological replay exceeds a shifted-order control by about 2.41 OST points across two paired seeds. Adaptive frame selection then changes evidence access while keeping the trained model fixed, providing an additional inference-time gain at lower visual cost. Streaming spatial performance depends on what distinctions supervision preserves, how heterogeneous histories are organized during learning, and what causal evidence inference makes available at test time.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.34283.png", "numComments": 1, "submittedBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "fullname": "Yihao Hu", "name": "HU22333", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6650967d53061f0d1b5a7962", "name": "LINs-lab", "fullname": "LINs lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65296b8a6cdea40585bd81e2/M80w6f0H8dfx3Sa1nVmfq.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.06100", "authors": [{"_id": "6ac4b70a9eb4ee6bd77a9766", "user": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "name": "Quanyu Long", "status": "claimed_verified", "statusLastChangedAt": "2026-10-06T09:20:03.874Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9767", "user": {"_id": "64969bccf590e76c93938582", "avatarUrl": "/avatars/363598cba9e9496852e60144694b2f1c.svg", "isPro": false, "fullname": "shawncchen", "user": "chrisCCC", "type": "user", "name": "chrisCCC"}, "name": "Xiao Chen", "status": "claimed_verified", "statusLastChangedAt": "2026-10-07T08:07:49.844Z", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9768", "name": "Jianda Chen", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a9769", "name": "Haozhen Zhang", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976a", "name": "Qisheng Hu", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976b", "name": "Jianzhu Bao", "hidden": false}, {"_id": "6ac4b70a9eb4ee6bd77a976c", "name": "Wenya Wang", "hidden": false}], "publishedAt": "2026-10-05T00:00:00.000Z", "submittedOnDailyAt": "2026-10-09T00:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "submittedOnDailyBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "isPro": true, "fullname": "Long", "user": "Quanyu001", "type": "user", "name": "Quanyu001"}, "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "upvotes": 64, "discussionId": "6ac4b70a9eb4ee6bd77a976d", "projectPage": "https://quanyulong.net/trace2env/", "githubRepo": "https://github.com/ruyue0001/trace2env", "githubRepoAddedBy": "user", "githubStars": 17, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "summary_zh": "<ul>\n    <li>\u73b0\u5b9e\u73af\u5883\u7684\u590d\u5236\u54c1\u5bf9\u8bad\u7ec3\u548c\u8bc4\u4f30\u5927\u578b\u8bed\u8a00\u6a21\u578b\u4ee3\u7406\u8d8a\u6765\u8d8a\u91cd\u8981\uff0c\u4f46\u539f\u7cfb\u7edf\u53ef\u80fd\u96be\u4ee5\u83b7\u53d6\u6216\u91cd\u5efa\u3002</li>\n    <li>\u6211\u4eec\u63a2\u7d22\u4e86\u4e00\u79cd\u65b0\u7684\u65b9\u6cd5\uff0c\u4f7f\u7528\u4e16\u754c\u6a21\u578b\u4ee3\u7406\u4f5c\u4e3a\u4efb\u52a1\u4ee3\u7406\u7684\u73af\u5883\uff0c\u652f\u6301\u771f\u5b9e\u548c\u6301\u7eed\u7684\u6a21\u62df\u3002</li>\n    <li>Trace2Env\u662f\u4e00\u4e2a\u65e0\u9700\u5b66\u4e60\u7684\u6846\u67b6\uff0c\u5229\u7528\u5386\u53f2\u4ea4\u4e92\u8bb0\u5f55\u91cd\u5efa\u73af\u5883\uff0c\u800c\u4e0d\u662f\u91cd\u5efa\u539f\u59cb\u7cfb\u7edf\u3002</li>\n    <li>Trace2Env\u5728\u4e5d\u4e2a\u73af\u5883\u4e2d\u63d0\u9ad8\u4e86\u4e0b\u4e00\u89c2\u5bdf\u7684\u51c6\u786e\u6027\u548c\u957f\u671f\u4ea4\u4e92\u7684\u4e00\u81f4\u6027\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u8868\u660e\uff0c\u4f7f\u7528Trace2Env\u751f\u6210\u7684\u4efb\u52a1\u4ee3\u7406\u52a8\u4f5c\u5728\u771f\u5b9e\u73af\u5883\u4e2d\u91cd\u653e\u65f6\u66f4\u6709\u6548\uff0c\u8868\u660e\u5176\u6a21\u62df\u52a8\u6001\u66f4\u597d\u5730\u4fdd\u7559\u4e86\u65e9\u671f\u52a8\u4f5c\u7684\u540e\u679c\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Realistic environment replicas are important for training language model agents, but original systems can be hard to access or recreate.</li>\n    <li>The study introduces agentic language world modeling, which uses a world model agent instead of rebuilding the original environment.</li>\n    <li>Trace2Env is a new framework that builds a reusable environment model from historical interaction data, without needing to learn from scratch.</li>\n    <li>In tests, Trace2Env showed better accuracy in predicting observations and maintaining consistency over longer interactions compared to traditional methods.</li>\n    <li>The approach suggests a new way to create realistic environment models without needing the original executable systems.</li>\n</ul>"}, "publishedAt": "2026-10-04T20:00:00.000Z", "title": "From Traces to Agentic Worlds: Agentic Language World Models for Interactive Environment Simulation", "summary": "Realistic environment replicas are increasingly valuable for training and evaluating LLM agents, yet the original systems may be inaccessible or impractical to reproduce. We explore agentic language world modeling: rather than rebuilding an executable environment, a world model agent serves as the environment for a task agent and supports faithful and stateful simulation. We instantiate this paradigm with Trace2Env, a learning-free framework for settings where the original system is unavailable but historical interaction traces remain accessible. Trace2Env reconstructs these traces into a reusable environment worldbook containing environment schemas, grounded evidence, and induced behavioral knowledge. At runtime, the world model agent actively consults the worldbook together with persistent episodic state to infer each action's observation and lasting state effects. Across nine environments, Trace2Env improves both next-observation fidelity and long-horizon interaction consistency over conventional prompt-based LWMs. In multi-turn interaction, task agent actions generated against Trace2Env remain valid more often when replayed in the real environment, indicating that its simulated dynamics better preserve the consequences of earlier actions across successive turns. These results establish agentic language world modeling as an alternative direction for building realistic environment replicas without reconstructing the original executable system.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.06100.png", "numComments": 1, "submittedBy": {"_id": "65c1d1bda2239cf479ecf573", "avatarUrl": "/avatars/70483a134b3236d690fc4d9409f1ecad.svg", "fullname": "Long", "name": "Quanyu001", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "6371470aafbe42caa5a76208", "name": "nanyang-technological-university-singapore", "fullname": "Nanyang Technological University Singapore", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/637146c5afbe42caa5a75e1b/sZyHSA1AQaAS4nrGan682.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.18784", "authors": [{"_id": "6ad00783aab7978cb679dcde", "user": {"_id": "680462011c5a7a2228526d9c", "avatarUrl": "/avatars/2004afde5ba4050c4b53ef1786d02012.svg", "isPro": false, "fullname": "YUCHEN LU", "user": "callmeethan", "type": "user", "name": "callmeethan"}, "name": "Yuchen Lu", "status": "claimed_verified", "statusLastChangedAt": "2026-10-15T08:45:06.727Z", "hidden": false}, {"_id": "6ad00783aab7978cb679dcdf", "name": "Julian McAuley", "hidden": false}, {"_id": "6ad00783aab7978cb679dce0", "user": {"_id": "66f47c8d29b10ae4c97292c4", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/66f47c8d29b10ae4c97292c4/W3o7EsgKT4CgNyBMH_vxh.jpeg", "isPro": false, "fullname": "Lei Zhang", "user": "leiiizhang", "type": "user", "name": "leiiizhang"}, "name": "Lei Zhang", "status": "claimed_verified", "statusLastChangedAt": "2026-10-16T16:45:05.346Z", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/680462011c5a7a2228526d9c/xDGQ9e03X6BKBrr2NO0hW.mp4"], "publishedAt": "2026-10-13T17:35:27.000Z", "submittedOnDailyAt": "2026-10-19T00:00:00.000Z", "title": "Pack Light, CarryOn: Building Object-Oriented Context for Long-Horizon Agents", "submittedOnDailyBy": {"_id": "680462011c5a7a2228526d9c", "avatarUrl": "/avatars/2004afde5ba4050c4b53ef1786d02012.svg", "isPro": false, "fullname": "YUCHEN LU", "user": "callmeethan", "type": "user", "name": "callmeethan"}, "summary": "Long-horizon agents accumulate progress in persistent task state, yet repeatedly process interaction histories describing how that progress was achieved. This raises a natural question: can long-horizon context instead be organized around reusable progress rather than the history that produced it? In this paper, we introduce CarryOn, an object-oriented context runtime that organizes continuation around reusable task objects. Rather than treating compressed histories or reconstructed accounts of progress as the primary basis for continuation, CarryOn builds a context view from continuation carriers, complementary execution context, and a live tail of recent interactions. A core challenge is keeping this reusable basis valid after its surrounding history is retired: how can CarryOn update the basis without reconstructing the full representation at every fold? CarryOn maintains carrier records across folds, revising affected records against bound evidence and applicable environment checks while carrying forward unaffected records and jointly updating execution context. Experiments on OSWorld 2.0 and BrowseComp-Plus show improved gains of 5.8% and 7.0% while reducing total token usage by 51.9% and 22.9%, respectively. Project page: https://ethannju.github.io/carryon", "upvotes": 63, "discussionId": "6ad00783aab7978cb679dce1", "projectPage": "https://ethannju.github.io/carryon/", "ai_summary": "CarryOn organizes long-horizon agent context around reusable task objects rather than interaction histories, improving efficiency and performance on complex benchmarks.", "ai_keywords": ["object-oriented context runtime", "continuation carriers", "carrier records", "execution context", "OSWorld 2.0", "BrowseComp-Plus"], "ai_summary_model": "thinkingmachines/Inkling-Small", "organization": {"_id": "65af44a1637e10fba942ed0c", "name": "McAuley-Lab", "fullname": "McAuley-Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64daab70c38427829daf5958/OWlh6vciWnY_MeyM099wZ.png"}, "summary_zh": "<ul>\n    <li>\u672c\u6587\u4ecb\u7ecd\u4e86CarryOn\uff0c\u4e00\u4e2a\u9762\u5411\u5bf9\u8c61\u7684\u4e0a\u4e0b\u6587\u8fd0\u884c\u65f6\uff0c\u65e8\u5728\u56f4\u7ed5\u53ef\u91cd\u7528\u7684\u4efb\u52a1\u5bf9\u8c61\u7ec4\u7ec7\u957f\u65f6\u95f4\u7684\u4e0a\u4e0b\u6587\u3002</li>\n    <li>CarryOn\u4e0d\u540c\u4e8e\u4f20\u7edf\u65b9\u6cd5\uff0c\u5b83\u4e0d\u4f9d\u8d56\u4e8e\u538b\u7f29\u7684\u5386\u53f2\u8bb0\u5f55\uff0c\u800c\u662f\u4ece\u6301\u7eed\u8f7d\u4f53\u3001\u8865\u5145\u6267\u884c\u4e0a\u4e0b\u6587\u548c\u6700\u8fd1\u4ea4\u4e92\u4e2d\u6784\u5efa\u4e0a\u4e0b\u6587\u89c6\u56fe\u3002</li>\n    <li>\u4e00\u4e2a\u4e3b\u8981\u6311\u6218\u662f\u5982\u4f55\u5728\u5386\u53f2\u8bb0\u5f55\u88ab\u820d\u5f03\u540e\u66f4\u65b0\u53ef\u91cd\u7528\u7684\u57fa\u7840\uff0c\u800c\u4e0d\u9700\u8981\u6bcf\u6b21\u90fd\u91cd\u5efa\u5b8c\u6574\u8868\u793a\u3002</li>\n    <li>CarryOn\u901a\u8fc7\u8de8\u6298\u53e0\u7ef4\u62a4\u8f7d\u4f53\u8bb0\u5f55\uff0c\u66f4\u65b0\u53d7\u5f71\u54cd\u7684\u8bb0\u5f55\uff0c\u540c\u65f6\u643a\u5e26\u672a\u53d7\u5f71\u54cd\u7684\u8bb0\u5f55\u548c\u8054\u5408\u66f4\u65b0\u6267\u884c\u4e0a\u4e0b\u6587\u3002</li>\n    <li>\u5b9e\u9a8c\u7ed3\u679c\u663e\u793a\uff0c\u5728OSWorld 2.0\u548cBrowseComp-Plus\u4e0a\u7684\u6027\u80fd\u63d0\u5347\u5206\u522b\u4e3a5.8%\u548c7.0%\uff0c\u540c\u65f6\u603b\u4ee4\u724c\u4f7f\u7528\u91cf\u5206\u522b\u51cf\u5c11\u4e8651.9%\u548c22.9%\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>CarryOn is a new context runtime that focuses on reusable task objects instead of just the history of how tasks were completed.</li>\n    <li>It organizes progress by using continuation carriers and recent interactions rather than reconstructing full histories.</li>\n    <li>One challenge is updating reusable task information without needing to redo everything each time.</li>\n    <li>CarryOn successfully keeps track of changes and updates records while maintaining efficiency.</li>\n    <li>Tests showed improvements in performance and reduced resource usage in two experimental setups.</li>\n</ul>"}, "publishedAt": "2026-10-13T13:35:27.000Z", "title": "Pack Light, CarryOn: Building Object-Oriented Context for Long-Horizon Agents", "summary": "Long-horizon agents accumulate progress in persistent task state, yet repeatedly process interaction histories describing how that progress was achieved. This raises a natural question: can long-horizon context instead be organized around reusable progress rather than the history that produced it? In this paper, we introduce CarryOn, an object-oriented context runtime that organizes continuation around reusable task objects. Rather than treating compressed histories or reconstructed accounts of progress as the primary basis for continuation, CarryOn builds a context view from continuation carriers, complementary execution context, and a live tail of recent interactions. A core challenge is keeping this reusable basis valid after its surrounding history is retired: how can CarryOn update the basis without reconstructing the full representation at every fold? CarryOn maintains carrier records across folds, revising affected records against bound evidence and applicable environment checks while carrying forward unaffected records and jointly updating execution context. Experiments on OSWorld 2.0 and BrowseComp-Plus show improved gains of 5.8% and 7.0% while reducing total token usage by 51.9% and 22.9%, respectively. Project page: https://ethannju.github.io/carryon", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/680462011c5a7a2228526d9c/xDGQ9e03X6BKBrr2NO0hW.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.18784.png", "numComments": 1, "submittedBy": {"_id": "680462011c5a7a2228526d9c", "avatarUrl": "/avatars/2004afde5ba4050c4b53ef1786d02012.svg", "fullname": "YUCHEN LU", "name": "callmeethan", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 2, "isUserFollowing": false}, "organization": {"_id": "65af44a1637e10fba942ed0c", "name": "McAuley-Lab", "fullname": "McAuley-Lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64daab70c38427829daf5958/OWlh6vciWnY_MeyM099wZ.png"}, "isAuthorParticipating": true}, {"paper": {"id": "2610.10528", "authors": [{"_id": "6ac6fb044eb8005165aed391", "name": "Wei Huang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed392", "name": "Bohan Zhang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed393", "name": "Chenzhi Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed394", "name": "Isabella Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed395", "name": "Shuai Yang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed396", "name": "Weian Mao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed397", "name": "Luozhou Wang", "hidden": false}, {"_id": "6ac6fb044eb8005165aed398", "name": "Yicheng Xiao", "hidden": false}, {"_id": "6ac6fb044eb8005165aed399", "name": "Weifeng Lin", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39a", "name": "Qixin Hu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39b", "name": "Bryan Chu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39c", "name": "Sifei Liu", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39d", "name": "Linxi Fan", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39e", "name": "Xiaojuan Qi", "hidden": false}, {"_id": "6ac6fb044eb8005165aed39f", "name": "Song Han", "hidden": false}, {"_id": "6ac6fb044eb8005165aed3a0", "name": "Yukang Chen", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "submittedOnDailyBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "isPro": false, "fullname": "Wei Huang", "user": "AaronHuangWei", "type": "user", "name": "AaronHuangWei"}, "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "upvotes": 54, "discussionId": "6ac6fb044eb8005165aed3a1", "projectPage": "https://nvlabs.github.io/LongLive/Long-WAM/", "githubRepo": "https://github.com/NVlabs/LongLive", "githubRepoAddedBy": "user", "githubStars": 2662, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "summary_zh": "<ul>\n    <li>Long-WAM\u662f\u4e00\u4e2a\u6a21\u578b-\u7cfb\u7edf\u6846\u67b6\uff0c\u7528\u4e8e\u5728\u5b9e\u65f6\u63a7\u5236\u4e0b\u6269\u5c55\u56e0\u679c\u4e16\u754c-\u52a8\u4f5c\u6a21\u578b\u7684\u4e0a\u4e0b\u6587\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff0c\u8f83\u957f\u7684\u5386\u53f2\u4fe1\u606f\u5728\u7ecf\u8fc7\u81ea\u56de\u5f52\u9884\u8bad\u7ec3\u540e\u80fd\u663e\u8457\u63d0\u9ad8\u6210\u529f\u7387\u3002</li>\n    <li>\u5728RoboCasa GR-1\u4e0a\uff0c\u589e\u52a0\u4e0a\u4e0b\u6587\u65f6\u95f4\u4ece0.0\u79d2\u523019.2\u79d2\uff0c\u6210\u529f\u7387\u4ece63.3%\u63d0\u9ad8\u523078.7%\u3002</li>\n    <li>Long-WAM\u5728\u591a\u4e2a\u4efb\u52a1\u4e2d\u8868\u73b0\u51fa\u8272\uff0c\u5305\u62ec\u52a8\u6001\u676f\u5b50\u53e0\u653e\uff0c\u6210\u529f\u7387\u8fbe\u523095%\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u80fd\u591f\u5728\u591a\u79cd\u786c\u4ef6\u4e0a\u5b9e\u65f6\u6267\u884c\uff0c\u652f\u6301\u590d\u6742\u4efb\u52a1\u7684\u9ad8\u5c42\u89c4\u5212\u3002 </li>\n</ul>", "summary_simple": "<ul>\n    <li>Long-WAM is a new framework that helps robots use visual history for real-time control without delays.</li>\n    <li>A longer history of visual data improves robot performance, especially when the model is pretrained in a specific way.</li>\n    <li>Using Long-WAM, the success rate of robots increased significantly when given more visual context.</li>\n    <li>It outperforms other methods in various tests, achieving the best results on multiple benchmarks.</li>\n    <li>Long-WAM can be used in real-time on different hardware setups, enabling complex tasks like dynamic cup stacking with high success rates.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "Long-WAM: Scaling the Context of World-Action Models", "summary": "Real-time robot control demands enough visual history to infer motion and task progress, but processing that history can delay action. We present Long-WAM, a model-system framework for scaling the context of causal world-action models under real-time control constraints. Our central finding is that access to history is not the same as using it: longer histories pay off far more when the video foundation is pretrained autoregressively (AR). We first learn causal prediction from robot and egocentric videos without action labels, then preserve this history-to-future structure during world-action adaptation. On RoboCasa GR-1, increasing context from 0.0 to 19.2 seconds raises success from 63.3% to 78.7%, whereas a bidirectionally pretrained initialization shows no net gain; robot-domain AR pretraining further raises peak success on GR-1 and LIBERO-Long. Long-WAM also achieves the best results among compared methods on LIBERO-Long, RoboTwin 2.0, and DOMINO. Streaming observation encoding, asynchronous execution, and hardware-specific acceleration enable deployment on RTX 5090, DGX Spark, and Jetson AGX Thor without dropping future prediction; on RTX 5090, each action chunk, including future-video latent prediction, takes 107.4 ms. Real-time deployment on Unitree G1 and YAM supports dynamic and long-horizon manipulation, including 95% success on dynamic cup stacking, where Pi0.5 and Fast-WAM succeed in none of 20 trials. As a memory-informed executor, Long-WAM also complements higher-level planning in composite tasks.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/656db3f53dc1d277e5a64410/xydlSuXEJrwor5qFTZzvU.qt"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10528.png", "numComments": 1, "submittedBy": {"_id": "656db3f53dc1d277e5a64410", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/656db3f53dc1d277e5a64410/9kiY2K3MCRcBDk7MrkTBK.png", "fullname": "Wei Huang", "name": "AaronHuangWei", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 19, "isUserFollowing": false}, "organization": {"_id": "60262b67268c201cdc8b7d43", "name": "nvidia", "fullname": "NVIDIA", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/65df9200dc3292a8983e5017/Vs5FPVCH-VZBipV3qKTuy.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.04299", "authors": [{"_id": "6ac445589eb4ee6bd77a9345", "name": "Jinyuan Li", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9346", "name": "Chengsong Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9347", "name": "Langlin Huang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9348", "name": "Donghong Cai", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a9349", "name": "Shiping Gao", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934a", "name": "Yuyi Yang", "hidden": false}, {"_id": "6ac445589eb4ee6bd77a934b", "name": "Jiaxin Huang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "publishedAt": "2026-10-03T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "submittedOnDailyBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "isPro": false, "fullname": "Jinyuan Li", "user": "jinyuan222", "type": "user", "name": "jinyuan222"}, "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "upvotes": 52, "discussionId": "6ac445589eb4ee6bd77a934c", "projectPage": "https://jinyuanli0012.github.io/R-Quest/", "githubRepo": "https://github.com/JinYuanLi0012/R-Quest", "githubRepoAddedBy": "user", "githubStars": 1, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "summary_zh": "<ul>\n    <li>\u81ea\u6211\u8fdb\u5316\u7684\u63a8\u7406\u6a21\u578b\u901a\u8fc7\u751f\u6210\u7684\u95ee\u9898\u8fdb\u884c\u5b66\u4e60\uff0c\u4f46\u91cd\u590d\u81ea\u6211\u8bad\u7ec3\u53ef\u80fd\u5bfc\u81f4\u6027\u80fd\u4e0b\u964d\u3002</li>\n    <li>\u7814\u7a76\u53d1\u73b0\uff0c\u81ea\u751f\u6210\u95ee\u9898\u5b58\u5728\u65e0\u6548\u95ee\u9898\u548c\u91cd\u590d\u53d8\u4f53\u7684\u95ee\u9898\uff0c\u8fd9\u5f71\u54cd\u4e86\u6a21\u578b\u6027\u80fd\u3002</li>\n    <li>\u65e0\u6548\u95ee\u9898\u5728\u8bad\u7ec3\u4e2d\u8d8a\u6765\u8d8a\u591a\uff0c\u800c\u73b0\u6709\u7684\u591a\u6837\u6027\u63a7\u5236\u65b9\u6cd5\u65e0\u6cd5\u6709\u6548\u8bc6\u522b\u6570\u5b66\u4e0a\u7b49\u4ef7\u7684\u95ee\u9898\u3002</li>\n    <li>\u63d0\u51fa\u4e86R-Quest\u65b9\u6cd5\uff0c\u901a\u8fc7\u95ee\u9898\u6709\u6548\u6027\u548c\u65b0\u9896\u6027\u53cd\u9988\u6765\u6307\u5bfc\u81ea\u6211\u8fdb\u5316\u3002</li>\n    <li>R-Quest\u572812\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u6700\u4f73\uff0c\u4e14\u572810\u8f6e\u81ea\u6211\u8fdb\u5316\u4e2d\u4fdd\u6301\u7a33\u5b9a\u6027\u80fd\uff0c\u6700\u7ec8\u8d85\u8d8aR-Zero 17.32\u5206\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Self-evolving reasoning models can learn from their own questions, but repeated training can hurt their performance.</li>\n    <li>The study finds two main issues: an increase in invalid questions and a lack of diversity in questions over time.</li>\n    <li>Invalid questions become more common with each training round, and existing methods miss variations of similar questions.</li>\n    <li>R-Quest is a new approach that helps improve question quality by filtering out invalid ones and encouraging novel questions.</li>\n    <li>R-Quest shows better performance across multiple tests and maintains improvements over many training rounds, outperforming previous methods significantly.</li>\n</ul>"}, "publishedAt": "2026-10-02T20:00:00.000Z", "title": "Questioning the Questions: Sustaining Self-Evolution in Reasoning Models", "summary": "Self-evolving reasoning models learn from their own generated questions, yet repeated self-training can lead to performance collapse. In this paper, we investigate why performance deteriorates over successive rounds and how to sustain self-evolution. Our analysis identifies two recurring quality problems in self-generated questions: invalid questions and repeated variants of the same mathematical questions. First, invalid questions become more prevalent across rounds, and answer-consistency filtering further increases their proportion in training data. Second, existing question diversity controls based on lexical similarity can miss mathematically equivalent questions expressed in different ways, which leads to question diversity collapse in later training rounds. Building on these findings, we introduce R-Quest, which uses question validity and novelty feedback to guide self-evolution. We first train the solver to recognize and reject invalid questions, then use its judgments to guide questioner rewards and filter solver training data. To avoid question repetition, we use a frozen base model to compare sampled question pairs and provide novelty feedback. Empirically, our method consistently achieves the highest average performance on 12 benchmarks in mathematical reasoning, general-domain reasoning, and code generation across two model families. Additionally, R-Quest maintains stable performance gains over ten rounds of self-evolution, peaking in the final round and outperforming R-Zero by 17.32 points.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/64fc20d899123d7698a30e61/jETbBtAg6-jnVU4RPRvZb.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.04299.png", "numComments": 1, "submittedBy": {"_id": "64fc20d899123d7698a30e61", "avatarUrl": "/avatars/9231982cf70a0689f50accedf1004702.svg", "fullname": "Jinyuan Li", "name": "jinyuan222", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 3, "isUserFollowing": false}, "organization": {"_id": "670035f24055c4569f7dd024", "name": "HINT-lab", "fullname": "Huang's INTelligence lab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/64efbf39b3610349e84db417/tbNZtAX3vJeGo2Rag_7ZN.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.18829", "authors": [{"_id": "6acf1130abe004a210f25dc4", "name": "Xuyang Liu", "hidden": false}, {"_id": "6acf1130abe004a210f25dc5", "name": "Shihao Wang", "hidden": false}, {"_id": "6acf1130abe004a210f25dc6", "name": "Xinyu Wei", "hidden": false}, {"_id": "6acf1130abe004a210f25dc7", "name": "Minghan Li", "hidden": false}, {"_id": "6acf1130abe004a210f25dc8", "name": "Zeqing Wang", "hidden": false}, {"_id": "6acf1130abe004a210f25dc9", "name": "Zuhao Yang", "hidden": false}, {"_id": "6acf1130abe004a210f25dca", "name": "Zichen Wen", "hidden": false}, {"_id": "6acf1130abe004a210f25dcb", "name": "Lei Zhang", "hidden": false}], "publishedAt": "2026-10-13T00:00:00.000Z", "submittedOnDailyAt": "2026-10-16T00:00:00.000Z", "title": "OmniCompass: A Holistic Benchmark for Omni-Modal Video Grounding and Understanding", "submittedOnDailyBy": {"_id": "69db8a673114e93a4dbdec28", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/69db8a673114e93a4dbdec28/eJg3LOMGXpPKPa9lrzHtE.jpeg", "isPro": true, "fullname": "PolyU_VCLab", "user": "VCLab-PolyU", "type": "user", "name": "VCLab-PolyU"}, "summary": "With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systematic diagnosis of omni-modal video understanding. We introduce OmniCompass, a holistic benchmark for omni-modal video grounding and understanding. OmniCompass defines two evaluation tracks: OmniCompass-VL assesses vision-language models on tasks requiring visual evidence, while OmniCompass-AV assesses omni-modal models on tasks requiring joint audio-visual evidence. Each track includes three complementary tasks: temporal grounding (TG), spatial grounding (SG), and question answering (QA), assessing when a referenced target appears, where it is, and what happens. QA covers five perception and three reasoning categories in OmniCompass-VL, and three perception and two reasoning categories in OmniCompass-AV. OmniCompass-VL contains 820 videos and 2,460 instances across domains and three duration types: short, medium, and long. A narrative- and audio-rich subset forms OmniCompass-AV with 240 videos and 720 instances. Each instance is evaluated under two paired settings: text-only and text+image, specifying the same target through text and visual-language guidance. All instances are manually annotated with multi-round quality verification. Evaluations of 50 MLLMs show that open-source models still lag behind proprietary counterparts, particularly in audio-visual understanding. Precise temporal and spatial grounding remains challenging even for leading models, and their predictions still exhibit inconsistencies across the paired target specifications.", "upvotes": 51, "discussionId": "6acf1131abe004a210f25dcc", "projectPage": "https://omnicompass.netlify.app/", "githubRepo": "https://github.com/PolyU-VCLab/OmniCompass", "githubRepoAddedBy": "user", "ai_summary": "OmniCompass is a holistic benchmark for omni-modal video grounding and understanding that evaluates vision-language and audio-visual reasoning through temporal grounding, spatial grounding, and question answering tasks.", "ai_keywords": ["multimodal large language models", "video understanding", "temporal grounding", "spatial grounding", "question answering", "audio-visual reasoning", "vision-language models"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 54, "organization": {"_id": "69dba0c8dc88214a5ddca3f2", "name": "VCLab-HKPU", "fullname": "VCLab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/69db8a673114e93a4dbdec28/WgIv-pv3Mt2HBSdoR35eW.png"}, "summary_zh": "<ul>\n    <li>\u968f\u7740\u591a\u6a21\u6001\u5927\u8bed\u8a00\u6a21\u578b\u7684\u5feb\u901f\u53d1\u5c55\uff0c\u8bc4\u4f30\u5176\u89c6\u9891\u7406\u89e3\u80fd\u529b\u53d8\u5f97\u8d8a\u6765\u8d8a\u91cd\u8981\u3002</li>\n    <li>\u6211\u4eec\u4ecb\u7ecd\u4e86OmniCompass\uff0c\u4e00\u4e2a\u5168\u9762\u7684\u89c6\u9891\u5b9a\u4f4d\u548c\u7406\u89e3\u57fa\u51c6\uff0c\u5305\u542b\u4e24\u4e2a\u8bc4\u4f30\u65b9\u5411\uff1a\u89c6\u89c9\u8bed\u8a00\u6a21\u578b\u548c\u97f3\u89c6\u9891\u6a21\u578b\u3002</li>\n    <li>\u6bcf\u4e2a\u65b9\u5411\u5305\u62ec\u4e09\u4e2a\u4e92\u8865\u4efb\u52a1\uff1a\u65f6\u95f4\u5b9a\u4f4d\u3001\u7a7a\u95f4\u5b9a\u4f4d\u548c\u95ee\u7b54\uff0c\u8bc4\u4f30\u76ee\u6807\u51fa\u73b0\u7684\u65f6\u95f4\u3001\u4f4d\u7f6e\u548c\u4e8b\u4ef6\u3002</li>\n    <li>OmniCompass-VL \u5305\u542b820\u4e2a\u89c6\u9891\u548c2460\u4e2a\u5b9e\u4f8b\uff0cOmniCompass-AV \u5305\u542b240\u4e2a\u89c6\u9891\u548c720\u4e2a\u5b9e\u4f8b\uff0c\u6240\u6709\u5b9e\u4f8b\u7ecf\u8fc7\u4eba\u5de5\u6807\u6ce8\u548c\u591a\u8f6e\u8d28\u91cf\u9a8c\u8bc1\u3002</li>\n    <li>\u8bc4\u4f30\u7ed3\u679c\u663e\u793a\uff0c\u5f00\u6e90\u6a21\u578b\u5728\u97f3\u89c6\u9891\u7406\u89e3\u65b9\u9762\u4ecd\u843d\u540e\u4e8e\u4e13\u6709\u6a21\u578b\uff0c\u4e14\u7cbe\u786e\u7684\u65f6\u95f4\u548c\u7a7a\u95f4\u5b9a\u4f4d\u4ecd\u7136\u5177\u6709\u6311\u6218\u6027\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>The paper presents OmniCompass, a new benchmark for evaluating multimodal large language models (MLLMs) in understanding videos.</li>\n    <li>OmniCompass has two tracks: one for vision-language models (OmniCompass-VL) and another for audio-visual models (OmniCompass-AV).</li>\n    <li>Each track includes three tasks: figuring out when (temporal grounding), where (spatial grounding), and answering questions (question answering) about video content.</li>\n    <li>OmniCompass-VL has 820 videos, while OmniCompass-AV has 240 videos, both with various examples from different domains.</li>\n    <li>Results show that open-source models are not performing as well as proprietary ones, especially in understanding audio-visual content.</li>\n</ul>"}, "publishedAt": "2026-10-12T20:00:00.000Z", "title": "OmniCompass: A Holistic Benchmark for Omni-Modal Video Grounding and Understanding", "summary": "With the rapid development of multimodal large language models (MLLMs), evaluating their video understanding capabilities has become increasingly important. Existing video understanding benchmarks cover only part of the evaluation dimensions, limiting systematic diagnosis of omni-modal video understanding. We introduce OmniCompass, a holistic benchmark for omni-modal video grounding and understanding. OmniCompass defines two evaluation tracks: OmniCompass-VL assesses vision-language models on tasks requiring visual evidence, while OmniCompass-AV assesses omni-modal models on tasks requiring joint audio-visual evidence. Each track includes three complementary tasks: temporal grounding (TG), spatial grounding (SG), and question answering (QA), assessing when a referenced target appears, where it is, and what happens. QA covers five perception and three reasoning categories in OmniCompass-VL, and three perception and two reasoning categories in OmniCompass-AV. OmniCompass-VL contains 820 videos and 2,460 instances across domains and three duration types: short, medium, and long. A narrative- and audio-rich subset forms OmniCompass-AV with 240 videos and 720 instances. Each instance is evaluated under two paired settings: text-only and text+image, specifying the same target through text and visual-language guidance. All instances are manually annotated with multi-round quality verification. Evaluations of 50 MLLMs show that open-source models still lag behind proprietary counterparts, particularly in audio-visual understanding. Precise temporal and spatial grounding remains challenging even for leading models, and their predictions still exhibit inconsistencies across the paired target specifications.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.18829.png", "numComments": 1, "submittedBy": {"_id": "69db8a673114e93a4dbdec28", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/69db8a673114e93a4dbdec28/eJg3LOMGXpPKPa9lrzHtE.jpeg", "fullname": "PolyU_VCLab", "name": "VCLab-PolyU", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 9, "isUserFollowing": false}, "organization": {"_id": "69dba0c8dc88214a5ddca3f2", "name": "VCLab-HKPU", "fullname": "VCLab", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/69db8a673114e93a4dbdec28/WgIv-pv3Mt2HBSdoR35eW.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.20571", "authors": [{"_id": "6ad0370daab7978cb679de82", "name": "Weijie Wang", "hidden": false}, {"_id": "6ad0370daab7978cb679de83", "name": "Haomin Zhang", "hidden": false}, {"_id": "6ad0370daab7978cb679de84", "name": "Ye Li", "hidden": false}, {"_id": "6ad0370daab7978cb679de85", "name": "Akide Liu", "hidden": false}, {"_id": "6ad0370daab7978cb679de86", "name": "Zeyu Zhang", "hidden": false}, {"_id": "6ad0370daab7978cb679de87", "name": "Haoyu Zhao", "hidden": false}, {"_id": "6ad0370daab7978cb679de88", "name": "Yefei He", "hidden": false}, {"_id": "6ad0370daab7978cb679de89", "name": "Donny Y. Chen", "hidden": false}, {"_id": "6ad0370daab7978cb679de8a", "name": "Feng Chen", "hidden": false}, {"_id": "6ad0370daab7978cb679de8b", "name": "Bohan Zhuang", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66699aa8a33847217b5a49c7/YgsTMXs-dTVwLakJbrZfc.mp4"], "publishedAt": "2026-10-14T00:00:00.000Z", "submittedOnDailyAt": "2026-10-15T00:00:00.000Z", "title": "Any Time, Any Space: A World-State-Centric Framework for Agentic Video Generation", "submittedOnDailyBy": {"_id": "66699aa8a33847217b5a49c7", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/u8Z-6U8U7ARXOpdBDI7Qm.png", "isPro": false, "fullname": "Weijie Wang", "user": "lhmd", "type": "user", "name": "lhmd"}, "summary": "Long-form agentic video generation must turn a screenplay into shots that remain spatially and temporally consistent across nonconsecutive requests. Passing prompts or recent frames between shots does not provide a shared spatial frame for revisiting a scene or a time-indexed record for replaying an earlier event. We present Any Time, Any Space (ATAS), which compiles a screenplay into shot requests with explicit location, camera, and event-time references. Before generation, it retrieves relevant evidence from a scene memory of registered static geometry and an event memory of dynamic observations indexed by scene, event, and time. After generation, ATAS reconstructs and registers the clip. It updates memory only when review and state checks accept the observation, while film delivery remains independent of memory admission. Across four video generators, ATAS improves all reported cross-shot consistency measures and achieves the highest aggregate benchmark score for each backbone. It also outperforms the compared agents and 3D-guided methods on target-image spatial revisit, leads three event-recapture criteria, and receives the highest human ratings on all six criteria. The video results and code are available on our project page: https://lhmd.top/atas/.", "upvotes": 51, "discussionId": "6ad0370daab7978cb679de8c", "projectPage": "https://lhmd.top/atas/", "githubRepo": "https://github.com/ziplab/ATAS", "githubRepoAddedBy": "user", "githubStars": 65, "organization": {"_id": "61bac2af530e5c78d7b99667", "name": "zju", "fullname": "Zhejiang University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5e1058e9fcf41d740b69966d/7G1xjlxwCdMEmKcxNR0n5.png"}, "summary_zh": "<ul>\n    <li>ATAS\u7cfb\u7edf\u80fd\u591f\u5c06\u5267\u672c\u8f6c\u6362\u4e3a\u89c6\u9891\u955c\u5934\uff0c\u786e\u4fdd\u955c\u5934\u5728\u7a7a\u95f4\u548c\u65f6\u95f4\u4e0a\u4fdd\u6301\u4e00\u81f4\u3002</li>\n    <li>\u7cfb\u7edf\u901a\u8fc7\u573a\u666f\u8bb0\u5fc6\u548c\u4e8b\u4ef6\u8bb0\u5fc6\u6765\u68c0\u7d22\u76f8\u5173\u4fe1\u606f\uff0c\u4ee5\u652f\u6301\u89c6\u9891\u751f\u6210\u3002</li>\n    <li>ATAS\u5728\u8de8\u955c\u5934\u4e00\u81f4\u6027\u65b9\u9762\u6709\u663e\u8457\u6539\u5584\uff0c\u5e76\u5728\u591a\u4e2a\u57fa\u51c6\u6d4b\u8bd5\u4e2d\u8868\u73b0\u6700\u4f73\u3002</li>\n    <li>\u8be5\u7cfb\u7edf\u5728\u76ee\u6807\u56fe\u50cf\u7684\u7a7a\u95f4\u91cd\u8bbf\u548c\u4e8b\u4ef6\u6355\u6349\u65b9\u9762\u4f18\u4e8e\u5176\u4ed6\u6bd4\u8f83\u65b9\u6cd5\u3002</li>\n    <li>ATAS\u83b7\u5f97\u4e86\u4eba\u7c7b\u8bc4\u5ba1\u7684\u6700\u9ad8\u8bc4\u5206\uff0c\u5e76\u4e14\u76f8\u5173\u89c6\u9891\u7ed3\u679c\u548c\u4ee3\u7801\u53ef\u5728\u9879\u76ee\u9875\u9762\u4e0a\u83b7\u53d6\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>ATAS helps create consistent video shots from a screenplay by using specific location and timing information.</li>\n    <li>It uses a memory system that stores details about the scene and events to ensure continuity across different shots.</li>\n    <li>ATAS improves video quality by enhancing cross-shot consistency and achieving better benchmark scores than other methods.</li>\n    <li>It surpasses other agents and techniques in how well it can revisit spatial elements and recapture events.</li>\n    <li>The project provides video results and code for further exploration at its official page.</li>\n</ul>"}, "publishedAt": "2026-10-13T20:00:00.000Z", "title": "Any Time, Any Space: A World-State-Centric Framework for Agentic Video Generation", "summary": "Long-form agentic video generation must turn a screenplay into shots that remain spatially and temporally consistent across nonconsecutive requests. Passing prompts or recent frames between shots does not provide a shared spatial frame for revisiting a scene or a time-indexed record for replaying an earlier event. We present Any Time, Any Space (ATAS), which compiles a screenplay into shot requests with explicit location, camera, and event-time references. Before generation, it retrieves relevant evidence from a scene memory of registered static geometry and an event memory of dynamic observations indexed by scene, event, and time. After generation, ATAS reconstructs and registers the clip. It updates memory only when review and state checks accept the observation, while film delivery remains independent of memory admission. Across four video generators, ATAS improves all reported cross-shot consistency measures and achieves the highest aggregate benchmark score for each backbone. It also outperforms the compared agents and 3D-guided methods on target-image spatial revisit, leads three event-recapture criteria, and receives the highest human ratings on all six criteria. The video results and code are available on our project page: https://lhmd.top/atas/.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/66699aa8a33847217b5a49c7/YgsTMXs-dTVwLakJbrZfc.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.20571.png", "numComments": 1, "submittedBy": {"_id": "66699aa8a33847217b5a49c7", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/noauth/u8Z-6U8U7ARXOpdBDI7Qm.png", "fullname": "Weijie Wang", "name": "lhmd", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 17, "isUserFollowing": false}, "organization": {"_id": "61bac2af530e5c78d7b99667", "name": "zju", "fullname": "Zhejiang University", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/5e1058e9fcf41d740b69966d/7G1xjlxwCdMEmKcxNR0n5.png"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.33568", "authors": [{"_id": "6ae00a6fa5efa215400a7903", "name": "Yihao Hu", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7904", "name": "Zhihao Wen", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7905", "name": "Yitong Lin", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7906", "name": "Siyuan Lu", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7907", "name": "Pan Wang", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7908", "name": "Wei Wu", "hidden": false}, {"_id": "6ae00a6fa5efa215400a7909", "name": "Jiang-Ming Yang", "hidden": false}, {"_id": "6ae00a6fa5efa215400a790a", "name": "Tao Lin", "hidden": false}], "publishedAt": "2026-10-24T00:00:00.000Z", "submittedOnDailyAt": "2026-10-27T00:00:00.000Z", "title": "Trajectory2Gym: Decision-Grounded Compositional Interaction Synthesis for Tool-Use Agents", "submittedOnDailyBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "isPro": false, "fullname": "Yihao Hu", "user": "HU22333", "type": "user", "name": "HU22333"}, "summary": "Successful tool-use trajectories are not necessarily useful supervision. Even successful interactions may underrepresent multi-step dependencies or contain actions that are unjustified by the information visible to the agent at decision time. We identify two coupled requirements for effective trajectory supervision: compositional coverage, so that important observation-action dependencies are represented, and decision grounding, so that each supervised action is supported by the learner-visible interaction history. We introduce Trajectory2Gym, which constructs executable interactions around under-supported compositional structures and derives supervision only from grounded decisions in their realized executions. Structural-support selection allocates the resulting experience, while parent-normalized supervised fine-tuning preserves the semantic interaction as the unit of training weight. This reframes trajectory generation as the deliberate construction of learnable interaction experience, rather than the collection of successful trajectories. Across five Qwen3 scales, Trajectory2Gym improves Tau1, Tau2, and BFCL at every tested scale, increasing the equal-weight three-benchmark mean by 16.9-29.8 percentage points. The gains are strongest in stateful and multi-turn interaction, where later decisions depend on earlier observations and feedback. Our results suggest that scaling tool-use agents depends not only on collecting more successful trajectories, but on constructing interactions whose dependencies are represented and whose decisions are learnable from the agent's visible history.", "upvotes": 51, "discussionId": "6ae00a70a5efa215400a790b", "projectPage": "https://yihaohu0118.github.io/Trajectory2Gym-page/", "githubRepo": "https://github.com/yihaohu0118/Trajectory2Gym", "githubRepoAddedBy": "user", "ai_summary": "Trajectory2Gym improves tool-use training by constructing interactions with compositional coverage and decision grounding rather than collecting successful trajectories.", "ai_keywords": ["compositional coverage", "decision grounding", "Trajectory2Gym", "structural-support selection", "parent-normalized supervised fine-tuning", "multi-turn interaction", "tool-use agents"], "ai_summary_model": "thinkingmachines/Inkling-Small", "githubStars": 2, "organization": {"_id": "68d4ae9941614425f8aa7490", "name": "ant-intl", "fullname": "ant-international", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68e9c86d2551cb38000fa77c/qG2KcieHqYFuWXi2-weuP.jpeg"}, "summary_zh": "<ul>\n    <li>\u6210\u529f\u7684\u5de5\u5177\u4f7f\u7528\u8f68\u8ff9\u4e0d\u4e00\u5b9a\u80fd\u63d0\u4f9b\u6709\u6548\u7684\u76d1\u7763\u3002</li>\n    <li>\u6709\u6548\u76d1\u7763\u9700\u8981\u4e24\u4e2a\u6761\u4ef6\uff1a\u7ec4\u5408\u8986\u76d6\u548c\u51b3\u7b56\u57fa\u7840\u3002</li>\n    <li>Trajectory2Gym \u53ef\u4ee5\u521b\u5efa\u53ef\u6267\u884c\u7684\u4ea4\u4e92\uff0c\u57fa\u4e8e\u771f\u5b9e\u6267\u884c\u7684\u51b3\u7b56\u63d0\u4f9b\u76d1\u7763\u3002</li>\n    <li>\u8be5\u65b9\u6cd5\u5728\u591a\u9879\u6d4b\u8bd5\u4e2d\u63d0\u9ad8\u4e86\u6027\u80fd\uff0c\u5c24\u5176\u662f\u5728\u9700\u8981\u4f9d\u8d56\u5386\u53f2\u89c2\u5bdf\u548c\u53cd\u9988\u7684\u4e92\u52a8\u4e2d\u3002</li>\n    <li>\u6784\u5efa\u5de5\u5177\u4f7f\u7528\u4ee3\u7406\u7684\u5173\u952e\u5728\u4e8e\u521b\u5efa\u6709\u4f9d\u8d56\u5173\u7cfb\u7684\u4ea4\u4e92\uff0c\u800c\u4e0d\u662f\u5355\u7eaf\u6536\u96c6\u6210\u529f\u7684\u8f68\u8ff9\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Successful tool-use trajectories may not always provide effective learning supervision.</li>\n    <li>Two key requirements for good supervision are: covering important observation-action links and ensuring decisions are based on what the agent can see.</li>\n    <li>Trajectory2Gym is a new method that focuses on creating interactions that support learning from these requirements.</li>\n    <li>This method shows significant improvements in performance across various tests, especially in complex interactions where past actions influence future decisions.</li>\n    <li>Effective scaling of tool-using agents relies on building meaningful interactions rather than just gathering successful examples.</li>\n</ul>"}, "publishedAt": "2026-10-23T20:00:00.000Z", "title": "Trajectory2Gym: Decision-Grounded Compositional Interaction Synthesis for Tool-Use Agents", "summary": "Successful tool-use trajectories are not necessarily useful supervision. Even successful interactions may underrepresent multi-step dependencies or contain actions that are unjustified by the information visible to the agent at decision time. We identify two coupled requirements for effective trajectory supervision: compositional coverage, so that important observation-action dependencies are represented, and decision grounding, so that each supervised action is supported by the learner-visible interaction history. We introduce Trajectory2Gym, which constructs executable interactions around under-supported compositional structures and derives supervision only from grounded decisions in their realized executions. Structural-support selection allocates the resulting experience, while parent-normalized supervised fine-tuning preserves the semantic interaction as the unit of training weight. This reframes trajectory generation as the deliberate construction of learnable interaction experience, rather than the collection of successful trajectories. Across five Qwen3 scales, Trajectory2Gym improves Tau1, Tau2, and BFCL at every tested scale, increasing the equal-weight three-benchmark mean by 16.9-29.8 percentage points. The gains are strongest in stateful and multi-turn interaction, where later decisions depend on earlier observations and feedback. Our results suggest that scaling tool-use agents depends not only on collecting more successful trajectories, but on constructing interactions whose dependencies are represented and whose decisions are learnable from the agent's visible history.", "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.33568.png", "numComments": 1, "submittedBy": {"_id": "67e40cea6d0207b1fa43c826", "avatarUrl": "https://cdn-avatars.huggingface.co/v1/production/uploads/no-auth/_OzAJCjFC49dEkHZm4AQb.png", "fullname": "Yihao Hu", "name": "HU22333", "type": "user", "isPro": false, "isHf": false, "isHfAdmin": false, "isMod": false, "isUserFollowing": false}, "organization": {"_id": "68d4ae9941614425f8aa7490", "name": "ant-intl", "fullname": "ant-international", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/68e9c86d2551cb38000fa77c/qG2KcieHqYFuWXi2-weuP.jpeg"}, "isAuthorParticipating": false}, {"paper": {"id": "2610.10524", "authors": [{"_id": "6ac6fef64eb8005165aed3e0", "name": "Jiyoung Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e1", "name": "Paul Hyunbin Cho", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e2", "name": "Jisu Nam", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e3", "name": "Donghoon Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e4", "name": "Hyunsung Go", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e5", "name": "Yeonkyeong Lee", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e6", "name": "Hansaem Kim", "hidden": false}, {"_id": "6ac6fef64eb8005165aed3e7", "name": "Seungryong Kim", "hidden": false}], "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "publishedAt": "2026-10-07T00:00:00.000Z", "submittedOnDailyAt": "2026-10-08T00:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "submittedOnDailyBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "isPro": true, "fullname": "jee0", "user": "chimaharicox", "type": "user", "name": "chimaharicox"}, "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "upvotes": 51, "discussionId": "6ac6fef64eb8005165aed3e8", "projectPage": "https://cvlab-kaist.github.io/GRACE/", "githubRepo": "https://github.com/cvlab-kaist/GRACE", "githubRepoAddedBy": "user", "githubStars": 12, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "summary_zh": "<ul>\n    <li>\u9ad8\u538b\u7f29\u89c6\u9891\u81ea\u7f16\u7801\u5668\u80fd\u52a0\u901f\u89c6\u9891\u6269\u6563\u6a21\u578b\uff0c\u4f46\u8bad\u7ec3\u6bd4\u8f83\u56f0\u96be\u3002</li>\n    <li>\u66f4\u9ad8\u7684\u538b\u7f29\u6bd4\u4f1a\u964d\u4f4e\u91cd\u5efa\u8d28\u91cf\uff0c\u9700\u8981\u66f4\u591a\u901a\u9053\u6765\u6062\u590d\uff0c\u5f71\u54cd\u6a21\u578b\u6536\u655b\u3002</li>\n    <li>\u6211\u4eec\u63d0\u51fa\u4e86GRACE\u6846\u67b6\uff0c\u65e8\u5728\u5728\u538b\u7f29\u9884\u8bad\u7ec3\u89c6\u9891\u81ea\u7f16\u7801\u5668\u65f6\u4fdd\u6301\u4e0e\u6269\u6563Transformer\u7684\u517c\u5bb9\u6027\u3002</li>\n    <li>GRACE\u4f7f\u7528\u4e24\u9636\u6bb5\u65b9\u6cd5\uff0c\u901a\u8fc7\u51bb\u7ed3\u57fa\u7840\u6f5c\u53d8\u91cf\u5e76\u5b66\u4e60\u6b8b\u5dee\u6f5c\u53d8\u91cf\u6765\u4f18\u5316\u751f\u6210\u6548\u679c\u3002</li>\n    <li>GRACE\u4f7fWan2.1-I2V-14B\u7684Token\u6570\u91cf\u51cf\u5c118\u500d\uff0c\u5ef6\u8fdf\u51cf\u5c1111.1\u500d\uff0c\u540c\u65f6\u4fdd\u6301\u751f\u6210\u8d28\u91cf\u3002</li>\n</ul>", "summary_simple": "<ul>\n    <li>Highly compressed video autoencoders can speed up video diffusion models by using fewer tokens.</li>\n    <li>Training these autoencoders is difficult because high compression reduces video quality and requires more channels.</li>\n    <li>To solve this, the GRACE framework compresses a pretrained video autoencoder while ensuring it works well with the pretrained DiT model.</li>\n    <li>GRACE uses a two-stage process to keep important information from the original model and fine-tunes the DiT for better performance.</li>\n    <li>This approach significantly reduces token count and latency while maintaining video quality during generation.</li>\n</ul>"}, "publishedAt": "2026-10-06T20:00:00.000Z", "title": "GRACE: Generation-aware latent compression for efficient video generation", "summary": "Highly compressed video autoencoders offer an effective way to accelerate video diffusion models, as the Diffusion Transformer (DiT) operates on far fewer tokens. However, such autoencoders are challenging to train, since a higher compression ratio degrades reconstruction quality and recovering it requires more channels, which is known to slow the convergence of the DiT. The compressed latent also differs from the one the DiT was trained on, so the pretrained DiT must be either retrained from scratch or adapted at considerable cost. Compressing the autoencoder the DiT was trained with appears to preserve compatibility, yet optimizing it for reconstruction alone still shifts the latent away from the distribution the DiT has learned. To address this, we propose Generation-Aware Latent Compression for Efficient Video Generation (GRACE), a two-stage framework that compresses a pretrained video autoencoder while keeping it compatible with the pretrained DiT. Specifically, we keep a frozen base latent from the pretrained encoder and learn a residual latent for the information lost under stronger compression, while aligning the compressed latent with the pretrained latent in the feature space of the frozen DiT so that the autoencoder is optimized for generation. We then adapt the DiT with lightweight fine-tuning and asymmetric denoising, where the base is denoised ahead of the residual. GRACE reduces the token count of Wan2.1-I2V-14B by 8x and its latency by 11.1x at 480x832x81, while matching the generation quality of the pretrained pipeline before compression on VBench.", "mediaUrls": ["https://cdn-uploads.huggingface.co/production/uploads/65cb4ce4d5822659ec122119/vuLISuzr1b3izauYyA274.mp4"], "thumbnail": "https://cdn-thumbnails.huggingface.co/social-thumbnails/papers/2610.10524.png", "numComments": 1, "submittedBy": {"_id": "65cb4ce4d5822659ec122119", "avatarUrl": "/avatars/b7e4b4c6914b32e097648dd5991dec26.svg", "fullname": "jee0", "name": "chimaharicox", "type": "user", "isPro": true, "isHf": false, "isHfAdmin": false, "isMod": false, "followerCount": 1, "isUserFollowing": false}, "organization": {"_id": "6475760c33192631bad2bb38", "name": "kaist-ai", "fullname": "KAIST AI", "avatar": "https://cdn-avatars.huggingface.co/v1/production/uploads/6469949654873f0043b09c22/aaZFiyXe1qR-Dmy_xq67m.png"}, "isAuthorParticipating": false}]
};
